// Content for Fair Play World (node g10, ages 6-9, Chapter 2): NEW v2 build to GDD 10 (mechanic-embodying),
// the fairness game in the Gender & Respect thread. "Everyone gets a fair turn." 84 researched, India-grounded
// scenarios across six categories, each encoded as one of the shared v2 play actions (branch / reflect /
// strike-rewrite / sort / role-play / match / build / spot): no binary "tap the right card", led by fairness
// DILEMMAS (branch: decide the fair move, see the ripple, get a debrief), the fair-chore-chart builder
// (build), and spot-the-unfair-rule scenes (spot). Teaches fairness as gender equality: what fair means
// (a turn / what you need), sharing chores by turns not gender (India's chore gap, named plainly), fair
// opportunity, equity (fair can mean meeting different needs), and spotting/standing up to unfair rules.
// DECIDE NOT BE TOLD (multiple good moves; the child reasons it out); BOTH DIRECTIONS (frees girls toward
// chances AND boys toward home help; no gender villain); SAFE TO BE WRONG (gentle debriefs, no buzzer);
// family-safe ("everyone helps the family", an elder can nod to). Builds on g07 (What Makes Me, Me); prereq
// g41 (Heart Smart). Rendered by the shared engine (components/games/v2-engine.tsx).
// gameId "fair-play" (the engine-host registry id; the GDD/library "fair-play-world" is design-doc only). DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // What fair means (everyone gets a turn / what they need)
  {"id":"fp-001","cat":"what-is-fair","type":"sort","hook":"Lensy: welcome to Fair Play World! Sort these into fair or not fair.","items":[{"id":"a","text":"Everyone gets a turn on the swing"},{"id":"b","text":"One kid hogs the swing all break"},{"id":"c","text":"Sharing the snacks equally"},{"id":"d","text":"Only my friends get any"},{"id":"e","text":"Letting the next in line go"},{"id":"f","text":"Cutting ahead of everyone"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair usually means everyone gets a turn or a share.","persona":"any","source":"fairness development"},
  {"id":"fp-002","cat":"what-is-fair","type":"reflect","hook":"Lensy: what does 'fair' feel like to you?","prompt":"Pick one.","options":["Everyone gets a turn","No one's left out","People get what they need"],"affirm":"Fair feels like everyone matters, that's the heart of it.","relearn":"Fairness means everyone matters and no one's left out.","persona":"Ananya","source":"fairness"},
  {"id":"fp-003","cat":"what-is-fair","type":"strike-rewrite","hook":"\"Fair means I always get my way.\"","myth":{"un":"Fair means I always get what I want.","re":"Fair means everyone gets a turn or a share, not just me.","why":"Fairness is about everyone, not only you."},"relearn":"Fair is about everyone, not just me getting my way.","persona":"any","source":"fairness"},
  {"id":"fp-004","cat":"what-is-fair","type":"branch","hook":"Two of you want the last samosa.","options":[{"text":"Split it or take turns next time","consequence":"Both of you feel it was fair.","outcome":"fair","best":true},{"text":"Grab it all","consequence":"You win once, but it doesn't feel fair to your friend.","outcome":"unfair"}],"debrief":"Sharing or taking turns keeps things fair for everyone.","relearn":"Splitting or taking turns is a fair fix.","persona":"any","source":"fairness"},
  {"id":"fp-005","cat":"what-is-fair","type":"match","hook":"Match the situation to the fair fix.","pairs":[{"left":"One ball, many players","right":"Take turns"},{"left":"A big cake","right":"Equal slices"},{"left":"One person did all the work","right":"They get a say in the prize"},{"left":"A kid who can't see over the wall","right":"A box to stand on"},{"left":"Only one kid ever chooses","right":"Rotate who picks"}],"relearn":"Different situations have fair fixes: turns, equal shares, a say, a box.","persona":"any","source":"fairness"},
  {"id":"fp-006","cat":"what-is-fair","type":"reflect","hook":"Lensy: is fair the same as kind?","prompt":"What do you think?","options":["They go together","Fair is part of kind","Both matter"],"affirm":"Fairness and kindness work together to make everyone feel okay.","relearn":"Being fair is one way of being kind.","persona":"any","source":"values"},
  {"id":"fp-007","cat":"what-is-fair","type":"sort","hook":"Sort: a fair rule, or an unfair rule?","items":[{"id":"a","text":"Whoever's next gets a turn"},{"id":"b","text":"Only boys go first, always"},{"id":"c","text":"We rotate who chooses the game"},{"id":"d","text":"The loudest kid always decides"},{"id":"e","text":"Everyone gets one fair vote"},{"id":"f","text":"Only the captain's friends play"}],"bins":[{"id":"fair","label":"Fair rule","valence":"pos"},{"id":"no","label":"Unfair rule","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair rules give everyone a chance; unfair ones favour a few.","persona":"Ananya","source":"fairness / rules"},
  {"id":"fp-008","cat":"what-is-fair","type":"branch","hook":"You're picking teams and one kid is always picked last.","options":[{"text":"Mix it up so everyone gets picked","consequence":"That kid feels included; teams are still fun.","outcome":"fair","best":true},{"text":"Leave them till last again","consequence":"They feel rubbish, and it wasn't their fault.","outcome":"unfair"}],"debrief":"Fair picking means no one is always left till last.","relearn":"Fair teams don't leave the same kid out every time.","persona":"any","source":"fairness / inclusion"},
  {"id":"fp-009","cat":"what-is-fair","type":"reflect","hook":"Lensy: have you ever felt something was unfair?","prompt":"How did it feel?","options":["Frustrating","Not nice","Like I wasn't counted"],"affirm":"That feeling is your fairness-sense working. It helps you put things right.","relearn":"Noticing unfairness is the first step to fixing it.","persona":"Ananya","source":"justice sensitivity"},
  {"id":"fp-010","cat":"what-is-fair","type":"strike-rewrite","hook":"\"Rules can't be changed, even unfair ones.\"","myth":{"un":"Unfair rules can never be changed.","re":"People can change unfair rules to fairer ones.","why":"Rules are made by people, and can be improved."},"relearn":"Unfair rules can be changed to fair ones.","persona":"Ananya","source":"rights / agency"},
  {"id":"fp-011","cat":"what-is-fair","type":"sort","hook":"Sort: this helps everyone get a fair go, or blocks it?","items":[{"id":"a","text":"Taking turns to speak"},{"id":"b","text":"Talking over everyone"},{"id":"c","text":"A turn-list for the tablet"},{"id":"d","text":"One kid keeping the tablet all day"},{"id":"e","text":"Letting a quiet kid have a say"},{"id":"f","text":"Cutting people off mid-sentence"}],"bins":[{"id":"help","label":"Fair go","valence":"pos"},{"id":"block","label":"Blocks it","valence":"neg"}],"key":{"a":"help","b":"block","c":"help","d":"block","e":"help","f":"block"},"relearn":"Turns and turn-lists give everyone a fair go.","persona":"any","source":"fairness"},
  {"id":"fp-012","cat":"what-is-fair","type":"build","hook":"Build the rules for Fair Play World.","prompt":"Pick the fair rules.","pieces":["everyone gets a turn","share what we can","no one left out","help those who need it","loudest always wins"],"mode":"assemble","key":["everyone gets a turn","share what we can","no one left out","help those who need it"],"relearn":"Fair Play World runs on turns, sharing, including everyone and helping.","persona":"any","source":"fairness"},
  // Sharing chores fairly (everyone helps, not by gender)
  {"id":"fp-013","cat":"chores-shared","type":"strike-rewrite","hook":"\"Chores are girls' work.\"","myth":{"un":"Chores are girls' work.","re":"Everyone in the family shares the chores, whatever their gender.","why":"A home runs when everyone helps."},"relearn":"Chores are everyone's, not just girls'.","persona":"Ananya","source":"India chore gap"},
  {"id":"fp-014","cat":"chores-shared","type":"branch","hook":"Your brother plays while your sister does all the housework.","options":[{"text":"Say \"let's all take turns with the chores\"","consequence":"The work is shared; it's fair and faster.","outcome":"fair","best":true},{"text":"Let it carry on","consequence":"One kid carries it all, day after day.","outcome":"unfair"}],"debrief":"In India, girls do about 40% more chores than boys, sharing fixes that.","relearn":"Chores shared by turns, not by gender, is fair.","persona":"Ananya","source":"India chore gap"},
  {"id":"fp-015","cat":"chores-shared","type":"sort","hook":"Sort the chore lines: fair for all, or an unfair myth?","items":[{"id":"a","text":"Anyone can cook"},{"id":"b","text":"We all fix shelves in turns"},{"id":"c","text":"Washing up is only girls' work"},{"id":"d","text":"Brothers care for siblings too"},{"id":"e","text":"Everyone sweeps the courtyard"},{"id":"f","text":"Boys don't iron clothes"}],"bins":[{"id":"fair","label":"Fair for all 💚","valence":"pos"},{"id":"myth","label":"Unfair myth 🛑","valence":"neg"}],"key":{"a":"fair","b":"fair","c":"myth","d":"fair","e":"fair","f":"myth"},"relearn":"Every chore can be done by anyone, of any gender.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-016","cat":"chores-shared","type":"build","hook":"Build a fair family chore chart.","prompt":"Give everyone a turn at each job.","pieces":["amma cooks Mon","appa cooks Tue","brother washes up","sister fixes the bulb","everyone tidies"],"mode":"assemble","key":["amma cooks Mon","appa cooks Tue","brother washes up","sister fixes the bulb","everyone tidies"],"relearn":"A fair chart rotates jobs so no one's stuck with all of them.","persona":"Sunita","source":"India joint family / fairness"},
  {"id":"fp-017","cat":"chores-shared","type":"branch","hook":"It's festival prep: the girls cook while the boys watch TV.","options":[{"text":"Say \"everyone helps the family\" and rope the boys in","consequence":"Prep's faster; everyone shares the fun and work.","outcome":"fair","best":true},{"text":"Let the girls do it all","consequence":"The girls miss the fun and rest.","outcome":"unfair"}],"debrief":"\"Everyone helps the family\" is a fairness even elders accept.","relearn":"Festival and home work is for everyone, not just girls.","persona":"Sunita","source":"India / gender-equal caregiving"},
  {"id":"fp-018","cat":"chores-shared","type":"strike-rewrite","hook":"\"Boys shouldn't have to help at home.\"","myth":{"un":"Boys shouldn't have to help at home.","re":"Boys help at home just like everyone else.","why":"Helping is part of being in a family."},"relearn":"Boys do chores too; everyone helps.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-019","cat":"chores-shared","type":"role-play","hook":"You want chores shared more fairly at home.","setup":"Ask kindly. Say:","yourLine":[{"text":"\"Can we make a turn-by-turn chore chart so it's fair?\"","best":true},{"text":"Say nothing and feel cross"}],"relearn":"Asking for a fair chore plan is reasonable and brave.","persona":"Ananya","source":"voice / agency"},
  {"id":"fp-020","cat":"chores-shared","type":"reflect","hook":"Lensy: when chores are shared fairly, who has time to study and play?","prompt":"What do you think?","options":["Everyone","Both girls and boys","All of us"],"affirm":"Sharing chores fairly means everyone gets time to study, rest and play.","relearn":"Fair chores free up everyone's time for school and play.","persona":"Ananya","source":"India chore gap / education"},
  {"id":"fp-021","cat":"chores-shared","type":"sort","hook":"Sort: fair chore-sharing, or unfair?","items":[{"id":"a","text":"Everyone takes a turn"},{"id":"b","text":"Only the girls clean up"},{"id":"c","text":"Dad and son cook dinner"},{"id":"d","text":"Boys never lift a finger"},{"id":"e","text":"The chart rotates each week"},{"id":"f","text":"Sister does the boys' chores too"}],"bins":[{"id":"fair","label":"Fair 💚","valence":"pos"},{"id":"no","label":"Unfair 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair homes share the work across everyone.","persona":"Sunita","source":"fairness"},
  {"id":"fp-022","cat":"chores-shared","type":"branch","hook":"A friend says \"my sister does my chores for me.\"","options":[{"text":"Say \"that's not really fair to her, want to swap sometimes?\"","consequence":"Your friend sees it and starts sharing.","outcome":"fair","best":true},{"text":"Say \"lucky you!\"","consequence":"His sister keeps doing double; that's unfair."}],"debrief":"One kid doing another's chores isn't fair to them.","relearn":"It's not fair for one kid to carry another's chores.","persona":"Ananya","source":"fairness"},
  {"id":"fp-023","cat":"chores-shared","type":"match","hook":"Match the chore to the fair way to decide who does it. (Trick: it rotates!)","pairs":[{"left":"Monday cooking","right":"Whoever's turn it is"},{"left":"Taking out the rubbish","right":"The next on the rota"},{"left":"Helping a sibling study","right":"Whoever is free"},{"left":"Washing the dishes","right":"Shared, a bit each"},{"left":"Folding the clothes","right":"Everyone together"}],"relearn":"Chores rotate by turns, not fixed by gender.","persona":"Sunita","source":"gender-equal caregiving"},
  {"id":"fp-024","cat":"chores-shared","type":"reflect","hook":"Lensy: would you like a fairer chore deal at home? It's okay to want that.","prompt":"What do you think?","options":["Yes","It'd feel fairer","I'd like to share"],"affirm":"Wanting fair chores is reasonable, you can talk to your family about it.","relearn":"It's okay to want and ask for fair chores.","persona":"Ananya","source":"agency"},
  {"id":"fp-025","cat":"chores-shared","type":"strike-rewrite","hook":"\"Helping at home is a waste of a boy's time.\"","myth":{"un":"Helping at home wastes a boy's time.","re":"Learning to cook, clean and care helps every kid for life.","why":"Everyone needs these life skills."},"relearn":"Home skills are valuable for everyone to learn.","persona":"any","source":"life skills"},
  {"id":"fp-026","cat":"chores-shared","type":"branch","hook":"Capstone-style: you notice chores at home aren't shared fairly.","options":[{"text":"Suggest a family chat and a fair chart","consequence":"The family tries it; things get fairer over time.","outcome":"changemaker","best":true},{"text":"Just accept it","consequence":"Speaking up, kindly, is how unfair things change."}],"debrief":"You can be the one who starts a fairer system at home.","relearn":"You can help make chores fairer at home.","persona":"Ananya","source":"agency / changemaking"},
  {"id":"fp-027","cat":"chores-shared","type":"reflect","hook":"Lensy: sharing chores fairly is a small act with a big effect. Agree?","prompt":"What do you think?","options":["Yes","It frees everyone","Big effect"],"affirm":"Fair chores give everyone, especially girls, time to learn and dream.","relearn":"Fair chores at home ripple out into fairer chances in life.","persona":"Ananya","source":"India chore gap"},
  // Fair opportunity (who gets to play, lead, learn, rest)
  {"id":"fp-028","cat":"fair-opportunity","type":"branch","hook":"Only boys are being picked to use the new science kit.","options":[{"text":"Say \"girls should get a turn too\"","consequence":"Everyone gets a go; the best ideas come from all.","outcome":"fair","best":true},{"text":"Let only boys use it","consequence":"Girls miss out on a chance for no good reason.","outcome":"unfair"}],"debrief":"Fair opportunity means everyone gets a chance to try.","relearn":"Opportunities should be open to everyone, not one gender.","persona":"Ananya","source":"gender equality / opportunity"},
  {"id":"fp-029","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Boys get first chance at the good stuff.\"","myth":{"un":"Boys get first chance at the best opportunities.","re":"Everyone deserves a fair chance, regardless of gender.","why":"Talent and interest aren't gendered."},"relearn":"Fair chances go to everyone, not boys first.","persona":"Ananya","source":"gender equality"},
  {"id":"fp-030","cat":"fair-opportunity","type":"sort","hook":"Sort: a fair chance, or an unfair head-start?","items":[{"id":"a","text":"Everyone tries out for the team"},{"id":"b","text":"Only boys allowed to try out"},{"id":"c","text":"Picking the best, any gender"},{"id":"d","text":"Girls can only watch"},{"id":"e","text":"Names drawn, anyone can be picked"},{"id":"f","text":"The coach only ever picks his nephew"}],"bins":[{"id":"fair","label":"Fair chance","valence":"pos"},{"id":"no","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair chances are open to all; unfair ones shut people out.","persona":"any","source":"opportunity"},
  {"id":"fp-031","cat":"fair-opportunity","type":"branch","hook":"The class captain is always a boy 'because that's how it's done'.","options":[{"text":"Say \"let's choose the best leader, any gender\"","consequence":"A great captain is picked on merit.","outcome":"fair","best":true},{"text":"Keep it boys-only","consequence":"Good leaders are skipped for no reason.","outcome":"unfair"}],"debrief":"Leadership chances should be open to everyone.","relearn":"Anyone can lead; pick on skill, not gender.","persona":"Ananya","source":"leadership / equality"},
  {"id":"fp-032","cat":"fair-opportunity","type":"role-play","hook":"You want a fair chance at something only boys are getting.","setup":"Speak up. Say:","yourLine":[{"text":"\"I'd like a fair turn too, please.\"","best":true},{"text":"Stay quiet and miss out"}],"relearn":"Asking for a fair turn is your right.","persona":"Ananya","source":"voice / agency"},
  {"id":"fp-033","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Some kids just don't deserve a turn.\"","myth":{"un":"Some kids don't deserve a chance.","re":"Everyone deserves a fair chance to try.","why":"You can't shine if you're never given a go."},"relearn":"Everyone deserves a fair chance to try.","persona":"any","source":"opportunity"},
  {"id":"fp-034","cat":"fair-opportunity","type":"reflect","hook":"Lensy: a fair chance to try, does everyone deserve one?","prompt":"What do you think?","options":["Yes","Everyone","Of course"],"affirm":"Yes, a fair chance to try is something everyone deserves.","relearn":"Everyone deserves a fair chance.","persona":"any","source":"opportunity"},
  {"id":"fp-035","cat":"fair-opportunity","type":"branch","hook":"Your friend never gets to choose the game because they're quiet.","options":[{"text":"Say \"your turn to choose today\"","consequence":"They light up; the group tries something new.","outcome":"fair","best":true},{"text":"Let the loud kids decide again","consequence":"The quiet friend never gets a say."}],"debrief":"Fair opportunity includes the quiet kids too.","relearn":"Give quieter kids a fair turn to choose.","persona":"any","source":"inclusion"},
  {"id":"fp-036","cat":"fair-opportunity","type":"match","hook":"Match the chance to who should get it. (Trick: anyone who wants it!)","pairs":[{"left":"Lead the project","right":"Anyone, by turns"},{"left":"Try the new instrument","right":"Anyone keen to learn"},{"left":"Represent the class","right":"Anyone, fairly chosen"},{"left":"Carry the school flag","right":"A different kid each week"},{"left":"Answer on the quiz team","right":"Whoever knows it"}],"relearn":"Opportunities belong to anyone who wants a fair shot.","persona":"any","source":"opportunity"},
  {"id":"fp-037","cat":"fair-opportunity","type":"reflect","hook":"Lensy: when everyone gets a fair chance, who wins?","prompt":"What do you think?","options":["Everyone","The whole group","We all do"],"affirm":"When chances are fair, the whole group gets everyone's best.","relearn":"Fair chances make the whole group better.","persona":"any","source":"equality"},
  {"id":"fp-038","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Girls shouldn't get the same chances because they'll just do chores later.\"","myth":{"un":"Girls don't need the same chances.","re":"Girls deserve the very same chances to learn, lead and dream.","why":"Their futures are as wide as anyone's."},"relearn":"Girls deserve exactly the same chances as boys.","persona":"Ananya","source":"gender equality / India"},
  {"id":"fp-039","cat":"fair-opportunity","type":"branch","hook":"There's money for one kid's extra class; the son's assumed to get it.","options":[{"text":"Say \"could we choose fairly, by who wants it most?\"","consequence":"The chance goes to whoever will use it.","outcome":"fair","best":true},{"text":"Assume the son should get it","consequence":"A keen daughter might miss out unfairly."}],"debrief":"Family chances should go fairly, not default to the boy.","relearn":"Share opportunities at home fairly, not by gender.","persona":"Ananya","source":"India / gender equality"},
  // Fair isn't always 'the same' (needs differ)
  {"id":"fp-040","cat":"equal-vs-equity","type":"branch","hook":"Two friends watch a match over a wall; one's too short to see.","options":[{"text":"Give the shorter friend a box to stand on","consequence":"Now both can see; that's truly fair.","outcome":"equity","best":true},{"text":"Give them both the same-size box","consequence":"The tall one still sees, the short one can't."}],"debrief":"Fair sometimes means different help so everyone can join.","relearn":"Fair isn't always 'the same'; it's each getting what they need.","persona":"any","source":"equity"},
  {"id":"fp-041","cat":"equal-vs-equity","type":"strike-rewrite","hook":"\"Fair means everyone gets exactly the same, always.\"","myth":{"un":"Fair always means exactly the same for everyone.","re":"Sometimes fair means giving people what they each need.","why":"Different needs need different help."},"relearn":"Fair can mean meeting different needs, not identical shares.","persona":"any","source":"equity"},
  {"id":"fp-042","cat":"equal-vs-equity","type":"sort","hook":"Sort: fair (meets needs), or only looks equal?","items":[{"id":"a","text":"A kid who can't see gets glasses"},{"id":"b","text":"Everyone runs the same with a hurt leg"},{"id":"c","text":"Extra help for someone struggling"},{"id":"d","text":"Same homework, no help ever"},{"id":"e","text":"Front seat for who can't hear well"},{"id":"f","text":"Same tiny print for all, can't read it"}],"bins":[{"id":"fair","label":"Fair 💚","valence":"pos"},{"id":"no","label":"Looks equal 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Meeting needs is fair, even when it's not identical.","persona":"any","source":"equity"},
  {"id":"fp-043","cat":"equal-vs-equity","type":"branch","hook":"A new classmate doesn't speak the language well yet.","options":[{"text":"Give them extra help and patience","consequence":"They catch up and join in; that's fair.","outcome":"equity","best":true},{"text":"Expect them to manage alone","consequence":"Same treatment isn't fair when needs differ."}],"debrief":"Extra help for different needs is fairness, not favouritism.","relearn":"Helping someone who needs more is fair.","persona":"Kabir-type","source":"equity / inclusion"},
  {"id":"fp-044","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: is giving someone extra help when they need it fair?","prompt":"What do you think?","options":["Yes","It meets their need","That's fair"],"affirm":"Yes, helping someone meet their need is real fairness.","relearn":"Extra help for real needs is fair, not unfair.","persona":"any","source":"equity"},
  {"id":"fp-045","cat":"equal-vs-equity","type":"match","hook":"Match the person to the fair help.","pairs":[{"left":"Can't reach the shelf","right":"A step-stool"},{"left":"Can't hear well","right":"A seat at the front"},{"left":"New to the game","right":"A quick how-to"},{"left":"Can't see the board","right":"A pair of glasses"},{"left":"Reads slower than others","right":"A little more time"}],"relearn":"Fair help fits what each person actually needs.","persona":"any","source":"equity"},
  {"id":"fp-046","cat":"equal-vs-equity","type":"branch","hook":"Your team has a younger, smaller player.","options":[{"text":"Adjust so they can join in fairly","consequence":"They play and have fun; the team's kinder and stronger.","outcome":"equity","best":true},{"text":"Make them keep up exactly","consequence":"They can't, and feel left out, fair means adjusting."}],"debrief":"Adjusting for who's playing keeps it fair and fun for all.","relearn":"Fair play can mean small adjustments so everyone joins.","persona":"any","source":"equity / inclusion"},
  {"id":"fp-047","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: 'same' and 'fair' aren't always the same word. Surprised?","prompt":"What do you think?","options":["A bit","Makes sense","Fair fits the need"],"affirm":"Fair means everyone can truly take part, not just identical shares.","relearn":"Fairness is about everyone being able to take part.","persona":"any","source":"equity"},
  // Spotting & standing up to unfairness
  {"id":"fp-048","cat":"stand-up","type":"sort","hook":"Sort each playground rule into Fair or Not fair.","items":[{"id":"a","text":"\"Everyone gets a turn to bat.\""},{"id":"b","text":"\"Girls can't play cricket here.\""},{"id":"c","text":"\"We rotate who's captain.\""},{"id":"d","text":"\"Whoever's next bowls next.\""},{"id":"e","text":"\"Only big kids are allowed.\""},{"id":"f","text":"\"Anyone can join the team.\""}],"bins":[{"id":"fair","label":"Fair 💚","valence":"pos"},{"id":"notfair","label":"Not fair 🛑","valence":"neg"}],"key":{"a":"fair","b":"notfair","c":"fair","d":"fair","e":"notfair","f":"fair"},"relearn":"An unfair rule often shuts one group out, spot it.","persona":"Ananya","source":"spot unfairness"},
  {"id":"fp-049","cat":"stand-up","type":"role-play","hook":"You see a gender-unfair rule and want to speak up.","setup":"Say it calm and clear:","yourLine":[{"text":"\"That's not fair, everyone should get a turn.\"","best":true},{"text":"Say nothing"}],"relearn":"A calm, clear \"that's not fair\" can change a rule.","persona":"Ananya","source":"assertiveness / voice"},
  {"id":"fp-050","cat":"stand-up","type":"branch","hook":"Your friend is told they can't join because of their gender.","options":[{"text":"Stand with them: \"they're playing too, that's fair\"","consequence":"The group often relents when someone speaks up.","outcome":"ally","best":true},{"text":"Stay quiet to avoid fuss","consequence":"Your friend stays shut out; speaking up helps."}],"debrief":"Standing up for a friend's fair turn is brave and kind.","relearn":"You can stand up for someone shut out unfairly.","persona":"Faizan-type","source":"bystander / fairness"},
  {"id":"fp-051","cat":"stand-up","type":"strike-rewrite","hook":"\"If a rule's unfair, there's nothing a kid can do.\"","myth":{"un":"Kids can't do anything about unfair rules.","re":"Kids can speak up, suggest fairer rules, and ask a grown-up.","why":"Lots of fair rules exist because someone spoke up."},"relearn":"Kids can help change unfair rules.","persona":"Ananya","source":"agency / rights"},
  {"id":"fp-052","cat":"stand-up","type":"branch","hook":"You spoke up about an unfair rule and got brushed off.","options":[{"text":"Tell a fair-minded grown-up (teacher) too","consequence":"A grown-up can help make the rule fairer.","outcome":"persistent","best":true},{"text":"Give up","consequence":"Bringing in a grown-up is a good next step, not giving up."}],"debrief":"If speaking up isn't enough, ask a fair grown-up for help.","relearn":"If you're not heard, a trusted grown-up can help.","persona":"Ananya","source":"escalation / agency"},
  {"id":"fp-053","cat":"stand-up","type":"sort","hook":"Sort each classroom line into Fair or Not fair.","items":[{"id":"a","text":"\"Only boys answer the hard questions.\""},{"id":"b","text":"\"Anyone who knows can answer.\""},{"id":"c","text":"\"Girls just take notes.\""},{"id":"d","text":"\"We take turns reading aloud.\""},{"id":"e","text":"\"Boys sit in front always.\""},{"id":"f","text":"\"Everyone gets a chance to present.\""}],"bins":[{"id":"fair","label":"Fair 💚","valence":"pos"},{"id":"notfair","label":"Not fair 🛑","valence":"neg"}],"key":{"a":"notfair","b":"fair","c":"notfair","d":"fair","e":"notfair","f":"fair"},"relearn":"The fair rule lets anyone take part; the unfair ones don't.","persona":"Ananya","source":"spot fairness"},
  {"id":"fp-054","cat":"stand-up","type":"role-play","hook":"A classmate makes a 'girls can't do that' comment.","setup":"Give a calm comeback. Say:","yourLine":[{"text":"\"Actually, anyone can, let's give it a fair go.\"","best":true},{"text":"Laugh along"}],"relearn":"A calm comeback can flip an unfair comment.","persona":"Reyansh","source":"comebacks / voice"},
  {"id":"fp-055","cat":"stand-up","type":"branch","hook":"The group is dividing jobs: 'boys build, girls decorate', no choice.","options":[{"text":"Say \"let everyone pick what they want to do\"","consequence":"Kids do what they're keen on; the project's better.","outcome":"fair","best":true},{"text":"Go along with it","consequence":"People get stuck in boxes they didn't choose.","outcome":"unfair"}],"debrief":"Letting everyone choose their role is fairer than gender boxes.","relearn":"Roles should be chosen, not assigned by gender.","persona":"Ananya","source":"gender roles / fairness"},
  {"id":"fp-056","cat":"stand-up","type":"reflect","hook":"Lensy: speaking up for fairness can feel scary. Worth it?","prompt":"What do you think?","options":["Yes","For my friends","To make it fair"],"affirm":"Speaking up for fairness is brave, and it makes the world kinder.","relearn":"Speaking up for fairness is brave and worth it.","persona":"Ananya","source":"courage"},
  {"id":"fp-057","cat":"stand-up","type":"strike-rewrite","hook":"\"Standing up for fairness is just causing trouble.\"","myth":{"un":"Standing up for fairness is causing trouble.","re":"Standing up for fairness is making things right.","why":"Fairness helps everyone, not just one side."},"relearn":"Standing up for fairness isn't trouble; it's making things right.","persona":"Ananya","source":"values"},
  {"id":"fp-058","cat":"stand-up","type":"branch","hook":"You benefit from an unfair rule (you always get to go first).","options":[{"text":"Suggest taking turns so it's fair for all","consequence":"You give up a small perk; everyone feels it's fair.","outcome":"fair","best":true},{"text":"Keep your advantage quietly","consequence":"Real fairness sometimes means giving up an unfair perk."}],"debrief":"Being fair sometimes means letting go of an unfair advantage.","relearn":"Fairness can mean sharing an advantage you didn't earn.","persona":"Reyansh","source":"fairness / privilege (kid-level)"},
  {"id":"fp-059","cat":"stand-up","type":"role-play","hook":"You want to invite a left-out kid into a fair turn.","setup":"Include them. Say:","yourLine":[{"text":"\"Come on, it's your turn now.\"","best":true},{"text":"Ignore them"}],"relearn":"Inviting someone into a fair turn is fairness in action.","persona":"any","source":"inclusion / voice"},
  {"id":"fp-060","cat":"stand-up","type":"reflect","hook":"Lensy: who could YOU stand up for this week?","prompt":"Think of someone.","options":["A left-out friend","Someone treated unfairly","Anyone shut out","Myself"],"affirm":"That's a fairness hero move. Small stands change big things.","relearn":"You can choose to stand up for fairness, in small ways, often.","persona":"Ananya","source":"agency"},
  // Fair at home, school & play
  {"id":"fp-061","cat":"fair-everywhere","type":"branch","hook":"At home, you always get served first and the most.","options":[{"text":"Suggest everyone gets a fair share","consequence":"Mealtimes feel fair to all the kids.","outcome":"fair","best":true},{"text":"Enjoy the extra quietly","consequence":"Fairness at home means equal shares for the kids too."}],"debrief":"Fairness counts at home as much as at school.","relearn":"Fair shares matter at home too, not just at school.","persona":"Ananya","source":"fairness / India"},
  {"id":"fp-062","cat":"fair-everywhere","type":"sort","hook":"Sort: fair at school, or not?","items":[{"id":"a","text":"Everyone gets help when stuck"},{"id":"b","text":"Only favourites get picked"},{"id":"c","text":"Turns on the computer"},{"id":"d","text":"Same kids always told to sit out"},{"id":"e","text":"Sharing the library books by turns"},{"id":"f","text":"One group hogging the play equipment"}],"bins":[{"id":"fair","label":"Fair 💚","valence":"pos"},{"id":"no","label":"Unfair 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair classrooms share help, turns and chances.","persona":"any","source":"fairness"},
  {"id":"fp-063","cat":"fair-everywhere","type":"branch","hook":"In a game, you could cheat to win.","options":[{"text":"Play fair, even if you might lose","consequence":"Win or lose, you played fair and kept friends.","outcome":"fair","best":true},{"text":"Cheat to win","consequence":"A cheated win doesn't feel good and loses trust.","outcome":"unfair"}],"debrief":"Playing fair matters more than winning by cheating.","relearn":"Fair play means no cheating, even to win.","persona":"any","source":"fair play / integrity"},
  {"id":"fp-064","cat":"fair-everywhere","type":"role-play","hook":"A friend cheated and you both know it.","setup":"Say something fair, not mean. Say:","yourLine":[{"text":"\"Let's play it fair, it's more fun that way.\"","best":true},{"text":"Cheat back next time"}],"relearn":"Asking to keep it fair beats cheating back.","persona":"any","source":"fair play / voice"},
  {"id":"fp-065","cat":"fair-everywhere","type":"reflect","hook":"Lensy: does fairness make games more fun or less?","prompt":"What do you think?","options":["More fun","Everyone enjoys it","More, for sure"],"affirm":"Fair games are more fun, because everyone gets to enjoy them.","relearn":"Fair play makes games more fun for everyone.","persona":"any","source":"fair play"},
  {"id":"fp-066","cat":"fair-everywhere","type":"sort","hook":"Sort: fair sharing, or hogging?","items":[{"id":"a","text":"Passing the ball to everyone"},{"id":"b","text":"Never passing"},{"id":"c","text":"Letting others have a go"},{"id":"d","text":"Keeping all the toys"},{"id":"e","text":"Taking turns with the skipping rope"},{"id":"f","text":"Holding the only ball all break"}],"bins":[{"id":"fair","label":"Fair sharing 💚","valence":"pos"},{"id":"no","label":"Hogging 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair sharing passes the fun around.","persona":"any","source":"sharing"},
  {"id":"fp-067","cat":"fair-everywhere","type":"branch","hook":"You and your sibling must split screen time.","options":[{"text":"Agree on equal turns with a timer","consequence":"You both get fair time; no fights.","outcome":"fair","best":true},{"text":"Grab as much as you can","consequence":"Fair turns beat grabbing and fighting."}],"debrief":"A timer and turns make screen time fair.","relearn":"Fair turns solve a lot of sharing fights.","persona":"any","source":"fairness"},
  {"id":"fp-068","cat":"fair-everywhere","type":"reflect","hook":"Lensy: you can bring fairness anywhere you go. Ready?","prompt":"Where will you bring it?","options":["Home","School","Play","Everywhere"],"affirm":"Fairness travels with you, home, school and play.","relearn":"You can choose fairness wherever you are.","persona":"any","source":"transfer"},
  {"id":"fp-069","cat":"chores-shared","type":"reflect","hook":"Lensy: girls in India do about 40% more chores than boys. Is that fair?","prompt":"What do you think?","options":["No","Not fair","We can change it"],"affirm":"It's not fair, and sharing chores is how families can change it.","relearn":"The chore gap isn't fair; sharing fixes it.","persona":"Ananya","source":"India chore gap"},
  {"id":"fp-070","cat":"fair-opportunity","type":"branch","hook":"A teacher asks 'a strong boy' to carry books.","options":[{"text":"Say \"any strong kid can help, I'll come too\"","consequence":"Help isn't assumed by gender; anyone pitches in.","outcome":"fair","best":true},{"text":"Assume only boys should","consequence":"Strength and helping aren't a boys-only thing."}],"debrief":"Jobs and help shouldn't be assigned by gender by default.","relearn":"Don't assume tasks by gender; anyone can help.","persona":"Ananya","source":"gender norms"},
  {"id":"fp-071","cat":"equal-vs-equity","type":"branch","hook":"One friend gets pocket money, another never does.","options":[{"text":"Understand families differ, and share treats kindly","consequence":"You're thoughtful about different situations.","outcome":"kind","best":true},{"text":"Brag about yours","consequence":"Fairness includes being kind about what others have."}],"debrief":"Fairness includes kindness about different family situations.","relearn":"Be kind and thoughtful about what others have or don't.","persona":"Kabir-type","source":"equity / empathy"},
  {"id":"fp-072","cat":"stand-up","type":"sort","hook":"Sort each into Fair plan or Unfair guess.","items":[{"id":"a","text":"\"She's a girl, so she'll tidy.\""},{"id":"b","text":"\"Let's see who wants which job.\""},{"id":"c","text":"\"We'll take turns tidying.\""},{"id":"d","text":"\"Boys carry, girls can't lift.\""},{"id":"e","text":"\"Pick jobs from a hat, fair for all.\""},{"id":"f","text":"\"He's a boy, so he won't cook.\""}],"bins":[{"id":"fair","label":"Fair plan 💚","valence":"pos"},{"id":"unfair","label":"Unfair guess 🛑","valence":"neg"}],"key":{"a":"unfair","b":"fair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Watch for 'she's a girl, so...' assumptions, they're unfair.","persona":"Ananya","source":"gender norms"},
  {"id":"fp-073","cat":"what-is-fair","type":"branch","hook":"You made a mistake that was unfair to someone.","options":[{"text":"Own it and make it right","consequence":"You repair it; fairness includes fixing your own slips.","outcome":"fair","best":true},{"text":"Pretend it didn't happen","consequence":"Fairness means owning and fixing your own unfair moves."}],"debrief":"Being fair includes putting right your own mistakes.","relearn":"If you were unfair, own it and make it right.","persona":"any","source":"accountability"},
  {"id":"fp-074","cat":"fair-opportunity","type":"reflect","hook":"Lensy: imagine a world where everyone got a fair chance. Good?","prompt":"What do you think?","options":["Amazing","Everyone could shine","Yes!"],"affirm":"That's the world Fair Play builds, one fair turn at a time.","relearn":"Fair chances let everyone shine.","persona":"any","source":"vision"},
  {"id":"fp-075","cat":"chores-shared","type":"role-play","hook":"Your little brother says chores are 'for girls'.","setup":"Set him straight, kindly. Say:","yourLine":[{"text":"\"Nope, everyone helps, let's do it together.\"","best":true},{"text":"\"Fine, I'll do it.\""}],"relearn":"Teach a sibling that chores are for everyone.","persona":"Ananya","source":"voice / gender-equal caregiving"},
  {"id":"fp-076","cat":"stand-up","type":"branch","hook":"Everyone's laughing at an unfair 'joke' that puts girls down.","options":[{"text":"Say \"that's not fair or funny\"","consequence":"You take the air out of it; some agree.","outcome":"ally","best":true},{"text":"Laugh along","consequence":"Laughing feeds an unfair put-down."}],"debrief":"Unfair 'jokes' aren't funny; you can say so (see Not Fair, Not Funny).","relearn":"You don't have to laugh at unfair put-downs.","persona":"Ananya","source":"bystander (links g11)"},
  {"id":"fp-077","cat":"equal-vs-equity","type":"sort","hook":"Sort: meets needs, or unfair sameness?","items":[{"id":"a","text":"A ramp so a wheelchair user can enter"},{"id":"b","text":"Stairs only, everyone the same"},{"id":"c","text":"Extra reading time for who needs it"},{"id":"d","text":"No one ever gets help"},{"id":"e","text":"A stool so a short kid reaches the tap"},{"id":"f","text":"Same high tap, can't reach"}],"bins":[{"id":"fair","label":"Fair 💚","valence":"pos"},{"id":"no","label":"Unfair sameness 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Real fairness removes barriers so everyone can take part.","persona":"any","source":"equity / accessibility"},
  {"id":"fp-078","cat":"fair-everywhere","type":"role-play","hook":"Your team won; the other team is sad.","setup":"Be a fair winner. Say:","yourLine":[{"text":"\"Good game! You played really well.\"","best":true},{"text":"\"We're way better than you.\""}],"relearn":"Being fair includes being a kind winner.","persona":"any","source":"sportsmanship / voice"},
  {"id":"fp-079","cat":"stand-up","type":"reflect","hook":"Lensy: what's one unfair thing you'd love to change?","prompt":"Think of one.","options":["Chores at home","Who gets picked","Who gets a say","An unfair rule"],"affirm":"Hold that. Noticing it is the first step to changing it.","relearn":"Noticing unfairness is how change begins.","persona":"Ananya","source":"changemaking"},
  {"id":"fp-080","cat":"fair-opportunity","type":"branch","hook":"Capstone: you're in charge of picking who does the fun science demo.","options":[{"text":"Pick fairly, by turns, any gender","consequence":"Everyone gets a fair shot; the class trusts you.","outcome":"fair","best":true},{"text":"Pick only your friends / only boys","consequence":"Fair leaders share chances with everyone.","outcome":"unfair"}],"debrief":"When you have the power to choose, choosing fairly is the test.","relearn":"Fair leaders share opportunities with everyone.","persona":"Ananya","source":"leadership / consolidation"},
  {"id":"fp-081","cat":"chores-shared","type":"build","hook":"Capstone: build a fair-share plan for your home.","prompt":"Pick what makes it fair.","pieces":["turns for every chore","everyone helps, any gender","time to study and play for all","a family chat to agree"],"mode":"assemble","key":["turns for every chore","everyone helps, any gender","time to study and play for all","a family chat to agree"],"relearn":"A fair-share home: turns for all, everyone helps, time for all to study and play.","persona":"Ananya","source":"India chore gap / consolidation"},
  {"id":"fp-082","cat":"what-is-fair","type":"reflect","hook":"Lensy: what will you carry from Fair Play World?","prompt":"Pick your motto.","options":["Everyone gets a fair turn","Chores are everyone's","Fair means meeting needs","I can stand up for fair"],"affirm":"Carry that. You're a Fair Play champion now.","relearn":"Fairness: everyone gets a turn, chores are shared, needs are met, and you can stand up for it.","persona":"any","source":"consolidation"},
  {"id":"fp-083","cat":"stand-up","type":"strike-rewrite","hook":"\"It's not my problem if something's unfair to someone else.\"","myth":{"un":"Unfairness to others is none of my business.","re":"Fairness is everyone's business; you can help.","why":"We all do better when things are fair for all."},"relearn":"You can care about fairness for others, not just yourself.","persona":"Ananya","source":"solidarity"},
  {"id":"fp-084","cat":"fair-everywhere","type":"reflect","hook":"Lensy: fairness is a habit you build. Ready to practise it daily?","prompt":"What do you think?","options":["Yes","Every day","I'll practise"],"affirm":"Fairness grows with practice, one fair choice at a time. Go well!","relearn":"Fairness is a daily habit you can keep building.","persona":"any","source":"habit / growth"},
  {"id":"fp-900","cat":"chores-shared","type":"strike-rewrite","hook":"\"Cooking is amma's job, not appa's.\"","myth":{"un":"Cooking is amma's job, not appa's.","re":"Anyone in the family can cook; appa can make dinner too.","why":"Cooking is a skill, not a gender."},"relearn":"Cooking belongs to whoever's helping, any gender.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-901","cat":"chores-shared","type":"strike-rewrite","hook":"\"Girls should serve the boys their food first.\"","myth":{"un":"Girls should serve the boys their food first.","re":"Everyone serves and clears together; no one waits to be served by gender.","why":"A fair table means everyone helps and everyone eats."},"relearn":"Serving food is shared, not a girl's duty.","persona":"Ananya","source":"India / gender-equal caregiving"},
  {"id":"fp-902","cat":"chores-shared","type":"strike-rewrite","hook":"\"Boys only do the 'heavy' outdoor jobs.\"","myth":{"un":"Boys only do the heavy outdoor jobs, not housework.","re":"Boys do indoor chores too, like sweeping and washing up.","why":"Every job at home needs doing by someone."},"relearn":"No chore is off-limits to a boy.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-903","cat":"chores-shared","type":"strike-rewrite","hook":"\"My sister will do the dishes, she always does.\"","myth":{"un":"My sister will do the dishes, she always does.","re":"Dishes go to whoever's turn it is, and brothers take turns too.","why":"'Always her' just means she never gets a break."},"relearn":"One person doing it 'always' isn't a fair turn.","persona":"Ananya","source":"India chore gap"},
  {"id":"fp-904","cat":"chores-shared","type":"strike-rewrite","hook":"\"Helping in the kitchen makes a boy less of a boy.\"","myth":{"un":"Helping in the kitchen makes a boy less of a boy.","re":"Helping at home makes any kid kind and capable.","why":"Caring for your family is something to be proud of."},"relearn":"Home help adds to a boy, it never takes away.","persona":"Reyansh","source":"life skills"},
  {"id":"fp-905","cat":"chores-shared","type":"strike-rewrite","hook":"\"Looking after the baby is a girl's job.\"","myth":{"un":"Looking after the baby is a girl's job.","re":"Caring for a little one is shared; brothers can rock and feed too.","why":"A baby needs love from everyone in the family."},"relearn":"Caregiving is gender-equal, not just for girls.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-906","cat":"chores-shared","type":"strike-rewrite","hook":"\"Sweeping the floor is below a boy.\"","myth":{"un":"Sweeping the floor is below a boy.","re":"Keeping the home clean is everyone's job and below no one.","why":"A tidy home is something the whole family shares."},"relearn":"No chore is 'beneath' anyone, of any gender.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-907","cat":"chores-shared","type":"strike-rewrite","hook":"\"Daughters help at home; sons just study.\"","myth":{"un":"Daughters help at home while sons just study.","re":"Everyone can study and everyone shares some chores too.","why":"Sharing the work leaves all the kids time to learn."},"relearn":"Both sons and daughters study and help.","persona":"Ananya","source":"India chore gap / education"},
  {"id":"fp-908","cat":"chores-shared","type":"branch","hook":"Your cousin visits and says only the girls should wash up after lunch.","options":[{"text":"Say \"let's all wash up, it'll be done in a minute\"","consequence":"Boys and girls clear together; it's quick and fair.","outcome":"fair","best":true},{"text":"Let the girls do it alone","consequence":"The girls miss playtime while the boys relax."}],"debrief":"Sharing clean-up means everyone gets back to play sooner.","relearn":"Clean-up is everyone's, finished fast when shared.","persona":"Ananya","source":"fairness"},
  {"id":"fp-909","cat":"chores-shared","type":"branch","hook":"Amma is unwell and the housework is piling up at home.","options":[{"text":"Call a family huddle and split the jobs for the week","consequence":"Everyone takes a job; amma rests and the home runs.","outcome":"fair","best":true},{"text":"Wait for your sister to handle it all","consequence":"Your sister is swamped and amma still doesn't rest."}],"debrief":"When one person can't, the family shares the load, not one kid.","relearn":"A family shares the load when someone needs rest.","persona":"Sunita","source":"India joint family / fairness"},
  {"id":"fp-910","cat":"chores-shared","type":"branch","hook":"Your brother 'pays' you ₹10 to do his sweeping every day.","options":[{"text":"Say \"keep it, let's just take turns instead\"","consequence":"You both sweep on your own days; it's actually fair.","outcome":"fair","best":true},{"text":"Take the money and do both","consequence":"You're stuck doing double, money or not."}],"debrief":"Paying someone to take all your turns still isn't sharing.","relearn":"Fair sharing means turns, not buying your way out.","persona":"Ananya","source":"fairness"},
  {"id":"fp-911","cat":"chores-shared","type":"branch","hook":"Dadi says the boys never need to fold the washing.","options":[{"text":"Say \"can we all fold together? everyone helps the family\"","consequence":"Dadi nods; the boys join and it's done fast.","outcome":"fair","best":true},{"text":"Agree and fold it all yourself","consequence":"You're left with the whole basket each day."}],"debrief":"\"Everyone helps the family\" is a fairness elders can accept.","relearn":"You can invite everyone in, even an elder's rule.","persona":"Sunita","source":"India joint family"},
  {"id":"fp-912","cat":"chores-shared","type":"branch","hook":"At a meal, your friend's brother won't clear his own plate.","options":[{"text":"Say \"we all clear our own, come on, I'll go too\"","consequence":"He clears his plate; clearing up becomes everyone's.","outcome":"fair","best":true},{"text":"Clear it for him to avoid a fuss","consequence":"He learns someone always cleans up after him."}],"debrief":"Clearing your own plate is a fair habit anyone can keep.","relearn":"Each person clears their own; fair and simple.","persona":"any","source":"fairness"},
  {"id":"fp-913","cat":"chores-shared","type":"branch","hook":"The chore list at home only ever has the girls' names on it.","options":[{"text":"Suggest adding everyone's name and rotating each week","consequence":"The list now includes all; jobs rotate and feel fair.","outcome":"fair","best":true},{"text":"Leave the list as it is","consequence":"The same kids stay stuck with all the work."}],"debrief":"A fair list has everyone on it and rotates the jobs.","relearn":"Put everyone on the list and rotate by turns.","persona":"Ananya","source":"India chore gap"},
  {"id":"fp-914","cat":"chores-shared","type":"branch","hook":"Cleaning the classroom, the boys say sweeping is 'girls' work'.","options":[{"text":"Say \"we're a team, let's split it, I'll sweep too\"","consequence":"Everyone grabs a job; the room's clean fast.","outcome":"fair","best":true},{"text":"Let the girls sweep while the boys watch","consequence":"Half the team works, the other half watches."}],"debrief":"A team shares every job; no task is one gender's.","relearn":"Classroom chores are split across the whole team.","persona":"Reyansh","source":"school / fairness"},
  {"id":"fp-915","cat":"chores-shared","type":"branch","hook":"You and your sister both have homework, but only she's told to cook.","options":[{"text":"Say \"we both have homework, let's cook and study together\"","consequence":"You share the cooking; you both finish homework.","outcome":"fair","best":true},{"text":"Go study while she cooks alone","consequence":"She falls behind on homework; not a fair deal."}],"debrief":"Fair sharing protects everyone's study time, not just yours.","relearn":"Share the chore so no one loses study time.","persona":"Ananya","source":"India chore gap"},
  {"id":"fp-916","cat":"chores-shared","type":"branch","hook":"Appa starts cooking for guests and a neighbour laughs at him.","options":[{"text":"Say \"appa's a great cook, we all pitch in here\"","consequence":"Appa keeps cooking proudly; the meal's a team effort.","outcome":"fair","best":true},{"text":"Tell appa to stop so no one laughs","consequence":"Appa steps back; amma's left to do it all."}],"debrief":"Anyone can cook; a teasing neighbour doesn't set your rules.","relearn":"Men cooking at home is fair, nothing to hide.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-917","cat":"chores-shared","type":"branch","hook":"Your brother took his turn at the dishes but did it badly.","options":[{"text":"Show him how, kindly, so he keeps his turn","consequence":"He improves and stays in the rotation; sharing holds.","outcome":"fair","best":true},{"text":"Take dishes off his list 'as he's bad at it'","consequence":"He never learns; you're back to doing them all."}],"debrief":"Learning a chore is fairer than being let off it.","relearn":"Help someone improve, don't excuse the turn away.","persona":"Ananya","source":"life skills"},
  {"id":"fp-918","cat":"chores-shared","type":"branch","hook":"At a school event, the teacher gives cleaning only to the girls.","options":[{"text":"Say \"can the cleaning rotate too, ma'am?\"","consequence":"The teacher agrees; both jobs rotate across everyone.","outcome":"fair","best":true},{"text":"Say nothing; let the girls clean every time","consequence":"The girls always get the clean-up; not fair."}],"debrief":"A fair teacher rotates jobs once it's pointed out.","relearn":"You can ask a teacher to rotate chores fairly.","persona":"Reyansh","source":"school / fairness"},
  {"id":"fp-919","cat":"chores-shared","type":"sort","hook":"Sort the chore lines: fair for all, or an unfair myth?","items":[{"id":"a","text":"Anyone can cook the dal"},{"id":"b","text":"We all mop in turns"},{"id":"c","text":"Mending is only for girls"},{"id":"d","text":"Everyone can carry water"},{"id":"e","text":"Brothers feed the baby too"},{"id":"f","text":"Boys don't fix taps"}],"bins":[{"id":"fair","label":"Fair for all 💚","valence":"pos"},{"id":"myth","label":"Unfair myth 🛑","valence":"neg"}],"key":{"a":"fair","b":"fair","c":"myth","d":"fair","e":"fair","f":"myth"},"relearn":"Every chore can be done by anyone, of any gender.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-920","cat":"chores-shared","type":"sort","hook":"Sort each home moment: fair sharing, or not fair?","items":[{"id":"a","text":"Brother and sister cook together"},{"id":"b","text":"Only the girls sweep every day"},{"id":"c","text":"Everyone clears their own plate"},{"id":"d","text":"Boys watch TV while girls clean"},{"id":"e","text":"The chore chart rotates each week"},{"id":"f","text":"Sister does the brother's chores too"}],"bins":[{"id":"fair","label":"Fair 💚","valence":"pos"},{"id":"no","label":"Not fair 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair homes share the work across everyone, by turns.","persona":"Sunita","source":"fairness"},
  {"id":"fp-921","cat":"chores-shared","type":"sort","hook":"Sort: which chore words are fair, and which are unfair myths?","items":[{"id":"a","text":"\"Let's take turns\""},{"id":"b","text":"\"That's girls' work\""},{"id":"c","text":"\"Everyone helps the family\""},{"id":"d","text":"\"Boys don't do housework\""},{"id":"e","text":"\"I'll do my turn today\""},{"id":"f","text":"\"Cooking's not for boys\""}],"bins":[{"id":"fair","label":"Fair words 💚","valence":"pos"},{"id":"myth","label":"Unfair myth 🛑","valence":"neg"}],"key":{"a":"fair","b":"myth","c":"fair","d":"myth","e":"fair","f":"myth"},"relearn":"Fair words share the work; myths pin it on one gender.","persona":"Ananya","source":"India chore gap"},
  {"id":"fp-922","cat":"chores-shared","type":"sort","hook":"Sort: when does the chore happen? Build a fair morning order.","items":[{"id":"a","text":"Whose turn it is today"},{"id":"b","text":"Whoever is free first"},{"id":"c","text":"Only the eldest girl"},{"id":"d","text":"The boys never"},{"id":"e","text":"All of us, a bit each"},{"id":"f","text":"Just the daughters"}],"bins":[{"id":"fair","label":"Fair way 💚","valence":"pos"},{"id":"no","label":"Not fair 🛑","valence":"neg"}],"key":{"a":"fair","b":"fair","c":"no","d":"no","e":"fair","f":"no"},"relearn":"Chores go by turns or who's free, never by gender.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-923","cat":"chores-shared","type":"sort","hook":"Sort these ideas: helps everyone, or leaves someone stuck?","items":[{"id":"a","text":"A chart with everyone's name"},{"id":"b","text":"Rotating jobs each week"},{"id":"c","text":"One kid does it 'as she's good at it'"},{"id":"d","text":"Paying a sibling to take your turn"},{"id":"e","text":"Teaching a brother a new chore"},{"id":"f","text":"Saying 'not a boy's job'"}],"bins":[{"id":"helps","label":"Helps all 💚","valence":"pos"},{"id":"stuck","label":"Leaves one stuck 🛑","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"stuck","d":"stuck","e":"helps","f":"stuck"},"relearn":"Sharing spreads the work; tricks leave one kid stuck.","persona":"Ananya","source":"fairness"},
  {"id":"fp-924","cat":"chores-shared","type":"sort","hook":"Sort each home scene: fair sharing, or not fair?","items":[{"id":"a","text":"Appa folds the clothes"},{"id":"b","text":"Brother feeds the baby"},{"id":"c","text":"Only sisters wash dishes"},{"id":"d","text":"Amma carries the cylinder"},{"id":"e","text":"Boys never tidy up"},{"id":"f","text":"All of us share the chores"}],"bins":[{"id":"fair","label":"Fair sharing 💚","valence":"pos"},{"id":"no","label":"Not fair 🛑","valence":"neg"}],"key":{"a":"fair","b":"fair","c":"no","d":"fair","e":"no","f":"fair"},"relearn":"Everyone in the family can do every kind of chore.","persona":"Sunita","source":"India joint family / gender-equal caregiving"},
  {"id":"fp-925","cat":"chores-shared","type":"build","hook":"Build a fair weekend chore plan for your family.","prompt":"Pick the pieces that make it fair for everyone.","pieces":["a turn for each person","brothers and sisters both on it","appa cooks his day too","time left for everyone to play","'only the girls' clean"],"mode":"assemble","key":["a turn for each person","brothers and sisters both on it","appa cooks his day too","time left for everyone to play"],"relearn":"A fair plan: turns for all, both genders, time to play for everyone.","persona":"Sunita","source":"India joint family / fairness"},
  {"id":"fp-926","cat":"chores-shared","type":"build","hook":"Build the steps to share a big festival clean-up fairly.","prompt":"Put the fair steps in order.","pieces":["list every job that needs doing","share the jobs across everyone","each person does their share","celebrate together when it's done"],"mode":"sequence","key":["list every job that needs doing","share the jobs across everyone","each person does their share","celebrate together when it's done"],"relearn":"Share festival work by listing jobs, splitting them, then celebrating.","persona":"any","source":"India / fairness"},
  {"id":"fp-927","cat":"chores-shared","type":"build","hook":"Build a fair chore-swap when one sibling is busy with exams.","prompt":"Pick what keeps it fair.","pieces":["others cover her chores this week","she takes extra turns after exams","everyone agrees to the swap","she does it all anyway, exams or not"],"mode":"assemble","key":["others cover her chores this week","she takes extra turns after exams","everyone agrees to the swap"],"relearn":"A fair swap is agreed, temporary, and paid back in turns.","persona":"Ananya","source":"fairness / education"},
  {"id":"fp-928","cat":"chores-shared","type":"build","hook":"Build a 'morning jobs' rota everyone can follow.","prompt":"Pick the pieces of a fair rota.","pieces":["each name gets a job","jobs swap the next day","boys and girls both listed","quick check that it's fair"],"mode":"assemble","key":["each name gets a job","jobs swap the next day","boys and girls both listed","quick check that it's fair"],"relearn":"A fair rota lists everyone, swaps jobs, and gets a fairness check.","persona":"any","source":"fairness"},
  {"id":"fp-929","cat":"chores-shared","type":"build","hook":"Build the order for teaching your little brother to wash up.","prompt":"Put the kind steps in order.","pieces":["show him how, step by step","do one together","let him try his own turn","cheer him on so he keeps it up"],"mode":"sequence","key":["show him how, step by step","do one together","let him try his own turn","cheer him on so he keeps it up"],"relearn":"Teach a chore by showing, doing together, then cheering them on.","persona":"Ananya","source":"life skills / gender-equal caregiving"},
  {"id":"fp-930","cat":"chores-shared","type":"build","hook":"Build a fair deal so cooking isn't only amma's job.","prompt":"Pick the fair pieces.","pieces":["everyone takes a cooking day","appa and the kids learn dishes too","amma gets days to rest","amma cooks every single day"],"mode":"assemble","key":["everyone takes a cooking day","appa and the kids learn dishes too","amma gets days to rest"],"relearn":"Fair cooking rotates so amma gets rest days too.","persona":"Sunita","source":"India chore gap / gender-equal caregiving"},
  {"id":"fp-931","cat":"chores-shared","type":"role-play","hook":"Your friend boasts that his sister does all his chores.","setup":"Nudge him to share, kindly. Say:","yourLine":[{"text":"\"That's a lot on her, want to start taking turns?\"","best":true},{"text":"\"Wow, lucky you!\""}],"relearn":"Help a friend see his sister shouldn't carry his chores.","persona":"Reyansh","source":"voice / fairness"},
  {"id":"fp-932","cat":"chores-shared","type":"role-play","hook":"At dinner, the boys get up to play while the girls are told to clear.","setup":"Speak up at the table, kindly. Say:","yourLine":[{"text":"\"Let's all clear together, then we can all play.\"","best":true},{"text":"Start clearing alone without a word"}],"relearn":"Inviting everyone to clear up is fair and brave.","persona":"Ananya","source":"voice / fairness"},
  {"id":"fp-933","cat":"chores-shared","type":"role-play","hook":"Appa offers to cook and your cousin teases him for it.","setup":"Back appa up, kindly. Say:","yourLine":[{"text":"\"Appa's cooking is great, and we all help here.\"","best":true},{"text":"Laugh along and say nothing"}],"relearn":"Standing up for a dad who cooks is a fair, kind move.","persona":"any","source":"voice / gender-equal caregiving"},
  {"id":"fp-934","cat":"chores-shared","type":"role-play","hook":"You want to start a fair chore rota but feel shy to ask.","setup":"Ask your family, kindly. Say:","yourLine":[{"text":"\"Could we try a turn-by-turn rota so everyone shares?\"","best":true},{"text":"Keep quiet and hope it changes"}],"relearn":"Asking for a fair rota is reasonable and brave.","persona":"Ananya","source":"voice / agency"},
  {"id":"fp-935","cat":"chores-shared","type":"role-play","hook":"Your brother says he's 'too busy' for chores but you both have the same homework.","setup":"Call it fairly, kindly. Say:","yourLine":[{"text":"\"We're both busy, so let's split it and both get free.\"","best":true},{"text":"\"Okay, I'll just do yours too.\""}],"relearn":"'Too busy' isn't fair when everyone's busy; split it.","persona":"Ananya","source":"voice / India chore gap"},
  {"id":"fp-936","cat":"chores-shared","type":"role-play","hook":"A neighbour says your brother helping in the kitchen is 'odd'.","setup":"Stand by your brother, kindly. Say:","yourLine":[{"text":"\"It's not odd, everyone in our home helps out.\"","best":true},{"text":"Tell your brother to stop helping"}],"relearn":"Boys helping at home is normal and fair, not odd.","persona":"Reyansh","source":"voice / gender-equal caregiving"},
  {"id":"fp-937","cat":"chores-shared","type":"reflect","hook":"Lensy: when both your parents share the cooking, how does that feel?","prompt":"What do you think?","options":["Fair","Nice for amma","Like teamwork"],"affirm":"When parents share the cooking, the whole home feels like a team.","relearn":"Shared cooking at home feels fair and like teamwork.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-938","cat":"chores-shared","type":"reflect","hook":"Lensy: which chore would you actually like to learn, whatever your gender?","prompt":"What do you think?","options":["Cooking","Fixing things","Caring for the baby"],"affirm":"Any chore is yours to learn; the skill belongs to you, not a gender.","relearn":"You can choose to learn any chore you like.","persona":"any","source":"life skills"},
  {"id":"fp-939","cat":"chores-shared","type":"reflect","hook":"Lensy: if chores were truly shared, what would you do with the time you'd save?","prompt":"What do you think?","options":["Study","Play","Rest"],"affirm":"Sharing chores gives everyone time back, to study, play or rest.","relearn":"Fair chores free up time for what matters to you.","persona":"Ananya","source":"India chore gap / education"},
  {"id":"fp-940","cat":"chores-shared","type":"reflect","hook":"Lensy: a brother learning to cook, what do you make of that?","prompt":"What do you think?","options":["Great","Totally normal","Useful for life"],"affirm":"A brother who cooks is learning a skill that helps him for life.","relearn":"Boys learning home skills is great and normal.","persona":"Reyansh","source":"life skills"},
  {"id":"fp-941","cat":"chores-shared","type":"reflect","hook":"Lensy: would a fair chore rota make your mornings calmer? It's okay to want that.","prompt":"What do you think?","options":["Yes","Less rushed","Fairer for all"],"affirm":"Wanting calmer, fairer mornings is reasonable; you can ask for a rota.","relearn":"It's okay to want and ask for a fair chore rota.","persona":"any","source":"agency / fairness"},
  {"id":"fp-942","cat":"chores-shared","type":"reflect","hook":"Lensy: who should get a turn to rest while others do the chores?","prompt":"What do you think?","options":["Everyone, by turns","All of us","Whoever's done their share"],"affirm":"Rest is shared by turns too, not saved only for some of the family.","relearn":"Rest is shared fairly, just like the chores.","persona":"Ananya","source":"fairness"},
  {"id":"fp-943","cat":"chores-shared","type":"reflect","hook":"Lensy: when everyone pitches in for festival prep, what changes?","prompt":"What do you think?","options":["It's faster","More fun","Everyone enjoys it"],"affirm":"When everyone pitches in, the work is faster and the fun is shared.","relearn":"Shared festival prep means more fun for all.","persona":"Sunita","source":"India / fairness"},
  {"id":"fp-944","cat":"chores-shared","type":"reflect","hook":"Lensy: should helping at home be only some kids' job, or everyone's?","prompt":"What do you think?","options":["Everyone's","All of us share","Not just some"],"affirm":"Helping at home is everyone's, shared across the whole family.","relearn":"Home help belongs to everyone, not just some kids.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-945","cat":"chores-shared","type":"reflect","hook":"Lensy: you taught your brother a chore today. How does sharing it feel now?","prompt":"What do you think?","options":["Lighter","Fairer","Like a team"],"affirm":"Teaching a chore shares the load; the work feels lighter for everyone.","relearn":"Sharing a chore you once did alone feels lighter and fairer.","persona":"Ananya","source":"life skills / fairness"},
  {"id":"fp-946","cat":"chores-shared","type":"reflect","hook":"Lensy: girls in India do about 40% more chores than boys. What could families do?","prompt":"What do you think?","options":["Share the chores","Take turns","Put everyone on the chart"],"affirm":"Families can close that gap by sharing the chores and taking turns.","relearn":"Sharing chores by turns is how families close the gap.","persona":"Ananya","source":"India chore gap"},
  {"id":"fp-947","cat":"chores-shared","type":"reflect","hook":"Lensy: a chore chart with everyone's name on it, what does that say to you?","prompt":"What do you think?","options":["We all help","It's fair","No one's left out"],"affirm":"A chart with everyone on it says the whole family helps, fairly.","relearn":"Everyone on the chart means the work is truly shared.","persona":"Sunita","source":"fairness"},
  {"id":"fp-948","cat":"chores-shared","type":"match","hook":"Match each home job to the fair way to decide who does it.","pairs":[{"left":"Cooking dinner","right":"Whoever's turn it is today"},{"left":"Washing the dishes","right":"The next person on the rota"},{"left":"Sweeping the floor","right":"Shared, a bit each"},{"left":"Feeding the baby","right":"Whoever is free to help"},{"left":"Folding the washing","right":"Everyone together"}],"relearn":"Every chore is decided by turns or who's free, never by gender.","persona":"Sunita","source":"gender-equal caregiving"},
  {"id":"fp-949","cat":"chores-shared","type":"match","hook":"Match the family member to a chore they can absolutely do.","pairs":[{"left":"Appa","right":"Cooking the dal"},{"left":"Brother","right":"Washing the dishes"},{"left":"Sister","right":"Fixing a loose handle"},{"left":"Dadu","right":"Folding the clothes"},{"left":"Amma","right":"Carrying the water"}],"relearn":"Anyone in the family can do any chore, whatever their gender.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-950","cat":"chores-shared","type":"match","hook":"Match each unfair chore line to its fair rewrite.","pairs":[{"left":"\"That's girls' work\"","right":"\"That's everyone's work\""},{"left":"\"Boys don't help at home\"","right":"\"Boys take their turn too\""},{"left":"\"Only my sister cooks\"","right":"\"We all cook on our days\""},{"left":"\"Cleaning is below me\"","right":"\"I'll do my share\""},{"left":"\"She always does it\"","right":"\"Let's rotate it fairly\""}],"relearn":"Every unfair chore line has a fair rewrite that shares the work.","persona":"Ananya","source":"India chore gap"},
  {"id":"fp-951","cat":"chores-shared","type":"match","hook":"Match each chore moment to what makes it fair or not.","pairs":[{"left":"Brother takes his dish turn","right":"Fair, he shares too"},{"left":"Only girls clear up","right":"Not fair, one gender does it"},{"left":"The rota swaps each week","right":"Fair, jobs rotate"},{"left":"Boys watch while girls work","right":"Not fair, half are left out"},{"left":"Appa cooks on his day","right":"Fair, anyone can cook"}],"relearn":"Fair chores rotate across everyone; one gender doing it all isn't fair.","persona":"Sunita","source":"fairness"},
  {"id":"fp-952","cat":"chores-shared","type":"match","hook":"Match each part of a fair chore plan to what it does.","pairs":[{"left":"Everyone's name listed","right":"No one is left out"},{"left":"Jobs rotate weekly","right":"No one's stuck with one job"},{"left":"Boys and girls both on it","right":"Shared by all, not by gender"},{"left":"A family chat to agree","right":"Everyone says yes to it"},{"left":"Time left to study and play","right":"Fair to everyone's day"}],"relearn":"A fair plan lists all, rotates, includes both genders, and is agreed.","persona":"Ananya","source":"India chore gap / fairness"},
  {"id":"fp-953","cat":"chores-shared","type":"match","hook":"Match each helper to a caregiving job anyone can share.","pairs":[{"left":"Older brother","right":"Rocking the baby to sleep"},{"left":"Appa","right":"Packing the school lunch"},{"left":"Sister","right":"Helping a sibling with sums"},{"left":"Dadi","right":"Telling a bedtime story"},{"left":"You","right":"Tidying the play corner"}],"relearn":"Caring for family is shared by all, not just by the girls.","persona":"any","source":"gender-equal caregiving"},
  {"id":"fp-954","cat":"chores-shared","type":"match","hook":"Match each chore to a fair reason everyone should learn it.","pairs":[{"left":"Cooking","right":"So you can feed yourself one day"},{"left":"Washing up","right":"So clean-up is never one kid's"},{"left":"Mending clothes","right":"So you can fix your own"},{"left":"Caring for a baby","right":"So you're a kind, ready helper"},{"left":"Fixing small things","right":"So you don't wait on anyone"}],"relearn":"Home skills help every kid for life, whatever their gender.","persona":"any","source":"life skills"},
  {"id":"fp-990","cat":"equal-vs-equity","type":"branch","hook":"A tall cousin and a small cousin both want to pluck mangoes.","options":[{"text":"Hand the small cousin a stool so both can reach","consequence":"Both pluck mangoes; that's truly fair.","outcome":"equity","best":true},{"text":"Tell them to jump the same height","consequence":"Only the tall one reaches; same rule, unfair."}],"debrief":"Fair can mean a little extra help so everyone joins.","relearn":"Fair isn't always 'the same'; it's each getting what they need.","persona":"Kabir-type","source":"equity"},
  {"id":"fp-991","cat":"equal-vs-equity","type":"branch","hook":"At the water cooler, the smallest kid can't reach the tap.","options":[{"text":"Bring a stool so they can reach it themselves","consequence":"They pour their own water; same drink, fair help.","outcome":"equity","best":true},{"text":"Say everyone reaches the same way","consequence":"The small kid stays thirsty; sameness isn't fair."}],"debrief":"Removing a barrier so someone can join is fair.","relearn":"Removing a barrier so someone can take part is fair.","persona":"any","source":"equity / access"},
  {"id":"fp-992","cat":"equal-vs-equity","type":"branch","hook":"One classmate uses a wheelchair; the cricket game is on the grass.","options":[{"text":"Move the game to the smooth court so they can play too","consequence":"Everyone plays together; that's a fair fix.","outcome":"equity","best":true},{"text":"Keep it on grass, same field for all","consequence":"They can't join; same place isn't fair for everyone."}],"debrief":"Changing the spot so everyone can play is fair play.","relearn":"Removing a barrier so everyone can play is fair.","persona":"Kabir-type","source":"equity / inclusion"},
  {"id":"fp-993","cat":"equal-vs-equity","type":"branch","hook":"A friend who reads slower is given the same five minutes for a long page.","options":[{"text":"Let them have a little more time to finish","consequence":"They read it all; the goal is the same, the help fits.","outcome":"equity","best":true},{"text":"Stop everyone at five minutes flat","consequence":"They miss the end; equal time wasn't fair to them."}],"debrief":"More time for who needs it is fair, not unfair to the rest.","relearn":"Meeting a different need is still fair.","persona":"any","source":"equity"},
  {"id":"fp-994","cat":"equal-vs-equity","type":"branch","hook":"Lunch is shared: one friend skipped breakfast, the rest ate well.","options":[{"text":"Give the hungry friend a bit more this time","consequence":"They're not hungry now; kindness reads the need.","outcome":"equity","best":true},{"text":"Split it into exactly equal piles","consequence":"They stay hungry; equal isn't always fair."}],"debrief":"Sometimes fair means giving by need, not by exact halves.","relearn":"Sometimes fair means giving by need, not equal shares.","persona":"any","source":"equity"},
  {"id":"fp-995","cat":"equal-vs-equity","type":"branch","hook":"A new boy at school can't read the board from the back.","options":[{"text":"Swap him to a front seat so he can see","consequence":"He sees the lesson; same class, fair help.","outcome":"equity","best":true},{"text":"Say seats are fixed, same for all","consequence":"He keeps missing the board; sameness left him out."}],"debrief":"A small change so someone can see is a fair move.","relearn":"Fair help fits what each person actually needs.","persona":"Kabir-type","source":"equity / access"},
  {"id":"fp-996","cat":"equal-vs-equity","type":"branch","hook":"Sharing one bicycle: your cousin has never learned to ride.","options":[{"text":"Hold the seat steady while they learn first","consequence":"Soon they ride too; extra help got them started.","outcome":"equity","best":true},{"text":"Make them ride solo right away like you","consequence":"They keep falling; the same start wasn't fair."}],"debrief":"Extra help to start is fair, then everyone joins in.","relearn":"Helping someone who needs more is fair.","persona":"any","source":"equity"},
  {"id":"fp-997","cat":"equal-vs-equity","type":"branch","hook":"In the school race, one runner is much younger than the rest.","options":[{"text":"Give the youngest a small head start","consequence":"The race feels fair and fun for everyone.","outcome":"equity","best":true},{"text":"Same start line for all, no changes","consequence":"The youngest can never win; equal felt unfair."}],"debrief":"A fair tweak so everyone has a real chance is good play.","relearn":"Fair play can mean small adjustments so everyone joins.","persona":"any","source":"equity / fair play"},
  {"id":"fp-998","cat":"equal-vs-equity","type":"branch","hook":"A friend who can't hear well sits far from the teacher.","options":[{"text":"Offer them the front seat near the teacher","consequence":"They hear the lesson; fair help, same class.","outcome":"equity","best":true},{"text":"Keep seats by height like always","consequence":"They miss half the words; sameness wasn't fair."}],"debrief":"Meeting a hearing need is fair, not special treatment.","relearn":"Meeting a different need is still fair.","persona":"Kabir-type","source":"equity / access"},
  {"id":"fp-999","cat":"equal-vs-equity","type":"branch","hook":"Painting time: there's one left-handed kid and only right-set scissors.","options":[{"text":"Find left-handed scissors so they can cut too","consequence":"They cut neatly; the right tool made it fair.","outcome":"equity","best":true},{"text":"Say everyone uses the same scissors","consequence":"They struggle and give up; same tool wasn't fair."}],"debrief":"The right tool for a different need is a fair fix.","relearn":"Fair help fits what each person actually needs.","persona":"any","source":"equity / access"},
  {"id":"fp-1000","cat":"equal-vs-equity","type":"branch","hook":"Two kids share homework help: one already gets it, one is lost.","options":[{"text":"Spend more time with the one who's stuck","consequence":"Both end up understanding; help went where needed.","outcome":"equity","best":true},{"text":"Give each exactly equal minutes","consequence":"The stuck one stays lost; equal time wasn't fair."}],"debrief":"Help that goes where it's needed is real fairness.","relearn":"Extra help for someone who needs more is fair.","persona":"any","source":"equity"},
  {"id":"fp-1001","cat":"equal-vs-equity","type":"branch","hook":"During break, one friend uses crutches and the bench is far.","options":[{"text":"Bring a closer chair so they can rest too","consequence":"They rest with everyone; a small fair fix.","outcome":"equity","best":true},{"text":"Say the bench is the same for all","consequence":"They stand tired; equal seating left them out."}],"debrief":"A closer seat for who needs it is fair, not unfair.","relearn":"Removing a barrier so someone can take part is fair.","persona":"Kabir-type","source":"equity / access"},
  {"id":"fp-1002","cat":"equal-vs-equity","type":"branch","hook":"Sharing a story turn: one shy friend freezes when it's their go.","options":[{"text":"Let them tell it with a friend beside them","consequence":"They share their story too; gentle help, same turn.","outcome":"equity","best":true},{"text":"Make them stand alone like everyone else","consequence":"They stay silent; the same way wasn't fair to them."}],"debrief":"A gentle adjustment so everyone gets their turn is fair.","relearn":"Meeting a different need is still fair.","persona":"any","source":"equity"},
  {"id":"fp-1003","cat":"equal-vs-equity","type":"branch","hook":"Your team shares one umbrella in the rain; one kid is already soaked and cold.","options":[{"text":"Give the cold, soaked friend the umbrella first","consequence":"They warm up; sharing by need is kind and fair.","outcome":"equity","best":true},{"text":"Pass it for equal seconds each","consequence":"The cold one shivers longer; equal wasn't fair now."}],"debrief":"Sharing by who needs it most can be the fair call.","relearn":"Sometimes fair means giving by need, not equal shares.","persona":"any","source":"equity"},
  {"id":"fp-1004","cat":"equal-vs-equity","type":"branch","hook":"A friend who's unwell can't carry their heavy bag up the stairs today.","options":[{"text":"Offer to carry it for them just today","consequence":"They make it up fine; help fit the day's need.","outcome":"equity","best":true},{"text":"Say everyone carries their own, no help","consequence":"They struggle and hurt; same rule wasn't fair today."}],"debrief":"Helping for a one-day need is fair, not breaking a rule.","relearn":"Helping someone who needs more is fair.","persona":"Kabir-type","source":"equity"},
  {"id":"fp-1005","cat":"equal-vs-equity","type":"branch","hook":"Group game uses written clues; one classmate can't read yet.","options":[{"text":"Read the clues aloud so they can play too","consequence":"They join the hunt; same game, fair help.","outcome":"equity","best":true},{"text":"Hand everyone the same paper clues","consequence":"They're stuck out; the same way left them behind."}],"debrief":"Reading aloud so everyone can join is a fair fix.","relearn":"Removing a barrier so someone can take part is fair.","persona":"any","source":"equity / inclusion"},
  {"id":"fp-1006","cat":"equal-vs-equity","type":"branch","hook":"On a hot walk, one younger sibling tires faster than the rest.","options":[{"text":"Take short breaks so the youngest can keep up","consequence":"Everyone arrives together; pacing was the fair move.","outcome":"equity","best":true},{"text":"Walk the same fast pace for all","consequence":"The youngest falls behind; the same pace wasn't fair."}],"debrief":"Pacing for who needs it keeps the group together fairly.","relearn":"Fair play can mean small adjustments so everyone joins.","persona":"any","source":"equity"},
  {"id":"fp-1007","cat":"equal-vs-equity","type":"branch","hook":"One friend in the play has the most lines but gets terribly nervous.","options":[{"text":"Let them hold a cue card to read from","consequence":"They get through their part; a fair, kind aid.","outcome":"equity","best":true},{"text":"Make them memorise it all like everyone","consequence":"They blank on stage; the same rule wasn't fair."}],"debrief":"A small aid for a real need is fair, not cheating.","relearn":"Meeting a different need is still fair.","persona":"Kabir-type","source":"equity"},
  {"id":"fp-1008","cat":"equal-vs-equity","type":"branch","hook":"Library time: one classmate needs big-print books to read comfortably.","options":[{"text":"Find them a large-print copy of the same story","consequence":"They read along happily; same story, fair help.","outcome":"equity","best":true},{"text":"Give everyone the identical small-print book","consequence":"They squint and quit; the same book wasn't fair."}],"debrief":"The right version for a different need is fair.","relearn":"Fair help fits what each person actually needs.","persona":"any","source":"equity / access"},
  {"id":"fp-1009","cat":"equal-vs-equity","type":"branch","hook":"Sharing the one ladder at the slide: a toddler cousin can't climb alone.","options":[{"text":"Steady the toddler up while the rest climb solo","consequence":"Everyone slides; the help matched the age.","outcome":"equity","best":true},{"text":"Make the toddler climb unhelped like the big kids","consequence":"They get stuck and cry; same rule wasn't fair."}],"debrief":"Different help by age can be the fair thing to do.","relearn":"Helping someone who needs more is fair.","persona":"any","source":"equity"},
  {"id":"fp-1010","cat":"equal-vs-equity","type":"branch","hook":"Snack is one big roti split for four; one friend can't eat wheat.","options":[{"text":"Get them a rice snack so they have something too","consequence":"Everyone eats; a different snack met their need.","outcome":"equity","best":true},{"text":"Give them an equal piece of the roti anyway","consequence":"They can't eat it; equal shares weren't fair here."}],"debrief":"A different food for a real need is fair sharing.","relearn":"Meeting a different need is still fair.","persona":"Kabir-type","source":"equity"},
  {"id":"fp-1011","cat":"equal-vs-equity","type":"branch","hook":"Team relay: one runner sprained their ankle but still wants to take part.","options":[{"text":"Give them the short, easy leg of the relay","consequence":"They join in safely; a fair role for today.","outcome":"equity","best":true},{"text":"Make everyone run the same long leg","consequence":"They get hurt or sit out; same leg wasn't fair."}],"debrief":"A fair role that fits a need keeps everyone in the game.","relearn":"Fair play can mean small adjustments so everyone joins.","persona":"any","source":"equity / fair play"},
  {"id":"fp-1012","cat":"equal-vs-equity","type":"branch","hook":"Drawing class: one classmate's hands shake, so a thin pencil slips.","options":[{"text":"Offer them a chunky grip pencil that's easier to hold","consequence":"They draw with everyone; the right tool helped.","outcome":"equity","best":true},{"text":"Hand out the same thin pencils to all","consequence":"Their lines wobble and they give up; same wasn't fair."}],"debrief":"A tool that fits a need is a fair, quiet kindness.","relearn":"Fair help fits what each person actually needs.","persona":"Kabir-type","source":"equity / access"},
  {"id":"fp-1013","cat":"equal-vs-equity","type":"strike-rewrite","hook":"\"Helping one kid more than the others is just unfair to everyone else.\"","myth":{"un":"Giving one kid extra help is unfair to the rest.","re":"Helping someone meet a real need is fair, not unfair to others.","why":"Filling a need doesn't take anything away from anyone."},"relearn":"Extra help for a real need is fair, not favouritism.","persona":"Kabir-type","source":"equity"},
  {"id":"fp-1014","cat":"equal-vs-equity","type":"strike-rewrite","hook":"\"If we don't all get the exact same thing, it can't be fair.\"","myth":{"un":"Fair only counts when everyone gets the exact same thing.","re":"Fair can mean different help so everyone can take part.","why":"People start from different needs, so the same isn't always fair."},"relearn":"Fair can mean meeting different needs, not identical shares.","persona":"any","source":"equity"},
  {"id":"fp-1015","cat":"equal-vs-equity","type":"strike-rewrite","hook":"\"A ramp or a front seat is special treatment that no one else gets.\"","myth":{"un":"A ramp or front seat is special treatment for one kid.","re":"It just removes a barrier so they can join like everyone else.","why":"Fair means everyone can take part, and that sometimes needs a change."},"relearn":"Removing a barrier so someone can take part is fair.","persona":"Kabir-type","source":"equity / access"},
  {"id":"fp-1016","cat":"equal-vs-equity","type":"strike-rewrite","hook":"\"The same rule for everyone is always the fairest rule.\"","myth":{"un":"The same rule for everyone is always the fairest.","re":"Sometimes the same rule fits all, and sometimes a tailored one is fairer.","why":"Whether same or tailored is fair depends on the situation."},"relearn":"Same and tailored are both forms of fair; you judge which fits.","persona":"any","source":"equity"},
  {"id":"fp-1017","cat":"equal-vs-equity","type":"strike-rewrite","hook":"\"Treating people differently always means someone's being favoured.\"","myth":{"un":"Treating people differently always means favouritism.","re":"Giving each what they need is fairness, not picking favourites.","why":"It aims for everyone to take part, not to spoil one person."},"relearn":"Meeting different needs is fairness, not favouritism.","persona":"Kabir-type","source":"equity"},
  {"id":"fp-1018","cat":"equal-vs-equity","type":"strike-rewrite","hook":"\"Equal and equity are just the same word for the same thing.\"","myth":{"un":"Equal and equity mean exactly the same thing.","re":"Equal is the same for all; equity is what each person needs.","why":"Both can be fair, but they're different ways to share."},"relearn":"Equality and equity are both forms of fair, in different ways.","persona":"any","source":"equity"},
  {"id":"fp-1019","cat":"equal-vs-equity","type":"strike-rewrite","hook":"\"If you help the slow ones, it isn't fair to the fast ones.\"","myth":{"un":"Helping the ones who struggle is unfair to the quick ones.","re":"Help where it's needed lets everyone reach the same goal.","why":"The fast ones lose nothing when a friend gets a hand."},"relearn":"Help that goes where it's needed is real fairness.","persona":"any","source":"equity"},
  {"id":"fp-1020","cat":"equal-vs-equity","type":"sort","hook":"Sort: meets a real need, or only looks equal?","items":[{"id":"a","text":"A stool so a short kid reaches the tap"},{"id":"b","text":"One cup each, even a kid who ran far"},{"id":"c","text":"More time for a slower reader"},{"id":"d","text":"Same fast pace for all, even the youngest"},{"id":"e","text":"A ramp so a wheelchair can enter"},{"id":"f","text":"Front seat for the tallest, not who can't see"}],"bins":[{"id":"fair","label":"Fair 💚","valence":"pos"},{"id":"no","label":"Only looks equal 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Meeting needs is fair, even when it's not identical.","persona":"any","source":"equity"},
  {"id":"fp-1021","cat":"equal-vs-equity","type":"sort","hook":"Sort: a fair fix, or unfair sameness?","items":[{"id":"a","text":"Read clues aloud for a kid who can't read"},{"id":"b","text":"A big-print book for who needs it"},{"id":"c","text":"Only paper clues, same for all"},{"id":"d","text":"Left scissors for a lefty kid"},{"id":"e","text":"Right-only scissors for everyone"},{"id":"f","text":"Stairs only, no ramp"}],"bins":[{"id":"fair","label":"Fair fix 💚","valence":"pos"},{"id":"no","label":"Unfair sameness 🛑","valence":"neg"}],"key":{"a":"fair","b":"fair","c":"no","d":"fair","e":"no","f":"no"},"relearn":"Real fairness removes barriers so everyone can take part.","persona":"any","source":"equity / access"},
  {"id":"fp-1022","cat":"equal-vs-equity","type":"sort","hook":"Sort: shared by need, or split blind?","items":[{"id":"a","text":"Umbrella first to a soaked friend"},{"id":"b","text":"More lunch for who skipped breakfast"},{"id":"c","text":"Equal umbrella time while one shivers"},{"id":"d","text":"Equal lunch, even for a hungry friend"},{"id":"e","text":"A break so the youngest keeps up"},{"id":"f","text":"Same fast walk, youngest behind"}],"bins":[{"id":"need","label":"By need 💚","valence":"pos"},{"id":"blind","label":"Split blind 🛑","valence":"neg"}],"key":{"a":"need","b":"need","c":"blind","d":"blind","e":"need","f":"blind"},"relearn":"Sometimes fair means giving by need, not equal shares.","persona":"any","source":"equity"},
  {"id":"fp-1023","cat":"equal-vs-equity","type":"sort","hook":"Sort: fair help for a need, or special treatment?","items":[{"id":"a","text":"A cue card for a nervous friend"},{"id":"b","text":"A grip pencil for shaky hands"},{"id":"c","text":"Picking your best friend to win"},{"id":"d","text":"A closer seat for a kid on crutches"},{"id":"e","text":"Skipping a kid's turn for yours"},{"id":"f","text":"Front seat for who can't hear well"}],"bins":[{"id":"fair","label":"Fair help 💚","valence":"pos"},{"id":"no","label":"Not fair 🛑","valence":"neg"}],"key":{"a":"fair","b":"fair","c":"no","d":"fair","e":"no","f":"fair"},"relearn":"Meeting a real need is fair; rigging things for yourself isn't.","persona":"any","source":"equity"},
  {"id":"fp-1024","cat":"equal-vs-equity","type":"sort","hook":"Sort: same rule fits, or needs a tailored fix?","items":[{"id":"a","text":"Everyone lines up for the slide"},{"id":"b","text":"A head start for the youngest"},{"id":"c","text":"All wash their own plate"},{"id":"d","text":"A short relay leg for a sore ankle"},{"id":"e","text":"All keep quiet in the test"},{"id":"f","text":"More time for a slower reader"}],"bins":[{"id":"same","label":"Same fits 💚","valence":"pos"},{"id":"tailor","label":"Tailor it 📦","valence":"neutral"}],"key":{"a":"same","b":"tailor","c":"same","d":"tailor","e":"same","f":"tailor"},"relearn":"Same and tailored are both forms of fair; you judge which fits.","persona":"any","source":"equity"},
  {"id":"fp-1025","cat":"equal-vs-equity","type":"sort","hook":"Sort: includes everyone, or leaves someone out?","items":[{"id":"a","text":"Steady the toddler up the ladder"},{"id":"b","text":"A rice snack for who can't eat wheat"},{"id":"c","text":"Make the toddler climb unhelped"},{"id":"d","text":"Equal roti to the wheat-allergic friend"},{"id":"e","text":"A friend beside the shy kid's turn"},{"id":"f","text":"Make the shy kid stand alone"}],"bins":[{"id":"in","label":"Includes all 💚","valence":"pos"},{"id":"out","label":"Leaves out 🛑","valence":"neg"}],"key":{"a":"in","b":"in","c":"out","d":"out","e":"in","f":"out"},"relearn":"Fairness is about everyone being able to take part.","persona":"any","source":"equity / inclusion"},
  {"id":"fp-1026","cat":"equal-vs-equity","type":"sort","hook":"Sort: a fair tweak, or 'same for all' that shuts out?","items":[{"id":"a","text":"Move cricket to a smooth court"},{"id":"b","text":"Short breaks so the youngest keeps up"},{"id":"c","text":"Keep cricket on the same grass"},{"id":"d","text":"A stool so the small cousin reaches"},{"id":"e","text":"Tell the cousin to jump the same"},{"id":"f","text":"A closer chair for crutches"}],"bins":[{"id":"tweak","label":"Fair tweak 💚","valence":"pos"},{"id":"shut","label":"Shuts out 🛑","valence":"neg"}],"key":{"a":"tweak","b":"tweak","c":"shut","d":"tweak","e":"shut","f":"tweak"},"relearn":"Fair play can mean small adjustments so everyone joins.","persona":"any","source":"equity"},
  {"id":"fp-1027","cat":"equal-vs-equity","type":"sort","hook":"Sort: equity (each their need), or equality (same)?","items":[{"id":"a","text":"Front seat for who can't hear well"},{"id":"b","text":"Everyone gets one swing turn"},{"id":"c","text":"Extra reading time for who needs it"},{"id":"d","text":"All sit in a circle for story"},{"id":"e","text":"A grip pencil for shaky hands"},{"id":"f","text":"Each child gets one fruit"}],"bins":[{"id":"equity","label":"Equity 📦","valence":"neutral"},{"id":"equal","label":"Equality 💚","valence":"pos"}],"key":{"a":"equity","b":"equal","c":"equity","d":"equal","e":"equity","f":"equal"},"relearn":"Equality and equity are both forms of fair, in different ways.","persona":"any","source":"equity"},
  {"id":"fp-1028","cat":"equal-vs-equity","type":"sort","hook":"Sort: meets the need, or ignores it?","items":[{"id":"a","text":"Carry the unwell friend's bag today"},{"id":"b","text":"Hold the seat while a cousin learns"},{"id":"c","text":"Tell the unwell friend to manage"},{"id":"d","text":"Make the new cousin ride solo"},{"id":"e","text":"A stool so the smallest reaches"},{"id":"f","text":"Same high tap for all, no help"}],"bins":[{"id":"meets","label":"Meets need 💚","valence":"pos"},{"id":"ignores","label":"Ignores it 🛑","valence":"neg"}],"key":{"a":"meets","b":"meets","c":"ignores","d":"ignores","e":"meets","f":"ignores"},"relearn":"Helping someone who needs more is fair.","persona":"any","source":"equity"},
  {"id":"fp-1029","cat":"equal-vs-equity","type":"sort","hook":"Sort: a kind fair fix, or only looks fair?","items":[{"id":"a","text":"A big-print copy for a friend"},{"id":"b","text":"Read the board aloud for the back"},{"id":"c","text":"Same tiny print for all, no help"},{"id":"d","text":"Left scissors for a lefty kid"},{"id":"e","text":"Front seat just for your friend"},{"id":"f","text":"Move a new boy up to see the board"}],"bins":[{"id":"fair","label":"Fair fix 💚","valence":"pos"},{"id":"looks","label":"Only looks fair 🛑","valence":"neg"}],"key":{"a":"fair","b":"fair","c":"looks","d":"fair","e":"looks","f":"fair"},"relearn":"Fair help fits what each person actually needs.","persona":"any","source":"equity / access"},
  {"id":"fp-1030","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: think of a time a friend needed a bit of extra help.","prompt":"How did giving that help feel?","options":["Kind","Fair","Like the right thing"],"affirm":"Helping someone meet their need is real fairness.","relearn":"Extra help for a real need is fair, not unfair.","persona":"any","source":"equity"},
  {"id":"fp-1031","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: sometimes 'fair' and 'exactly the same' aren't the same thing.","prompt":"What do you make of that?","options":["Makes sense","A bit surprising","Fair fits the need"],"affirm":"Fair means everyone can truly take part, not just identical shares.","relearn":"Fairness is about everyone being able to take part.","persona":"any","source":"equity"},
  {"id":"fp-1032","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: a box to see over the wall, or more time to read.","prompt":"Which feels like fair help to you?","options":["Both do","The one that fits the need","Whatever lets them join"],"affirm":"Fair help is whatever lets each person truly take part.","relearn":"Fair help fits what each person actually needs.","persona":"any","source":"equity"},
  {"id":"fp-1033","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: a new friend needs a little more help to join the game.","prompt":"What feels fair to do?","options":["Help them a bit","Make space for them","Slow down so they can join"],"affirm":"Adjusting so everyone can join is real fairness.","relearn":"Fair play can mean small adjustments so everyone joins.","persona":"any","source":"equity / inclusion"},
  {"id":"fp-1034","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: a ramp lets a wheelchair friend get in the same door.","prompt":"What does that change feel like to you?","options":["Fair","Welcoming","Just right"],"affirm":"Removing a barrier so someone can join is a fair, kind thing.","relearn":"Removing a barrier so someone can take part is fair.","persona":"any","source":"equity / access"},
  {"id":"fp-1035","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: two friends, one already gets it, one is stuck.","prompt":"Who could use more of your help?","options":["The one who's stuck","Whoever needs it","Both, but more for the stuck one"],"affirm":"Help that goes where it's needed is real fairness.","relearn":"Help that goes where it's needed is real fairness.","persona":"any","source":"equity"},
  {"id":"fp-1036","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: sometimes the same rule fits all, sometimes a tweak is fairer.","prompt":"How do you decide which?","options":["Look at who's there","Ask what they need","See if anyone's left out"],"affirm":"Reading the situation to see what's fair is smart and kind.","relearn":"Same and tailored are both forms of fair; you judge which fits.","persona":"any","source":"equity"},
  {"id":"fp-1037","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: a friend who can't eat wheat gets a different snack.","prompt":"Does that feel fair to you?","options":["Yes","It meets their need","Everyone still gets to eat"],"affirm":"A different snack for a real need is fair sharing.","relearn":"Meeting a different need is still fair.","persona":"any","source":"equity"},
  {"id":"fp-1038","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: the youngest in the race got a small head start.","prompt":"How does that race feel now?","options":["Fairer","More fun for all","Everyone has a chance"],"affirm":"A fair tweak so everyone has a real chance is good play.","relearn":"Fair play can mean small adjustments so everyone joins.","persona":"any","source":"equity / fair play"},
  {"id":"fp-1039","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: helping the one who's struggling, not the one who's already fine.","prompt":"What do you think of that?","options":["Sounds fair","That's where help belongs","Both still reach the goal"],"affirm":"Help where it's needed lets everyone reach the same goal.","relearn":"Help that goes where it's needed is real fairness.","persona":"any","source":"equity"},
  {"id":"fp-1040","cat":"equal-vs-equity","type":"reflect","hook":"Lensy: a friend on crutches got the closer chair to rest.","prompt":"What does sharing like that feel like?","options":["Kind","Fair","Looking out for each other"],"affirm":"Sharing by who needs it is fairness in action.","relearn":"Sometimes fair means giving by need, not equal shares.","persona":"any","source":"equity / access"},
  {"id":"fp-1041","cat":"equal-vs-equity","type":"match","hook":"Match the friend's need to the fair help.","pairs":[{"left":"Can't reach the tap","right":"A stool to stand on"},{"left":"Reads slower","right":"A little more time"},{"left":"Can't hear well","right":"A front seat"},{"left":"Uses a wheelchair","right":"A ramp to the door"},{"left":"Can't eat wheat","right":"A rice snack instead"}],"relearn":"Fair help fits what each person actually needs.","persona":"Kabir-type","source":"equity"},
  {"id":"fp-1042","cat":"equal-vs-equity","type":"match","hook":"Match the barrier to the fair fix that removes it.","pairs":[{"left":"Clues are written, can't read yet","right":"Read them aloud"},{"left":"Print is too small","right":"A big-print copy"},{"left":"Hands shake on a thin pencil","right":"A chunky grip pencil"},{"left":"Right-only scissors","right":"A left-handed pair"},{"left":"Bench is too far on crutches","right":"A chair brought closer"}],"relearn":"Real fairness removes barriers so everyone can take part.","persona":"any","source":"equity / access"},
  {"id":"fp-1043","cat":"equal-vs-equity","type":"match","hook":"Match each situation to whether it's the same for all or a need being met.","pairs":[{"left":"Everyone gets one swing turn","right":"Same for all"},{"left":"Head start for the youngest","right":"Meeting a need"},{"left":"All wash their own plate","right":"Same job for all"},{"left":"More homework help for who's stuck","right":"Help where it's needed"},{"left":"Each gets one piece of fruit","right":"Equal shares"}],"relearn":"Equality and equity are both forms of fair, in different ways.","persona":"any","source":"equity"},
  {"id":"fp-1044","cat":"equal-vs-equity","type":"match","hook":"Match the kid to the small change that lets them join in.","pairs":[{"left":"Too short for the wall","right":"A box to stand on"},{"left":"Nervous with many lines","right":"A cue card to read"},{"left":"Sprained ankle in the relay","right":"The short, easy leg"},{"left":"Shy to tell a story alone","right":"A friend beside them"},{"left":"Toddler at the slide ladder","right":"A steadying hand up"}],"relearn":"Fair play can mean small adjustments so everyone joins.","persona":"any","source":"equity / inclusion"},
  {"id":"fp-1045","cat":"equal-vs-equity","type":"match","hook":"Match the fair idea to what it really means.","pairs":[{"left":"Equality","right":"The same for everyone"},{"left":"Equity","right":"What each one needs"},{"left":"Barrier","right":"Something that blocks joining in"},{"left":"Fair fix","right":"A change so all can take part"},{"left":"Favouritism","right":"Helping just because they're your friend"}],"relearn":"Equality and equity are both forms of fair, in different ways.","persona":"any","source":"equity"},
  {"id":"fp-1046","cat":"equal-vs-equity","type":"match","hook":"Match the person to the help that fits their day.","pairs":[{"left":"Soaked and cold in the rain","right":"The umbrella first"},{"left":"Skipped breakfast","right":"A bit more lunch"},{"left":"Unwell with a heavy bag","right":"A hand carrying it today"},{"left":"Tired and youngest on the walk","right":"A short rest break"},{"left":"New and can't ride yet","right":"A steadied bicycle seat"}],"relearn":"Sometimes fair means giving by need, not equal shares.","persona":"any","source":"equity"},
  {"id":"fp-1047","cat":"equal-vs-equity","type":"build","hook":"Build a fair plan so everyone can watch the match over the wall.","prompt":"Pick what makes it fair for all.","pieces":["a box for the shortest kid","the same view for everyone","help whoever can't see","tell the short kid to manage"],"mode":"assemble","key":["a box for the shortest kid","the same view for everyone","help whoever can't see"],"relearn":"Fair can mean different help so everyone gets the same view.","persona":"any","source":"equity"},
  {"id":"fp-1048","cat":"equal-vs-equity","type":"build","hook":"Build a fair way to include a wheelchair-using friend in play.","prompt":"Pick the moves that let everyone join.","pieces":["choose a smooth, flat spot","add a ramp at the door","make sure they get turns","keep it on the bumpy grass"],"mode":"assemble","key":["choose a smooth, flat spot","add a ramp at the door","make sure they get turns"],"relearn":"Removing barriers so everyone can play is fair play.","persona":"Kabir-type","source":"equity / inclusion"},
  {"id":"fp-1049","cat":"equal-vs-equity","type":"build","hook":"Build a fair reading time for a class with different needs.","prompt":"Pick what meets each need fairly.","pieces":["more time for slower readers","a big-print book if needed","read aloud for who can't read yet","one tiny-print page for all"],"mode":"assemble","key":["more time for slower readers","a big-print book if needed","read aloud for who can't read yet"],"relearn":"Fair help fits what each reader actually needs.","persona":"any","source":"equity / access"},
  {"id":"fp-1050","cat":"equal-vs-equity","type":"build","hook":"Build a fair snack share for friends with different needs.","prompt":"Pick what makes the sharing fair.","pieces":["a wheat-free snack for who needs it","a bit more for the hungriest","everyone gets something to eat","equal piles, ignore allergies"],"mode":"assemble","key":["a wheat-free snack for who needs it","a bit more for the hungriest","everyone gets something to eat"],"relearn":"Fair sharing meets needs, so everyone gets to eat.","persona":"any","source":"equity"},
  {"id":"fp-1051","cat":"equal-vs-equity","type":"build","hook":"Build a fair race where the youngest still has a real chance.","prompt":"Pick the fair touches.","pieces":["a small head start for the youngest","cheer on everyone","same finish line for all","make the youngest start far back"],"mode":"assemble","key":["a small head start for the youngest","cheer on everyone","same finish line for all"],"relearn":"A fair tweak so everyone has a real chance is good play.","persona":"any","source":"equity / fair play"},
  {"id":"fp-1052","cat":"equal-vs-equity","type":"build","hook":"Build a fair seating plan for a class with different needs.","prompt":"Pick what helps each kid take part.","pieces":["front seat for who can't hear well","front seat for who can't see the board","let others sit where they like","fixed seats, no changes ever"],"mode":"assemble","key":["front seat for who can't hear well","front seat for who can't see the board","let others sit where they like"],"relearn":"Small seating changes for real needs are fair.","persona":"Kabir-type","source":"equity / access"},
  {"id":"fp-1053","cat":"equal-vs-equity","type":"build","hook":"Build a fair team where a smaller, younger player still belongs.","prompt":"Pick the fair adjustments.","pieces":["give them a role that fits","take turns at the hard jobs","help them learn the game","make them keep up exactly"],"mode":"assemble","key":["give them a role that fits","take turns at the hard jobs","help them learn the game"],"relearn":"Fair play can mean small adjustments so everyone joins.","persona":"any","source":"equity / inclusion"},
  {"id":"fp-1054","cat":"equal-vs-equity","type":"build","hook":"Build a fair plan to decide same-for-all or a tailored fix.","prompt":"Pick the steps to judge what's fair.","pieces":["look at who's taking part","ask what each one needs","check no one is left out","just give everyone the exact same"],"mode":"assemble","key":["look at who's taking part","ask what each one needs","check no one is left out"],"relearn":"Same and tailored are both forms of fair; you judge which fits.","persona":"any","source":"equity"},
  {"id":"fp-1055","cat":"equal-vs-equity","type":"role-play","hook":"A friend says giving the short kid a box is 'unfair to the rest'.","setup":"Explain it kindly. Say:","yourLine":[{"text":"\"It just helps them see too, it takes nothing from us.\"","best":true},{"text":"Shrug and take the box away"}],"relearn":"A need being met takes nothing away from anyone else.","persona":"Kabir-type","source":"equity / voice"},
  {"id":"fp-1056","cat":"equal-vs-equity","type":"role-play","hook":"Someone grumbles that the slower reader 'shouldn't get extra time'.","setup":"Stand up for the fair fix. Say:","yourLine":[{"text":"\"More time helps them finish, we all reach the same page.\"","best":true},{"text":"Say nothing and look away"}],"relearn":"Help where it's needed lets everyone reach the same goal.","persona":"Ananya","source":"equity / voice"},
  {"id":"fp-1057","cat":"equal-vs-equity","type":"role-play","hook":"A classmate calls the wheelchair friend's ramp 'special treatment'.","setup":"Set it straight, calmly. Say:","yourLine":[{"text":"\"It's not special, it just lets them use the same door.\"","best":true},{"text":"Agree to keep the peace"}],"relearn":"Removing a barrier so someone can join is fair, not special.","persona":"Kabir-type","source":"equity / access / voice"},
  {"id":"fp-1058","cat":"equal-vs-equity","type":"role-play","hook":"A friend wants to split snacks exactly equally, ignoring the kid who skipped breakfast.","setup":"Suggest the fair share. Say:","yourLine":[{"text":"\"Let's give them a bit more, they're really hungry today.\"","best":true},{"text":"\"No, exactly equal or nothing.\""}],"relearn":"Sometimes fair means giving by need, not equal shares.","persona":"any","source":"equity / voice"},
  {"id":"fp-1059","cat":"equal-vs-equity","type":"role-play","hook":"Your little cousin can't reach the mangoes and others say 'too bad'.","setup":"Offer the fair fix. Say:","yourLine":[{"text":"\"Here, stand on this stool, now you can reach too.\"","best":true},{"text":"\"You're just too small, sorry.\""}],"relearn":"A little extra help so everyone can join is fair.","persona":"any","source":"equity / voice"},
  {"id":"fp-1060","cat":"equal-vs-equity","type":"role-play","hook":"A friend who can't hear well is stuck at the back row.","setup":"Speak up for them. Say:","yourLine":[{"text":"\"Can they sit up front? They hear the lesson better there.\"","best":true},{"text":"Leave them where they are"}],"relearn":"Asking for a fix that meets a need is a fair, brave move.","persona":"Ananya","source":"equity / access / voice"},
  {"id":"fp-1061","cat":"equal-vs-equity","type":"role-play","hook":"Kids say the wheat-allergic friend should 'just eat the same roti'.","setup":"Find a fair way. Say:","yourLine":[{"text":"\"Let's get them a rice snack so they can eat too.\"","best":true},{"text":"\"Same food for all, no fuss.\""}],"relearn":"A different snack for a real need is fair sharing.","persona":"Kabir-type","source":"equity / voice"},
  {"id":"fp-1062","cat":"equal-vs-equity","type":"role-play","hook":"A teammate with a sore ankle is told to run the same long leg.","setup":"Suggest the fair swap. Say:","yourLine":[{"text":"\"Give them the short leg today, so they can still play.\"","best":true},{"text":"\"Rules are rules, run it.\""}],"relearn":"A fair role that fits a need keeps everyone in the game.","persona":"any","source":"equity / fair play / voice"},
  {"id":"fp-1080","cat":"fair-everywhere","type":"branch","hook":"At the bus stop, big kids push to the front and little ones wait.","options":[{"text":"Say \"let's make a line and board by turns\"","consequence":"A queue forms; the little ones get on too.","outcome":"fair","best":true},{"text":"Push to the front yourself","consequence":"The smallest kids keep getting left behind.","outcome":"unfair"}],"debrief":"Fair turns work at the bus stop like anywhere else.","relearn":"A turn-by-turn line is fairer than pushing in.","persona":"any","source":"fair-everywhere / turns"},
  {"id":"fp-1081","cat":"fair-everywhere","type":"branch","hook":"Your group won't let a new kid join the kabaddi game.","options":[{"text":"Say \"come play, we'll add you to a team\"","consequence":"The new kid joins; the game's just as fun.","outcome":"fair","best":true},{"text":"Tell them \"you can't play with us\"","consequence":"They walk off alone; leaving people out isn't fair.","outcome":"unfair"}],"debrief":"Including everyone in play is the fair move, anywhere.","relearn":"\"You can't play with us\" isn't fair; including is.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1082","cat":"fair-everywhere","type":"branch","hook":"Your cousins visit; only one cricket bat for six kids.","options":[{"text":"Set up batting turns so each cousin bats","consequence":"Everyone bats and the game lasts all afternoon.","outcome":"fair","best":true},{"text":"Keep the bat because it's yours","consequence":"Your cousins sit out and the fun fizzles.","outcome":"unfair"}],"debrief":"One bat, many kids: turns make it fair for the whole group.","relearn":"Sharing the bat by turns keeps play fair for everyone.","persona":"any","source":"fair-everywhere / turns"},
  {"id":"fp-1084","cat":"fair-everywhere","type":"branch","hook":"You scored the winning goal and feel like showing off to the team that lost.","options":[{"text":"Shake hands and say \"great match\"","consequence":"Both teams leave happy and want to play again.","outcome":"fair","best":true},{"text":"Brag and tease the losing team","consequence":"Gloating spoils the game; no one wants you next time.","outcome":"unfair"}],"debrief":"Being a kind winner is part of fair play, win or lose.","relearn":"A fair player is a kind winner, not a gloater.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1087","cat":"fair-everywhere","type":"branch","hook":"At a birthday party, the cake's cut and you're handed the biggest slice.","options":[{"text":"Say \"let's make the slices about equal\"","consequence":"Every kid gets a fair piece and no one sulks.","outcome":"fair","best":true},{"text":"Take the big slice and say nothing","consequence":"Other kids feel short-changed; that's not fair.","outcome":"unfair"}],"debrief":"A fair share of cake is the same idea as a fair share at home.","relearn":"Roughly equal shares are fairer than grabbing the biggest.","persona":"any","source":"fair-everywhere / fair shares"},
  {"id":"fp-1088","cat":"fair-everywhere","type":"branch","hook":"Your team is winning big and the other side looks like giving up.","options":[{"text":"Pass to weaker players and keep it close","consequence":"The game stays fun and everyone wants to finish.","outcome":"fair","best":true},{"text":"Keep piling on the score","consequence":"The other side gives up; a one-sided game isn't fun for anyone.","outcome":"unfair"}],"debrief":"A fair player keeps the game fun, not just chases the score.","relearn":"Keeping the game fun for both sides is fair play.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1092","cat":"fair-everywhere","type":"branch","hook":"At the snack stall after school, your group always serves boys first.","options":[{"text":"Say \"let's just go by who's next in line\"","consequence":"Everyone's served by turn, no gender goes first.","outcome":"fair","best":true},{"text":"Let boys keep going first","consequence":"The girls always wait; that's an unfair habit.","outcome":"unfair"}],"debrief":"Fair turns aren't decided by gender, at the stall or anywhere.","relearn":"Serve by who's next, not by gender.","persona":"Ananya","source":"fair-everywhere / fair shares"},
  {"id":"fp-1097","cat":"fair-everywhere","type":"sort","hook":"Sort these moves at home and play: fair, or not fair?","items":[{"id":"a","text":"Taking turns with the one cricket bat"},{"id":"b","text":"Hiding the dice so you win"},{"id":"c","text":"Splitting the chips about equally"},{"id":"d","text":"Hogging the swing all evening"},{"id":"e","text":"Saying \"good game\" after winning"},{"id":"f","text":"Teasing the kid who lost"}],"bins":[{"id":"fair","label":"Fair 💚","valence":"pos"},{"id":"no","label":"Not fair 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair everywhere: share turns, play clean, win kindly.","persona":"any","source":"fair-everywhere / sort"},
  {"id":"fp-1098","cat":"fair-everywhere","type":"sort","hook":"Sort: a real, fair win, or not a fair win?","items":[{"id":"a","text":"Winning by playing your best"},{"id":"b","text":"Winning by peeking at the answers"},{"id":"c","text":"Winning after a fair, close game"},{"id":"d","text":"Winning by tripping the other runner"},{"id":"e","text":"Winning and shaking hands"},{"id":"f","text":"Winning by changing the score sheet"}],"bins":[{"id":"real","label":"Real, fair win 💚","valence":"pos"},{"id":"no","label":"Not a fair win 🛑","valence":"neg"}],"key":{"a":"real","b":"no","c":"real","d":"no","e":"real","f":"no"},"relearn":"A win by cheating isn't a real win; clean wins are.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1099","cat":"fair-everywhere","type":"sort","hook":"Sort: keeps play fun for everyone, or spoils it?","items":[{"id":"a","text":"Letting a younger kid join your team"},{"id":"b","text":"Saying \"no girls allowed\""},{"id":"c","text":"Cheering a good shot by either side"},{"id":"d","text":"Quitting the moment you lose"},{"id":"e","text":"Explaining the rules to a new player"},{"id":"f","text":"Bragging and putting others down"}],"bins":[{"id":"fun","label":"Keeps it fun 💚","valence":"pos"},{"id":"spoil","label":"Spoils it 🛑","valence":"neg"}],"key":{"a":"fun","b":"spoil","c":"fun","d":"spoil","e":"fun","f":"spoil"},"relearn":"Fair players keep play fun and open for everyone.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1100","cat":"fair-everywhere","type":"sort","hook":"Sort where these belong: fair at home, or unfair at home?","items":[{"id":"a","text":"Everyone gets a turn choosing dinner"},{"id":"b","text":"Only one kid is always served last"},{"id":"c","text":"Siblings split chores by turns"},{"id":"d","text":"One kid grabs all the dessert"},{"id":"e","text":"Sharing the phone by a timer"},{"id":"f","text":"The youngest never gets a say"}],"bins":[{"id":"fair","label":"Fair at home 💚","valence":"pos"},{"id":"no","label":"Unfair at home 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair shares and turns belong at home as much as at play.","persona":"any","source":"fair-everywhere / fair shares"},
  {"id":"fp-1101","cat":"fair-everywhere","type":"sort","hook":"Sort: a kind-winner move, or a sore-winner move?","items":[{"id":"a","text":"\"Good game, you played well\""},{"id":"b","text":"\"We're way better than you\""},{"id":"c","text":"Helping pack up the gear together"},{"id":"d","text":"Doing a victory dance in their faces"},{"id":"e","text":"Inviting them for a rematch"},{"id":"f","text":"Calling the losers names"}],"bins":[{"id":"kind","label":"Kind winner 💚","valence":"pos"},{"id":"sore","label":"Sore winner 🛑","valence":"neg"}],"key":{"a":"kind","b":"sore","c":"kind","d":"sore","e":"kind","f":"sore"},"relearn":"A kind winner respects the other side; a sore one gloats.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1102","cat":"fair-everywhere","type":"sort","hook":"Sort: fair turn-taking, or someone hogging?","items":[{"id":"a","text":"A turn-list for the one bicycle"},{"id":"b","text":"One kid riding it all week"},{"id":"c","text":"Passing the ball around the team"},{"id":"d","text":"Keeping the ball to yourself"},{"id":"e","text":"Timer on the video game per player"},{"id":"f","text":"Playing the game alone for hours"}],"bins":[{"id":"turns","label":"Fair turns 💚","valence":"pos"},{"id":"hog","label":"Hogging 🛑","valence":"neg"}],"key":{"a":"turns","b":"hog","c":"turns","d":"hog","e":"turns","f":"hog"},"relearn":"Fair turns pass the fun around; hogging keeps it for one.","persona":"any","source":"fair-everywhere / turns"},
  {"id":"fp-1103","cat":"fair-everywhere","type":"sort","hook":"Sort these playground rules: fair rule, or unfair rule?","items":[{"id":"a","text":"\"Whoever's next gets the next turn\""},{"id":"b","text":"\"Only my friends can play\""},{"id":"c","text":"\"We rotate who picks teams\""},{"id":"d","text":"\"Losers can't play the next round\""},{"id":"e","text":"\"Everyone bats once before repeats\""},{"id":"f","text":"\"The tallest always goes first\""}],"bins":[{"id":"fair","label":"Fair rule 💚","valence":"pos"},{"id":"no","label":"Unfair rule 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair rules give everyone a turn; unfair ones favour a few.","persona":"any","source":"fair-everywhere / rules"},
  {"id":"fp-1104","cat":"fair-everywhere","type":"sort","hook":"Sort: including everyone in play, or shutting someone out?","items":[{"id":"a","text":"\"Come join, you're on my side\""},{"id":"b","text":"\"You're too small, sit out\""},{"id":"c","text":"Teaching a new kid the rules"},{"id":"d","text":"Laughing at someone who can't play yet"},{"id":"e","text":"Making a team for the leftover kids"},{"id":"f","text":"\"Only fast runners allowed\""}],"bins":[{"id":"in","label":"Includes everyone 💚","valence":"pos"},{"id":"out","label":"Shuts out 🛑","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"Including everyone in play is the fair move, every time.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1105","cat":"fair-everywhere","type":"sort","hook":"Sort: carries fairness everywhere, or leaves it behind?","items":[{"id":"a","text":"Taking turns at home and school"},{"id":"b","text":"Fair at school, hogging at home"},{"id":"c","text":"Sharing with team and family"},{"id":"d","text":"Kind on the field, mean at home"},{"id":"e","text":"Playing clean in games and tests"},{"id":"f","text":"Honest in class, cheating at ludo"}],"bins":[{"id":"carry","label":"Carries it 💚","valence":"pos"},{"id":"drop","label":"Drops it 🛑","valence":"neg"}],"key":{"a":"carry","b":"drop","c":"carry","d":"drop","e":"carry","f":"drop"},"relearn":"Fairness is a habit you carry between settings.","persona":"any","source":"fair-everywhere / habit"},
  {"id":"fp-1106","cat":"fair-everywhere","type":"sort","hook":"Sort: a fair way to settle who goes first, or an unfair one?","items":[{"id":"a","text":"A coin toss everyone agrees to"},{"id":"b","text":"\"I go first because I'm a boy\""},{"id":"c","text":"Rock-paper-scissors to decide"},{"id":"d","text":"The loudest kid just declaring it"},{"id":"e","text":"Drawing lots fairly"},{"id":"f","text":"\"Whoever shoves in wins the spot\""}],"bins":[{"id":"fair","label":"Fair way 💚","valence":"pos"},{"id":"no","label":"Unfair way 🛑","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"A toss or draw everyone agrees to is a fair way to decide.","persona":"any","source":"fair-everywhere / rules"},
  {"id":"fp-1107","cat":"fair-everywhere","type":"sort","hook":"Sort: a fair shared call, or one kid bossing it?","items":[{"id":"a","text":"The group votes on the game"},{"id":"b","text":"One kid always decides"},{"id":"c","text":"Agreeing the rules together"},{"id":"d","text":"Changing rules to win"},{"id":"e","text":"Rotating who captains"},{"id":"f","text":"Same captain every time"}],"bins":[{"id":"group","label":"Shared call 💚","valence":"pos"},{"id":"boss","label":"One kid bossing 🛑","valence":"neg"}],"key":{"a":"group","b":"boss","c":"group","d":"boss","e":"group","f":"boss"},"relearn":"A fair group agrees rules and shares who leads.","persona":"any","source":"fair-everywhere / rules"},
  {"id":"fp-1108","cat":"fair-everywhere","type":"role-play","hook":"Your friend dropped a catch and another kid is mocking him.","setup":"Stand up for fair, kind play. Say:","yourLine":[{"text":"\"Everyone drops one, leave it, let's just play.\"","best":true},{"text":"Join in laughing at him"}],"relearn":"A fair player doesn't pile on someone's mistake.","persona":"any","source":"fair-everywhere / voice"},
  {"id":"fp-1109","cat":"fair-everywhere","type":"role-play","hook":"A new kid stands at the edge, wanting to join your game.","setup":"Invite them in fairly. Say:","yourLine":[{"text":"\"Come on, you can be on our team.\"","best":true},{"text":"Pretend you didn't see them"}],"relearn":"Inviting a new kid in is fairness in action.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1110","cat":"fair-everywhere","type":"role-play","hook":"A teammate wants to fudge the score so your side wins.","setup":"Keep it honest. Say:","yourLine":[{"text":"\"Let's keep the real score, a fair game's better.\"","best":true},{"text":"\"Okay, just change it quickly.\""}],"relearn":"Keeping the true score is fair play, even if you lose.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1111","cat":"fair-everywhere","type":"role-play","hook":"At home, your brother grabs the last two laddoos for himself.","setup":"Ask for a fair share, kindly. Say:","yourLine":[{"text":"\"Let's split them so we each get one.\"","best":true},{"text":"Grab them back without a word"}],"relearn":"Asking to split is a fair, calm way to share at home.","persona":"any","source":"fair-everywhere / fair shares"},
  {"id":"fp-1112","cat":"fair-everywhere","type":"role-play","hook":"Your side just won the gully match by a mile.","setup":"Be a good winner. Say:","yourLine":[{"text":"\"Close game, you batted really well.\"","best":true},{"text":"\"You lot are useless.\""}],"relearn":"A kind winner lifts the other side instead of mocking.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1113","cat":"fair-everywhere","type":"role-play","hook":"The group says the youngest cousin is 'too little' to get a turn.","setup":"Speak up for a fair turn. Say:","yourLine":[{"text":"\"She gets a turn too, we can go easy.\"","best":true},{"text":"\"Yeah, she's too little.\""}],"relearn":"Everyone deserves a fair turn, even the youngest.","persona":"any","source":"fair-everywhere / turns"},
  {"id":"fp-1114","cat":"fair-everywhere","type":"role-play","hook":"Two friends are about to fight over who bowls next.","setup":"Offer a fair fix. Say:","yourLine":[{"text":"\"Let's take turns over by over, no fighting.\"","best":true},{"text":"\"Just sort it out yourselves.\""}],"relearn":"Suggesting turns is a fair way to settle a clash.","persona":"any","source":"fair-everywhere / turns"},
  {"id":"fp-1115","cat":"fair-everywhere","type":"role-play","hook":"A kid wants to quit the second their team falls behind.","setup":"Keep the game fair and fun. Say:","yourLine":[{"text":"\"Stay in, a game's no fun if we quit halfway.\"","best":true},{"text":"\"Fine, walk off then.\""}],"relearn":"Finishing the game fairly keeps it fun for everyone.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1116","cat":"fair-everywhere","type":"role-play","hook":"In a board game, a friend keeps sneaking peeks at the cards.","setup":"Ask them to play straight. Say:","yourLine":[{"text":"\"No peeking, it's more fun when it's fair.\"","best":true},{"text":"Start peeking yourself"}],"relearn":"Asking to play straight beats cheating back.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1117","cat":"fair-everywhere","type":"role-play","hook":"At home, your sister always ends up washing up after dinner.","setup":"Offer to share the job. Say:","yourLine":[{"text":"\"I'll wash up tonight, let's take turns.\"","best":true},{"text":"\"That's your job anyway.\""}],"relearn":"Offering to take turns shares the work fairly at home.","persona":"Ananya","source":"fair-everywhere / fair shares"},
  {"id":"fp-1118","cat":"fair-everywhere","type":"role-play","hook":"The group wants to leave one kid out of the next round for losing.","setup":"Keep play open to all. Say:","yourLine":[{"text":"\"Everyone stays in, that's the fair way.\"","best":true},{"text":"\"Yeah, losers sit out.\""}],"relearn":"Keeping everyone in the game is the fair rule.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1119","cat":"fair-everywhere","type":"reflect","hook":"Lensy: think of a game you love. What makes it fun for everyone?","prompt":"What do you think?","options":["Everyone gets a turn","No one cheats","Win or lose, we're kind"],"affirm":"That's it, fairness is what keeps a game fun for all of us.","relearn":"Fair turns, no cheating and kindness keep play fun.","persona":"any","source":"fair-everywhere / reflect"},
  {"id":"fp-1120","cat":"fair-everywhere","type":"reflect","hook":"Lensy: you can be fair at home AND at play. Same you, both places?","prompt":"What do you think?","options":["Same me everywhere","Fair in both","I carry it with me"],"affirm":"Fairness is a habit that travels with you, home, school and play.","relearn":"Fairness is a habit you carry between settings.","persona":"any","source":"fair-everywhere / habit"},
  {"id":"fp-1121","cat":"fair-everywhere","type":"reflect","hook":"Lensy: how does it feel to win a game fairly?","prompt":"What do you think?","options":["Really good","Like a real win","Better than cheating"],"affirm":"A fair win feels real, because you earned it and kept friends.","relearn":"A clean win is a real win you can feel proud of.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1122","cat":"fair-everywhere","type":"reflect","hook":"Lensy: how does it feel to be left out of a game?","prompt":"What do you think?","options":["Not nice","Lonely","Like I don't count"],"affirm":"That feeling is why including everyone in play is the fair move.","relearn":"Knowing how being left out feels helps you include others.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1123","cat":"fair-everywhere","type":"reflect","hook":"Lensy: when you lose, what's a fair way to feel about it?","prompt":"What do you think?","options":["It's just a game","Try again next time","Say well played"],"affirm":"Losing fairly and trying again is part of being a good player.","relearn":"Losing well, with a 'well played', is fair play too.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1124","cat":"fair-everywhere","type":"reflect","hook":"Lensy: where in your day could things be a bit fairer?","prompt":"Pick one.","options":["Chores at home","Turns in games","Who gets the remote","Sharing snacks"],"affirm":"Noticing where it's unfair is the first step to making it fair.","relearn":"Spotting where to be fairer is how you start changing it.","persona":"any","source":"fair-everywhere / reflect"},
  {"id":"fp-1125","cat":"fair-everywhere","type":"reflect","hook":"Lensy: who's someone you could share a turn with today?","prompt":"Think of someone.","options":["A sibling","A friend","A younger kid","Anyone waiting"],"affirm":"Sharing a turn, even a small one, is fairness you can do today.","relearn":"You can share a fair turn with someone every day.","persona":"any","source":"fair-everywhere / turns"},
  {"id":"fp-1126","cat":"fair-everywhere","type":"reflect","hook":"Lensy: what makes someone a fun person to play with?","prompt":"What do you think?","options":["They play fair","They're kind when they win","They let everyone join"],"affirm":"Fair, kind, welcoming, that's who everyone wants to play with.","relearn":"Playing fair and kind makes you great to play with.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1127","cat":"fair-everywhere","type":"reflect","hook":"Lensy: is a win by cheating really a win to be proud of?","prompt":"What do you think?","options":["No","Not really","A clean win is better"],"affirm":"A cheated win isn't a real win; a fair one is the proud kind.","relearn":"Winning by cheating isn't a real or fair win.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1128","cat":"fair-everywhere","type":"reflect","hook":"Lensy: what could you do when one kid is hogging the only swing?","prompt":"What do you think?","options":["Ask for turns","Suggest a turn-list","Remind them everyone waits"],"affirm":"Suggesting turns is a calm, fair way to share the swing.","relearn":"Turn-taking is the fair fix when someone's hogging.","persona":"any","source":"fair-everywhere / turns"},
  {"id":"fp-1129","cat":"fair-everywhere","type":"reflect","hook":"Lensy: fair shares at home, what would that look like for you?","prompt":"What do you think?","options":["Equal snacks","Chores by turns","Everyone gets a say"],"affirm":"Equal shares and turns at home make it fair for every kid.","relearn":"Fair shares at home: snacks, chores and a say, split fairly.","persona":"any","source":"fair-everywhere / fair shares"},
  {"id":"fp-1130","cat":"fair-everywhere","type":"reflect","hook":"Lensy: a new kid joins your street. How could you make it fair for them?","prompt":"What do you think?","options":["Invite them to play","Explain the rules","Give them a turn"],"affirm":"Welcoming a new kid into the game is fairness in action.","relearn":"Including a newcomer with a fair turn is the kind move.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1131","cat":"fair-everywhere","type":"reflect","hook":"Lensy: do the same fairness rules work at home, school and play?","prompt":"What do you think?","options":["Yes, the same","Turns work everywhere","Fair is fair anywhere"],"affirm":"The same fairness, turns, sharing, kindness, works everywhere.","relearn":"The same fairness works at home, school and play.","persona":"any","source":"fair-everywhere / habit"},
  {"id":"fp-1132","cat":"fair-everywhere","type":"reflect","hook":"Lensy: what's one fair-play promise you'd make to your friends?","prompt":"Pick your promise.","options":["I won't cheat","I'll share turns","I'll be a kind winner","Everyone can join"],"affirm":"Hold that promise, it's how you keep play fair and fun.","relearn":"A fair-play promise keeps games fun for the whole group.","persona":"any","source":"fair-everywhere / reflect"},
  {"id":"fp-1133","cat":"fair-everywhere","type":"reflect","hook":"Lensy: at a party, the snacks run low. What's the fair thing?","prompt":"What do you think?","options":["Share what's left","Make sure everyone gets some","Don't grab it all"],"affirm":"Sharing what's left so everyone gets some is the fair move.","relearn":"Fair shares mean everyone gets some, even when there's little.","persona":"any","source":"fair-everywhere / fair shares"},
  {"id":"fp-1134","cat":"fair-everywhere","type":"reflect","hook":"Lensy: when a game gets tense, what keeps it from turning unfair?","prompt":"What do you think?","options":["Sticking to the rules","Staying calm","Same rule for all"],"affirm":"Sticking to the agreed rules keeps a tense game fair.","relearn":"Keeping to the agreed rules keeps play fair when it's tense.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1135","cat":"fair-everywhere","type":"reflect","hook":"Lensy: what will you carry from Fair Play World into your everyday?","prompt":"Pick what you'll carry.","options":["Everyone gets a turn","No cheating","Be a kind winner","Let everyone join"],"affirm":"Carry that into home, school and play, you're a fair-play champion.","relearn":"Fairness, turns, clean play, kindness, goes everywhere with you.","persona":"any","source":"fair-everywhere / reflect"},
  {"id":"fp-1136","cat":"fair-everywhere","type":"build","hook":"Build the fair-play rules for your street games.","prompt":"Pick the rules that make play fair for all.","pieces":["everyone gets a turn","no cheating","winners stay kind","let new kids join","losers can't play again"],"mode":"assemble","key":["everyone gets a turn","no cheating","winners stay kind","let new kids join"],"relearn":"Fair street games run on turns, clean play, kindness and including all.","persona":"any","source":"fair-everywhere / build"},
  {"id":"fp-1137","cat":"fair-everywhere","type":"build","hook":"Build a fair plan for sharing the one family phone.","prompt":"Pick what makes sharing it fair.","pieces":["a turn for each person","a timer so turns are equal","homework time comes first","everyone agrees the plan","one person keeps it all day"],"mode":"assemble","key":["a turn for each person","a timer so turns are equal","homework time comes first","everyone agrees the plan"],"relearn":"A fair phone plan: equal timed turns everyone agrees to.","persona":"any","source":"fair-everywhere / build"},
  {"id":"fp-1138","cat":"fair-everywhere","type":"build","hook":"Build the steps to start a fair gully cricket game.","prompt":"Put the fair-start steps in order.","pieces":["agree the rules together","pick teams fairly","everyone gets a bat","play clean, no cheating"],"mode":"sequence","key":["agree the rules together","pick teams fairly","everyone gets a bat","play clean, no cheating"],"relearn":"A fair game starts with agreed rules, fair teams and clean play.","persona":"any","source":"fair-everywhere / build"},
  {"id":"fp-1139","cat":"fair-everywhere","type":"build","hook":"Build a 'kind winner' plan for after the match.","prompt":"Pick what a fair winner does.","pieces":["shake hands with the other team","say \"good game\"","offer a rematch","help pack up together","brag about winning"],"mode":"assemble","key":["shake hands with the other team","say \"good game\"","offer a rematch","help pack up together"],"relearn":"A kind winner shakes hands, says good game and stays humble.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1140","cat":"fair-everywhere","type":"build","hook":"Build a fair way to include the new kid in your team.","prompt":"Pick the steps that make it fair.","pieces":["welcome them in","explain the rules","give them a real turn","cheer their tries","make them just watch"],"mode":"assemble","key":["welcome them in","explain the rules","give them a real turn","cheer their tries"],"relearn":"Including a new kid means a welcome, the rules and a real turn.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1141","cat":"fair-everywhere","type":"build","hook":"Build the steps to settle a fight over whose turn it is.","prompt":"Put the fair steps in order.","pieces":["stop and talk it out","agree a way to decide","take turns from now on","keep playing fairly"],"mode":"sequence","key":["stop and talk it out","agree a way to decide","take turns from now on","keep playing fairly"],"relearn":"Settle a turn-fight by talking, agreeing a way, then taking turns.","persona":"any","source":"fair-everywhere / turns"},
  {"id":"fp-1142","cat":"fair-everywhere","type":"build","hook":"Build a fair-share snack plan for a group of friends.","prompt":"Pick what makes sharing snacks fair.","pieces":["split it about equally","make sure everyone gets some","ask about allergies","share with whoever has none","keep the most for yourself"],"mode":"assemble","key":["split it about equally","make sure everyone gets some","ask about allergies","share with whoever has none"],"relearn":"Fair snack-sharing: equal-ish, everyone included, no one left out.","persona":"any","source":"fair-everywhere / fair shares"},
  {"id":"fp-1143","cat":"fair-everywhere","type":"build","hook":"Build a 'fair everywhere' habit to carry between places.","prompt":"Pick the fair habits you'll take everywhere.","pieces":["share turns at home","play clean at games","be kind whether you win or lose","let everyone join in","only be fair when watched"],"mode":"assemble","key":["share turns at home","play clean at games","be kind whether you win or lose","let everyone join in"],"relearn":"Fairness is the same habit at home, school and play.","persona":"any","source":"fair-everywhere / habit"},
  {"id":"fp-1144","cat":"fair-everywhere","type":"match","hook":"Match each tricky moment to the fair move.","pairs":[{"left":"One swing, many kids","right":"Take fair turns"},{"left":"You won the match","right":"Say \"good game\""},{"left":"A new kid wants in","right":"Invite them to play"},{"left":"Tempted to cheat to win","right":"Play it straight"},{"left":"Last two snacks","right":"Split them equally"}],"relearn":"Every tricky moment has a fair move: turns, kindness, clean play.","persona":"any","source":"fair-everywhere / match"},
  {"id":"fp-1145","cat":"fair-everywhere","type":"match","hook":"Match the place to a fair thing you can do there.","pairs":[{"left":"At home","right":"Share the chores by turns"},{"left":"On the playground","right":"Let everyone have a go"},{"left":"In a board game","right":"Keep the real score"},{"left":"On the team bus","right":"Rotate the good seats"},{"left":"At a party","right":"Split the cake fairly"}],"relearn":"Fairness has a move for every place: home, play, bus and party.","persona":"any","source":"fair-everywhere / habit"},
  {"id":"fp-1146","cat":"fair-everywhere","type":"match","hook":"Match the unfair habit to its fair fix.","pairs":[{"left":"Hogging the ball","right":"Pass it around"},{"left":"Cheating to win","right":"Play by the rules"},{"left":"Gloating after winning","right":"Be a kind winner"},{"left":"Leaving a kid out","right":"Include everyone"},{"left":"Grabbing first every time","right":"Wait your turn"}],"relearn":"Each unfair habit has a fair fix you can choose instead.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1147","cat":"fair-everywhere","type":"match","hook":"Match the fair winner's words to the moment.","pairs":[{"left":"The whistle blows, you won","right":"\"Good game, well played\""},{"left":"They want a rematch","right":"\"Sure, let's go again\""},{"left":"A teammate dropped a catch","right":"\"No worries, next ball\""},{"left":"The other team is down","right":"\"You played hard\""},{"left":"Packing up after","right":"\"Let's tidy up together\""}],"relearn":"A kind winner has fair, warm words for every moment.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1148","cat":"fair-everywhere","type":"match","hook":"Match the sharing problem to the fair tool.","pairs":[{"left":"One phone, three siblings","right":"A turn timer"},{"left":"Who picks the game","right":"A group vote"},{"left":"Who goes first","right":"A coin toss"},{"left":"One bike for the week","right":"Alternate days"},{"left":"One bat for six kids","right":"Batting turns"}],"relearn":"Fair tools, timers, votes, tosses, turns, settle sharing fairly.","persona":"any","source":"fair-everywhere / fair shares"},
  {"id":"fp-1149","cat":"fair-everywhere","type":"match","hook":"Match the place to the unfair move you'd want to fix there.","pairs":[{"left":"At the water tap","right":"Cutting the line"},{"left":"In gully cricket","right":"Never calling yourself out"},{"left":"At the dinner table","right":"Grabbing all the dessert"},{"left":"On the swing","right":"Hogging it all evening"},{"left":"In a card game","right":"Peeking at the cards"}],"relearn":"Spotting the unfair move is the first step to a fair fix.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1150","cat":"fair-everywhere","type":"match","hook":"Match the kid's feeling to the fair thing that caused it.","pairs":[{"left":"Felt welcome in the game","right":"They were invited to join"},{"left":"Felt the win was real","right":"Everyone played clean"},{"left":"Felt the game was fun","right":"Each got a fair turn"},{"left":"Felt respected after losing","right":"The winner was kind"},{"left":"Felt the snacks were fair","right":"They were split equally"}],"relearn":"Fair moves leave everyone feeling welcome, respected and included.","persona":"any","source":"fair-everywhere / match"},
  {"id":"fp-1151","cat":"fair-everywhere","type":"match","hook":"Match the fair-play idea to a place it works.","pairs":[{"left":"Take turns","right":"At the one swing"},{"left":"No cheating","right":"In a ludo game"},{"left":"Be a kind winner","right":"After the cricket match"},{"left":"Include everyone","right":"On the playground"},{"left":"Fair shares","right":"At the dinner table"}],"relearn":"The same fair ideas fit every place you play and live.","persona":"any","source":"fair-everywhere / habit"},
  {"id":"fp-1152","cat":"fair-everywhere","type":"strike-rewrite","hook":"\"It's only cheating if you get caught.\"","myth":{"un":"Cheating's fine as long as nobody catches you.","re":"A win by cheating isn't a real win, caught or not.","why":"You know it wasn't earned, and that matters."},"relearn":"A cheated win isn't real, even if no one sees.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1153","cat":"fair-everywhere","type":"strike-rewrite","hook":"\"Winners can say whatever they like to the losers.\"","myth":{"un":"If you win, you can brag and tease all you want.","re":"A fair winner stays kind to whoever lost.","why":"Gloating spoils the game for everyone."},"relearn":"Being a kind winner is part of fair play.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1154","cat":"fair-everywhere","type":"strike-rewrite","hook":"\"Fairness is just for school, not for home.\"","myth":{"un":"You only have to be fair at school.","re":"The same fairness works at home, school and play.","why":"Fairness is a habit you carry everywhere."},"relearn":"Fairness belongs at home as much as at school.","persona":"any","source":"fair-everywhere / habit"},
  {"id":"fp-1155","cat":"fair-everywhere","type":"strike-rewrite","hook":"\"You don't have to let little kids play with you.\"","myth":{"un":"Little kids are too young to join your game.","re":"Including everyone in play is the fair move.","why":"Everyone deserves a fair turn to join in."},"relearn":"\"You can't play with us\" isn't fair; including is.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1156","cat":"fair-everywhere","type":"strike-rewrite","hook":"\"Whoever grabs the remote first gets to keep it.\"","myth":{"un":"First to grab the remote keeps it all night.","re":"Fair turns mean everyone gets to pick a show.","why":"Grabbing first isn't the same as a fair turn."},"relearn":"Fair turns share the remote, not first-grab rules.","persona":"any","source":"fair-everywhere / fair shares"},
  {"id":"fp-1157","cat":"fair-everywhere","type":"strike-rewrite","hook":"\"The biggest kid should always go first.\"","myth":{"un":"Being biggest means you get to go first.","re":"Fair turns aren't decided by who's biggest.","why":"A coin toss or a queue is fairer than size."},"relearn":"Going first should be fair, not just by size.","persona":"any","source":"fair-everywhere / turns"},
  {"id":"fp-1158","cat":"fair-everywhere","type":"strike-rewrite","hook":"\"If you lose, you have to sit out the next game.\"","myth":{"un":"Losers must sit out the next round.","re":"Keeping everyone in the game is the fair rule.","why":"Sitting losers out just shuts people out of play."},"relearn":"Everyone stays in the game; losers don't sit out.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1159","cat":"fair-everywhere","type":"strike-rewrite","hook":"\"It's fine to change the rules once you're losing.\"","myth":{"un":"You can change the rules mid-game if you're behind.","re":"Fair play means the same agreed rules for the whole game.","why":"Changing rules to win is a kind of cheating."},"relearn":"Stick to the agreed rules; don't change them to win.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1160","cat":"fair-everywhere","type":"branch","hook":"At the family lunch, kids eat only after every adult, and you're starving.","options":[{"text":"Ask politely if little kids can eat alongside","consequence":"The young ones eat sooner; elders still respected.","outcome":"fair","best":true},{"text":"Sneak food off the plates","consequence":"Sneaking causes a fuss; asking fairly works better.","outcome":"unfair"}],"debrief":"You can ask kindly for a fairer turn, even with elders.","relearn":"Asking kindly for a fair turn beats sneaking.","persona":"Sunita","source":"fair-everywhere / fair shares"},
  {"id":"fp-1161","cat":"fair-everywhere","type":"branch","hook":"On the apartment slide, your friends form a 'no entry' gate to keep other kids off.","options":[{"text":"Open it up: \"the slide's for everyone, come on\"","consequence":"More kids play and it's twice as fun.","outcome":"fair","best":true},{"text":"Help guard the gate","consequence":"Other kids feel shut out; that isn't fair.","outcome":"unfair"}],"debrief":"Shared play spaces are for everyone; gatekeeping isn't fair.","relearn":"Public play spaces are for everyone, not a chosen few.","persona":"any","source":"fair-everywhere / inclusion"},
  {"id":"fp-1162","cat":"fair-everywhere","type":"branch","hook":"Your team lost the colony match and a teammate blames the smallest player.","options":[{"text":"Say \"we win and lose as a team, no blaming\"","consequence":"The little one feels okay; the team stays together.","outcome":"fair","best":true},{"text":"Pile on the blame too","consequence":"Blaming one kid is unfair and breaks the team.","outcome":"unfair"}],"debrief":"A fair team shares the result, win or lose, without scapegoats.","relearn":"A fair team doesn't blame one player for a loss.","persona":"any","source":"fair-everywhere / kind winner"},
  {"id":"fp-1163","cat":"fair-everywhere","type":"branch","hook":"In a quiz with friends, you spot the answer sheet left open.","options":[{"text":"Close it and play from what you know","consequence":"You play fair; the quiz means something.","outcome":"fair","best":true},{"text":"Peek and use the answers","consequence":"A peeked win isn't a real win, and friends lose trust.","outcome":"unfair"}],"debrief":"Playing from what you actually know is the fair, real game.","relearn":"Using leaked answers isn't a fair or real win.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1164","cat":"fair-everywhere","type":"branch","hook":"Your sibling always picks the movie 'because they're older'.","options":[{"text":"Suggest taking turns to choose each week","consequence":"You both get to pick; movie night feels fair.","outcome":"fair","best":true},{"text":"Sulk and refuse to watch","consequence":"Sulking doesn't fix it; turn-taking does.","outcome":"unfair"}],"debrief":"Being older isn't a fair reason to always choose; turns are.","relearn":"Fair turns to choose beat 'older always picks'.","persona":"any","source":"fair-everywhere / fair shares"},
  {"id":"fp-1165","cat":"fair-everywhere","type":"branch","hook":"Mid-game, a kid keeps moving the boundary line to suit himself.","options":[{"text":"Say \"let's mark the line once and keep it for all\"","consequence":"One fixed line; the game's fair again.","outcome":"fair","best":true},{"text":"Move the line your way too","consequence":"A shifting line means no one's playing fair.","outcome":"unfair"}],"debrief":"One agreed boundary for everyone keeps the game fair.","relearn":"A fixed, agreed line is fairer than one that shifts to win.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1166","cat":"fair-everywhere","type":"branch","hook":"At the festival fair, kids crowd the one ride and the queue collapses.","options":[{"text":"Help start a line so everyone rides by turns","consequence":"The queue works; every kid gets a fair ride.","outcome":"fair","best":true},{"text":"Push in with the crowd","consequence":"The pushy kids ride; the patient ones miss out.","outcome":"unfair"}],"debrief":"A fair queue gives everyone a turn on the one ride.","relearn":"A line by turns is fairer than a pushing crowd.","persona":"any","source":"fair-everywhere / turns"},
  {"id":"fp-1167","cat":"fair-everywhere","type":"branch","hook":"Your friends want to gang up so one kid never wins at anything.","options":[{"text":"Say \"let's all just play our best, fairly\"","consequence":"Everyone has a real chance; games stay fun.","outcome":"fair","best":true},{"text":"Join the gang-up","consequence":"Rigging it against one kid isn't fair play.","outcome":"unfair"}],"debrief":"Ganging up to fix who loses isn't a fair game.","relearn":"Everyone should get a fair chance to win, not be rigged out.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1168","cat":"fair-everywhere","type":"branch","hook":"At home, only your sister is asked to share her things, never your brother.","options":[{"text":"Say \"sharing should go both ways for all of us\"","consequence":"Everyone shares by turns; it feels fair.","outcome":"fair","best":true},{"text":"Stay quiet because it suits you","consequence":"One kid always sharing isn't fair to her.","outcome":"unfair"}],"debrief":"Fair sharing at home goes both ways, not just for one kid.","relearn":"Sharing rules should be the same for every sibling.","persona":"Ananya","source":"fair-everywhere / fair shares"},
  {"id":"fp-1169","cat":"fair-everywhere","type":"branch","hook":"You're refereeing a friends' match and your best friend is playing.","options":[{"text":"Call it straight, even against your friend","consequence":"Both teams trust your calls; the match is fair.","outcome":"fair","best":true},{"text":"Make calls that favour your friend","consequence":"A biased ref makes the whole game unfair.","outcome":"unfair"}],"debrief":"A fair referee calls it the same for both sides.","relearn":"Refereeing fairly means no favourites, even friends.","persona":"any","source":"fair-everywhere / no cheating"},
  {"id":"fp-1170","cat":"fair-opportunity","type":"branch","hook":"Sir wants one student for the inter-school quiz and looks only at the boys.","options":[{"text":"Say \"can girls raise hands too, sir?\"","consequence":"Hands go up all round; sir picks who knows most.","outcome":"fair","best":true},{"text":"Stay quiet, it's sir's call","consequence":"Keen girls never get asked at all."}],"debrief":"A chance to represent the school should open to all, not one gender.","relearn":"Opening a chance to all is the fair move.","persona":"Ananya","source":"gender equality / opportunity"},
  {"id":"fp-1171","cat":"fair-opportunity","type":"branch","hook":"One spot at the art camp. Your cousin says \"give it to your brother.\"","options":[{"text":"Say \"let's pick whoever's keenest\"","consequence":"The spot goes to whoever will use it, girl or boy.","outcome":"fair","best":true},{"text":"Hand it to your brother","consequence":"A keener sibling misses out for no fair reason."}],"debrief":"Family chances shouldn't default to the boy; share them fairly.","relearn":"Pick by who's keenest, not by gender.","persona":"Ananya","source":"India / family opportunity"},
  {"id":"fp-1172","cat":"fair-opportunity","type":"branch","hook":"The football is out at lunch, and the boys say girls can just watch.","options":[{"text":"Say \"let's make mixed teams, everyone plays\"","consequence":"Mixed teams form and the game's more fun for all.","outcome":"fair","best":true},{"text":"Sit on the side and watch","consequence":"Half the class never gets a kick of the ball."}],"debrief":"Everyone deserves a fair turn to play, whatever their gender.","relearn":"Mixing teams gives everyone a fair go on the pitch.","persona":"any","source":"play / opportunity"},
  {"id":"fp-1173","cat":"fair-opportunity","type":"branch","hook":"Two kids want the last seat in the coding club. One's louder, one's quieter.","options":[{"text":"Suggest the teacher draw names so it's fair","consequence":"Both get an equal shot; the quiet kid isn't shut out.","outcome":"fair","best":true},{"text":"Let the louder one grab it","consequence":"Quieter kids keep losing chances to bolder ones."}],"debrief":"A fair draw gives shy kids the same chance as bold ones.","relearn":"Fair picking doesn't always reward the loudest.","persona":"any","source":"inclusion / opportunity"},
  {"id":"fp-1174","cat":"fair-opportunity","type":"branch","hook":"Your sister wants to learn to ride the cycle, but it's \"kept for your brother.\"","options":[{"text":"Say \"let's take turns, she'd love to learn too\"","consequence":"She learns to ride; the cycle's shared by turns.","outcome":"fair","best":true},{"text":"Leave the cycle as the boy's","consequence":"She never learns a skill she really wanted."}],"debrief":"A chance to learn a skill should be shared, not gendered.","relearn":"Skills and gear are for everyone to try by turns.","persona":"Ananya","source":"India / family opportunity"},
  {"id":"fp-1175","cat":"fair-opportunity","type":"branch","hook":"The teacher needs a class monitor and asks \"which boy wants it?\"","options":[{"text":"Say \"any of us could try, sir\"","consequence":"The role opens up; a great monitor is picked on merit.","outcome":"fair","best":true},{"text":"Let only the boys volunteer","consequence":"Half the class is skipped before they try."}],"debrief":"Roles like monitor should open to anyone keen for a fair turn.","relearn":"Don't assume a role is for one gender.","persona":"Ananya","source":"leadership / equality"},
  {"id":"fp-1176","cat":"fair-opportunity","type":"branch","hook":"A new drum is donated to the music room. The seniors say it's \"a boy's instrument.\"","options":[{"text":"Say \"anyone who wants to drum should get a turn\"","consequence":"A sign-up list goes round; everyone who's keen has a go.","outcome":"fair","best":true},{"text":"Agree it's for the boys","consequence":"Girls who'd love to drum never touch it."}],"debrief":"No instrument belongs to one gender; the chance is for all.","relearn":"A fair turn list beats \"that's for boys.\"","persona":"Reyansh","source":"opportunity / gender norms"},
  {"id":"fp-1177","cat":"fair-opportunity","type":"branch","hook":"Your team needs someone to give the speech. Everyone looks at the boys.","options":[{"text":"Say \"let's hear who'd like to, then pick the best\"","consequence":"A girl volunteers and gives a brilliant speech.","outcome":"fair","best":true},{"text":"Just let a boy do it again","consequence":"Confident speakers stay hidden behind an old habit."}],"debrief":"A chance to speak up front belongs to anyone, fairly chosen.","relearn":"Pick the speaker on willingness and skill, not gender.","persona":"Ananya","source":"leadership / equality"},
  {"id":"fp-1178","cat":"fair-opportunity","type":"branch","hook":"At the mela stall, only your brother is handed money to spend.","options":[{"text":"Say \"could we split it so we each get a turn?\"","consequence":"You both get a fair share to choose a treat.","outcome":"fair","best":true},{"text":"Watch him spend it all","consequence":"You miss out on a chance just because of who you are."}],"debrief":"Fun and pocket money should be shared fairly between siblings.","relearn":"A fair share at home means everyone gets a turn.","persona":"Ananya","source":"India / family opportunity"},
  {"id":"fp-1179","cat":"fair-opportunity","type":"branch","hook":"The science kit arrives. The teacher says \"boys, come build the circuit.\"","options":[{"text":"Say \"can we all take turns building it, sir?\"","consequence":"Everyone gets hands-on time; the best circuit wins.","outcome":"fair","best":true},{"text":"Let only the boys build it","consequence":"Girls miss a chance to try, for no good reason."}],"debrief":"Fair opportunity means everyone gets a chance to try the kit.","relearn":"Hands-on chances are for all, not boys first.","persona":"Ananya","source":"gender equality / opportunity"},
  {"id":"fp-1180","cat":"fair-opportunity","type":"branch","hook":"Captain's been a boy three years running \"because tradition.\"","options":[{"text":"Say \"let's vote, any of us can lead\"","consequence":"A vote picks a strong leader on merit.","outcome":"fair","best":true},{"text":"Keep the tradition going","consequence":"Good leaders are passed over by an old rule."}],"debrief":"Leadership should rotate fairly, not stick to one gender.","relearn":"A fair vote beats \"it's always been a boy.\"","persona":"Ananya","source":"leadership / equality"},
  {"id":"fp-1181","cat":"fair-opportunity","type":"branch","hook":"Only boys are sent to the cricket trial; girls are told to keep score.","options":[{"text":"Say \"can girls trial too, for a fair go?\"","consequence":"Girls trial as well; the team gets stronger.","outcome":"fair","best":true},{"text":"Accept scoring duty","consequence":"Talented players never get to show their game."}],"debrief":"Trials should be open to all; watching isn't a fair chance.","relearn":"A fair trial is open to everyone keen to play.","persona":"Ananya","source":"sport / opportunity"},
  {"id":"fp-1182","cat":"fair-opportunity","type":"branch","hook":"A boy loves dance but is told \"that's not for boys, sit out.\"","options":[{"text":"Say \"he should dance, let's all join in\"","consequence":"He joins the dance; the group has more fun.","outcome":"fair","best":true},{"text":"Let them shut him out","consequence":"He drops something he loves for a silly rule."}],"debrief":"Fair chances free boys too; no activity is gendered.","relearn":"Boys deserve a fair chance at what they love.","persona":"Faizan-type","source":"both directions / opportunity"},
  {"id":"fp-1183","cat":"fair-opportunity","type":"branch","hook":"The class trip has spare seats. Sir starts handing them to boys.","options":[{"text":"Say \"could spare seats be drawn fairly?\"","consequence":"Names are drawn; seats go to a fair mix.","outcome":"fair","best":true},{"text":"Say nothing, it's decided","consequence":"Some kids miss the trip for no fair reason."}],"debrief":"Spare chances should be shared fairly, not given to one group.","relearn":"A fair draw shares extra chances around.","persona":"any","source":"opportunity"},
  {"id":"fp-1184","cat":"fair-opportunity","type":"branch","hook":"Only the elder son is to be sent to the better school far away.","options":[{"text":"Ask \"could we weigh who'd gain most?\"","consequence":"The grown-ups think again, more fairly.","outcome":"fair","best":true},{"text":"Treat it as settled","consequence":"A keen learner misses out just for being a girl."}],"debrief":"Schooling chances should be weighed fairly, not by gender.","relearn":"Education chances go to whoever will use them.","persona":"Ananya","source":"India / family opportunity"},
  {"id":"fp-1185","cat":"fair-opportunity","type":"branch","hook":"In the school garden club, only boys are let near the tools.","options":[{"text":"Say \"let's rotate the tools so everyone learns\"","consequence":"Everyone gets a turn digging; the garden thrives.","outcome":"fair","best":true},{"text":"Let the boys keep the tools","consequence":"Half the club just watches and never learns the skill."}],"debrief":"A chance to learn by doing should rotate, not be held by one group.","relearn":"Sharing the tools by turns is the fair chance.","persona":"any","source":"opportunity / inclusion"},
  {"id":"fp-1186","cat":"fair-opportunity","type":"branch","hook":"A shy new girl never gets picked for anything. Today there's a relay.","options":[{"text":"Say \"let's give her a leg of the relay, it's her turn\"","consequence":"She runs, grins, and feels part of the team at last.","outcome":"fair","best":true},{"text":"Pick the usual fast kids again","consequence":"She stays on the bench, week after week."}],"debrief":"Fair opportunity reaches the quiet and the new kids too.","relearn":"Give a fair turn to those who never get picked.","persona":"any","source":"inclusion / opportunity"},
  {"id":"fp-1187","cat":"fair-opportunity","type":"branch","hook":"The rangoli contest is one entry per class. Sir picks his favourite.","options":[{"text":"Say \"could anyone keen enter, sir?\"","consequence":"Several enter; the best design wins fairly.","outcome":"fair","best":true},{"text":"Let the favourite go through","consequence":"Other keen kids get no fair shot."}],"debrief":"Picking only a favourite isn't fair; open it to all who're keen.","relearn":"Favouritism isn't fair; a chance is open to all.","persona":"any","source":"opportunity"},
  {"id":"fp-1188","cat":"fair-opportunity","type":"branch","hook":"Your friend wants chess but is told \"girls don't play chess.\"","options":[{"text":"Say \"anyone can play, sit with me\"","consequence":"She plays, wins, and the silly rule fades.","outcome":"fair","best":true},{"text":"Believe the rule and leave it","consequence":"A keen player is shut out of a game she'd love."}],"debrief":"No game is for one gender; a fair chance is open to all.","relearn":"\"Girls don't play that\" isn't a fair reason.","persona":"Reyansh","source":"gender norms / opportunity"},
  {"id":"fp-1189","cat":"fair-opportunity","type":"branch","hook":"After dinner the boys go play while the girls are kept back \"to help.\"","options":[{"text":"Say \"if we all help quick, we can all play after\"","consequence":"Work's done fast and shared; then everyone plays.","outcome":"fair","best":true},{"text":"Let the girls miss play again","consequence":"The same kids lose their playtime, night after night."}],"debrief":"Rest and play should be shared fairly, not kept from the girls.","relearn":"Everyone earns a fair turn to rest and play.","persona":"Sunita","source":"India / family opportunity"},
  {"id":"fp-1190","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Let the boys go first for the captain tryout.\"","myth":{"un":"Boys should be picked ahead of girls when a spot opens up.","re":"A fair pick goes by who's keen and ready, in the order everyone signed up.","why":"Being first in line isn't something you earn by being a boy."},"relearn":"A turn is decided by fairness, not by putting boys ahead.","persona":"Ananya","source":"gender equality"},
  {"id":"fp-1191","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Why sign her up for coding club? She'll just stop later.\"","myth":{"un":"It's not worth giving girls a place if they might drop it one day.","re":"Every child earns their place by wanting to be there, today.","why":"You can't fence a kid out of a chance over a guess about her future."},"relearn":"A girl's spot is hers because she showed up for it.","persona":"Ananya","source":"gender equality / India"},
  {"id":"fp-1192","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Leading is a boy's job.\"","myth":{"un":"Only boys should get to be the leader.","re":"Anyone can lead; the chance to lead should rotate fairly.","why":"Good leaders are found in every kind of kid."},"relearn":"Leadership is open to all and shared by turns.","persona":"Ananya","source":"leadership / equality"},
  {"id":"fp-1193","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Girls only need to learn to keep house.\"","myth":{"un":"Girls only need home skills, not the same learning.","re":"Girls deserve the same chance to study and chase any dream.","why":"Every child's mind grows when it's given a fair chance to learn."},"relearn":"Girls get the same chance to learn anything, not just home skills.","persona":"Ananya","source":"India / gender equality"},
  {"id":"fp-1194","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Some sports just aren't for girls.\"","myth":{"un":"Girls shouldn't get a turn at the rough sports.","re":"Any sport is open to anyone keen to play and train.","why":"Skill and effort grow with a fair chance, not from gender."},"relearn":"Every sport is open to anyone who wants a fair go.","persona":"Reyansh","source":"sport / opportunity"},
  {"id":"fp-1195","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Boys can't join the dance or singing group.\"","myth":{"un":"Singing and dancing aren't a fair chance for boys.","re":"Boys deserve a fair turn at dance and music too, if they want it.","why":"What you love to do isn't decided by your gender."},"relearn":"Boys get a fair chance at dance and music, the same as anyone.","persona":"Faizan-type","source":"both directions / opportunity"},
  {"id":"fp-1196","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"The quiet kids don't really want a turn anyway.\"","myth":{"un":"Shy kids don't need a fair chance to try.","re":"Quiet kids want a turn too; a fair chance reaches them as well.","why":"Being shy isn't the same as not wanting to take part."},"relearn":"A fair chance includes the quiet kids, not just the loud ones.","persona":"any","source":"inclusion / opportunity"},
  {"id":"fp-1197","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Only the eldest gets sent to study far away.\"","myth":{"un":"The best schooling chance always goes to the eldest boy.","re":"A schooling chance should go to whoever will use it, fairly weighed.","why":"A keen learner can be any child in the family."},"relearn":"Education chances are weighed fairly, not fixed by birth order or gender.","persona":"Ananya","source":"India / family opportunity"},
  {"id":"fp-1198","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"If you didn't get picked, you just weren't good enough.\"","myth":{"un":"Kids who never get a turn just don't deserve one.","re":"You can't show what you can do if you never get a fair chance to try.","why":"A turn comes first; talent shows once the chance is given."},"relearn":"Everyone deserves a fair chance to try before being judged.","persona":"any","source":"opportunity"},
  {"id":"fp-1199","cat":"fair-opportunity","type":"strike-rewrite","hook":"\"Fair chances are only the school's worry, not at home.\"","myth":{"un":"Fair chances matter at school but not at home.","re":"Chances to learn, rest and play should be shared fairly at home too.","why":"Fairness is the same habit wherever you are."},"relearn":"Fair opportunity counts at home as much as at school.","persona":"Ananya","source":"fair-everywhere / family opportunity"},
  {"id":"fp-1200","cat":"fair-opportunity","type":"sort","hook":"Sort: a fair chance, or shutting someone out?","items":[{"id":"a","text":"Anyone keen can join the club"},{"id":"b","text":"\"This room is boys only\""},{"id":"c","text":"Turns drawn from a hat"},{"id":"d","text":"\"Girls just keep the score\""},{"id":"e","text":"Everyone gets one try at the kit"},{"id":"f","text":"Only the teacher's favourite is picked"}],"bins":[{"id":"fair","label":"Fair chance","valence":"pos"},{"id":"no","label":"Shuts out","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"A fair chance is open to all; shutting people out is not fair.","persona":"any","source":"opportunity"},
  {"id":"fp-1201","cat":"fair-opportunity","type":"sort","hook":"Sort: this opens a chance, or blocks it?","items":[{"id":"a","text":"A sign-up sheet anyone can write on"},{"id":"b","text":"\"You're a girl, so just watch\""},{"id":"c","text":"Rotating who's team captain"},{"id":"d","text":"Picking the same kid every single time"},{"id":"e","text":"A fair vote for the lead role"},{"id":"f","text":"\"Boys go first, always\""}],"bins":[{"id":"open","label":"Opens a chance","valence":"pos"},{"id":"block","label":"Blocks it","valence":"neg"}],"key":{"a":"open","b":"block","c":"open","d":"block","e":"open","f":"block"},"relearn":"Sign-ups, votes and turns open chances; \"always the same\" blocks them.","persona":"any","source":"opportunity"},
  {"id":"fp-1202","cat":"fair-opportunity","type":"sort","hook":"Sort: a fair way to give a chance, or an unfair one?","items":[{"id":"a","text":"Anyone keen may lead the demo"},{"id":"b","text":"\"Only boys captain the team\""},{"id":"c","text":"Open the tabla to whoever wants it"},{"id":"d","text":"\"Girls can't stand for class rep\""},{"id":"e","text":"Everyone may try out for the play"},{"id":"f","text":"\"The notice is read by boys only\""}],"bins":[{"id":"fair","label":"Fair chance","valence":"pos"},{"id":"no","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"A chance open to anyone keen is fair; \"boys only\" or \"not girls\" is not.","persona":"any","source":"opportunity"},
  {"id":"fp-1203","cat":"fair-opportunity","type":"sort","hook":"Sort: a fair way to pick, or an unfair one?","items":[{"id":"a","text":"Draw names so everyone might get it"},{"id":"b","text":"\"Only my friends get a turn\""},{"id":"c","text":"Pick whoever's keenest, any gender"},{"id":"d","text":"\"Boys before girls, every time\""},{"id":"e","text":"Take it in strict turns"},{"id":"f","text":"The loudest kid always grabs it"}],"bins":[{"id":"fair","label":"Fair pick","valence":"pos"},{"id":"no","label":"Unfair pick","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Draws, turns and keenness are fair; favourites and \"boys first\" aren't.","persona":"any","source":"opportunity"},
  {"id":"fp-1204","cat":"fair-opportunity","type":"sort","hook":"Sort: this shares a chance at home, or hoards it?","items":[{"id":"a","text":"Siblings take turns on the one cycle"},{"id":"b","text":"\"The bat is only your brother's\""},{"id":"c","text":"Pocket money split evenly"},{"id":"d","text":"Only the boy is sent for tuition"},{"id":"e","text":"Each kid gets a study hour"},{"id":"f","text":"One child keeps the tablet all day"}],"bins":[{"id":"share","label":"Shares fairly","valence":"pos"},{"id":"hoard","label":"Hoards it","valence":"neg"}],"key":{"a":"share","b":"hoard","c":"share","d":"hoard","e":"share","f":"hoard"},"relearn":"Home chances are shared by turns, not hoarded by one child.","persona":"Sunita","source":"India / family opportunity"},
  {"id":"fp-1205","cat":"fair-opportunity","type":"sort","hook":"Sort: a fair reason to pick, or an unfair one?","items":[{"id":"a","text":"They worked hard to learn it"},{"id":"b","text":"\"Because he's a boy\""},{"id":"c","text":"It's honestly their turn"},{"id":"d","text":"\"Girls aren't good at that\""},{"id":"e","text":"They really want to try"},{"id":"f","text":"\"That's just how it's always been\""}],"bins":[{"id":"fair","label":"Fair reason","valence":"pos"},{"id":"no","label":"Unfair reason","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Effort, turns and keenness are fair reasons; gender and \"always\" aren't.","persona":"Ananya","source":"opportunity"},
  {"id":"fp-1206","cat":"fair-opportunity","type":"role-play","hook":"Sir is asking only the boys who wants to lead the assembly.","setup":"Speak up for a fair chance. Say:","yourLine":[{"text":"\"Sir, can anyone who'd like to lead put their hand up?\"","best":true},{"text":"Lower your hand and let it pass"}],"relearn":"Asking to open a chance to everyone is a calm, fair move.","persona":"Reyansh","source":"voice / opportunity"},
  {"id":"fp-1207","cat":"fair-opportunity","type":"role-play","hook":"Your friend's been told girls can't try the new cricket bat.","setup":"Back her up with a fair-ask. Say:","yourLine":[{"text":"\"Anyone can have a go, let's give her a fair turn.\"","best":true},{"text":"\"Maybe just watch this time.\""}],"relearn":"A calm \"let's give a fair turn\" can open a chance for a friend.","persona":"Ananya","source":"voice / opportunity"},
  {"id":"fp-1208","cat":"fair-opportunity","type":"role-play","hook":"Your sister wants to join your cricket game but feels she'll be turned away.","setup":"Invite her in fairly. Say:","yourLine":[{"text":"\"Come bat with us, it's everyone's turn.\"","best":true},{"text":"\"It's just us boys today.\""}],"relearn":"Inviting someone in is opening a fair chance to play.","persona":"any","source":"voice / inclusion"},
  {"id":"fp-1209","cat":"fair-opportunity","type":"role-play","hook":"At home the tuition spot is being given to your brother by default.","setup":"Ask for a fair say. Say:","yourLine":[{"text":"\"Can we decide the tuition by who'd use it most?\"","best":true},{"text":"Say nothing and accept it"}],"relearn":"Asking to decide a chance fairly is reasonable and brave.","persona":"Ananya","source":"voice / family opportunity"},
  {"id":"fp-1210","cat":"fair-opportunity","type":"role-play","hook":"A boy in your group is laughed at for wanting to join the dance act.","setup":"Stand up for his fair chance. Say:","yourLine":[{"text":"\"He should dance if he wants, come join us.\"","best":true},{"text":"Laugh along with the others"}],"relearn":"Backing a boy's fair chance to dance is a kind, fair move.","persona":"Faizan-type","source":"voice / both directions"},
  {"id":"fp-1211","cat":"fair-opportunity","type":"role-play","hook":"The quiz captain is always the same boy. You think it should rotate.","setup":"Suggest a fair turn. Say:","yourLine":[{"text":"\"Could we take turns as captain so it's fair?\"","best":true},{"text":"Just let him captain again"}],"relearn":"Asking for the lead to rotate is a fair, assertive move.","persona":"Ananya","source":"voice / leadership"},
  {"id":"fp-1212","cat":"fair-opportunity","type":"role-play","hook":"A quiet new girl wants to try the keyboard but never asks.","setup":"Open the chance for her. Say:","yourLine":[{"text":"\"Want a turn on the keyboard? It's yours next.\"","best":true},{"text":"Keep playing it yourself"}],"relearn":"Offering a turn reaches the kids who never ask.","persona":"any","source":"voice / inclusion"},
  {"id":"fp-1213","cat":"fair-opportunity","type":"reflect","hook":"Lensy: a fair chance to try, who do you think deserves one?","prompt":"What do you think?","options":["Everyone","Any keen kid","Girls and boys, the same"],"affirm":"A fair chance to try is something every single kid deserves.","relearn":"Everyone deserves a fair chance to try.","persona":"any","source":"opportunity"},
  {"id":"fp-1214","cat":"fair-opportunity","type":"reflect","hook":"Lensy: when chances at home are shared, who gets to dream big?","prompt":"What do you think?","options":["Everyone","All the kids","Girls too, not just boys"],"affirm":"When chances are shared, every child gets room to dream and grow.","relearn":"Sharing chances at home lets every child dream big.","persona":"Ananya","source":"family opportunity"},
  {"id":"fp-1215","cat":"fair-opportunity","type":"reflect","hook":"Lensy: imagine you could hand someone a fair chance today. Who?","prompt":"Think of one person.","options":["A left-out friend","A quiet classmate","My sibling","Anyone shut out"],"affirm":"Holding the door open for someone's chance is a real fairness move.","relearn":"You can choose to open a fair chance for someone.","persona":"any","source":"agency / opportunity"},
  {"id":"fp-1216","cat":"fair-opportunity","type":"reflect","hook":"Lensy: should the chance to lead stay with one kid, or move around?","prompt":"What do you think?","options":["Move around","Take turns","Anyone can lead"],"affirm":"Leadership feels fairest when it rotates and anyone can have a turn.","relearn":"Fair leadership rotates; it doesn't stick to one kid.","persona":"Ananya","source":"leadership"},
  {"id":"fp-1217","cat":"fair-opportunity","type":"reflect","hook":"Lensy: is there something you'd love a fair turn at?","prompt":"Picture it.","options":["A sport","An instrument","Leading something","Trying the kit"],"affirm":"You deserve a fair turn at that, and so does every other kid.","relearn":"It's okay to want, and ask for, a fair chance to try.","persona":"any","source":"agency / opportunity"},
  {"id":"fp-1218","cat":"fair-opportunity","type":"reflect","hook":"Lensy: when everyone gets a fair go, what happens to the whole group?","prompt":"What do you think?","options":["It gets stronger","Everyone shines","We all win"],"affirm":"When chances are fair, the group gets everybody's best.","relearn":"Fair chances make the whole group better.","persona":"any","source":"equality"},
  {"id":"fp-1219","cat":"fair-opportunity","type":"reflect","hook":"Lensy: a fair chance helps girls AND boys. Where might a boy need one?","prompt":"What do you think?","options":["Dance or art","Helping at home","Anything he loves"],"affirm":"Fair chances free boys too, toward whatever they love.","relearn":"Fair opportunity is a both-directions win, for girls and boys.","persona":"Faizan-type","source":"both directions"},
  {"id":"fp-1220","cat":"fair-opportunity","type":"match","hook":"Match the unfair habit to its fair fix.","pairs":[{"left":"Captain's always a boy","right":"Take turns to lead"},{"left":"Only favourites picked","right":"Draw names fairly"},{"left":"Girls told to just watch","right":"Make mixed teams"},{"left":"Loudest kid grabs it","right":"A turn list for all"},{"left":"Tuition only for the son","right":"Pick by who's keenest"}],"relearn":"Every unfair habit has a fair fix: turns, draws, mixing, sharing.","persona":"any","source":"opportunity"},
  {"id":"fp-1221","cat":"fair-opportunity","type":"match","hook":"Match the kid to the fair chance they're asking for.","pairs":[{"left":"Wants to try the science kit","right":"A turn to build the circuit"},{"left":"Loves to drum","right":"A go on the new drum"},{"left":"Dreams of captaining","right":"A fair vote for the role"},{"left":"Keen to learn the cycle","right":"Shared turns to ride"},{"left":"Wants to enter the contest","right":"An open sign-up"}],"relearn":"A fair chance gives each kid the turn they're keen on.","persona":"any","source":"opportunity"},
  {"id":"fp-1222","cat":"fair-opportunity","type":"match","hook":"Match where the chance is to the fair way to share it.","pairs":[{"left":"One science kit, whole class","right":"Everyone takes a turn"},{"left":"One trip seat spare","right":"Names drawn fairly"},{"left":"One cycle, two siblings","right":"Ride it by turns"},{"left":"One lead role","right":"Picked on merit"},{"left":"One tuition slot","right":"Goes to whoever's keenest"}],"relearn":"When there's one chance, a fair way splits it so no one's shut out.","persona":"Sunita","source":"opportunity / family"},
  {"id":"fp-1223","cat":"fair-opportunity","type":"match","hook":"Match the fair reason to pick someone to the chance.","pairs":[{"left":"Worked hardest in practice","right":"Earns a starting spot"},{"left":"It's honestly their turn","right":"Leads the assembly today"},{"left":"Really wants to try","right":"Gets a go at the kit"},{"left":"Knows the answer","right":"Speaks for the quiz team"},{"left":"Hasn't had a turn yet","right":"Picked for the relay"}],"relearn":"Fair picks rest on effort, turns, keenness and knowing, not gender.","persona":"any","source":"opportunity"},
  {"id":"fp-1224","cat":"fair-opportunity","type":"build","hook":"Build a fair way to pick who leads the school cleanliness drive.","prompt":"Pick what makes the choice fair.","pieces":["open it to anyone keen","let girls and boys stand","take a fair class vote","rotate it next term","keep it for the boys"],"mode":"assemble","key":["open it to anyone keen","let girls and boys stand","take a fair class vote","rotate it next term"],"relearn":"A fair pick is open to all, voted on, and rotated by turns.","persona":"Ananya","source":"leadership / opportunity"},
  {"id":"fp-1225","cat":"fair-opportunity","type":"build","hook":"Build a fair plan for sharing the one new science kit.","prompt":"Pick what makes it fair.","pieces":["a turn list for everyone","girls and boys both build","swap roles each lesson","help whoever's stuck","let only boys touch it"],"mode":"assemble","key":["a turn list for everyone","girls and boys both build","swap roles each lesson","help whoever's stuck"],"relearn":"A fair kit plan gives everyone a turn and swaps the roles around.","persona":"any","source":"opportunity"},
  {"id":"fp-1226","cat":"fair-opportunity","type":"build","hook":"Build a fair-chances plan for your home.","prompt":"Pick what shares chances fairly.","pieces":["take turns on the cycle","study time for every kid","split pocket money evenly","play and rest for all","spend it all on one child"],"mode":"assemble","key":["take turns on the cycle","study time for every kid","split pocket money evenly","play and rest for all"],"relearn":"A fair home shares turns, study, money, play and rest among all the kids.","persona":"Sunita","source":"India / family opportunity"},
  {"id":"fp-1227","cat":"fair-opportunity","type":"build","hook":"Build the steps to open a fair chance for a left-out friend.","prompt":"Put the fair steps in order.","pieces":["notice they never get picked","offer them a turn","cheer them while they try","keep including them next time"],"mode":"sequence","key":["notice they never get picked","offer them a turn","cheer them while they try","keep including them next time"],"relearn":"Open a fair chance: notice, offer a turn, cheer, then keep including.","persona":"any","source":"inclusion / opportunity"},
  {"id":"fp-1228","cat":"fair-opportunity","type":"build","hook":"Build the steps to ask sir to open a chance to everyone.","prompt":"Order the steps for a fair-ask.","pieces":["wait for a calm moment","ask if anyone keen can try","suggest drawing names","thank sir for a fair go"],"mode":"sequence","key":["wait for a calm moment","ask if anyone keen can try","suggest drawing names","thank sir for a fair go"],"relearn":"A fair-ask: pick the moment, ask to open it, suggest a fair way, say thanks.","persona":"Reyansh","source":"voice / opportunity"},
  {"id":"fp-1229","cat":"fair-opportunity","type":"build","hook":"Build a fair team try-out, open to everyone.","prompt":"Pick what makes the try-out fair.","pieces":["everyone may try out","judge on skill, any gender","give each a real turn","pick the strongest squad","let only boys trial"],"mode":"assemble","key":["everyone may try out","judge on skill, any gender","give each a real turn","pick the strongest squad"],"relearn":"A fair try-out is open to all and judged on skill, not gender.","persona":"any","source":"sport / opportunity"},
  {"id":"fp-1230","cat":"fair-opportunity","type":"build","hook":"Build the order to rotate the class captain fairly.","prompt":"Put the fair steps in order.","pieces":["agree captaincy will rotate","list everyone who's keen","take turns, week by week","cheer each new captain"],"mode":"sequence","key":["agree captaincy will rotate","list everyone who's keen","take turns, week by week","cheer each new captain"],"relearn":"Rotate the lead fairly: agree to rotate, list the keen, take turns, cheer.","persona":"Ananya","source":"leadership / opportunity"},
  {"id":"fp-1231","cat":"fair-opportunity","type":"build","hook":"Build a fair sign-up for the inter-school contest.","prompt":"Pick what keeps the sign-up fair.","pieces":["anyone keen can sign up","girls and boys both welcome","pick the best entry","draw if too many want it","only the favourite enters"],"mode":"assemble","key":["anyone keen can sign up","girls and boys both welcome","pick the best entry","draw if too many want it"],"relearn":"A fair sign-up is open to all, judged on merit, with a fair draw if needed.","persona":"any","source":"opportunity"},
  {"id":"fp-1232","cat":"fair-opportunity","type":"branch","hook":"Your little brother wants to join the skipping game but the girls say it's theirs.","options":[{"text":"Say \"he can skip too, let's count him in\"","consequence":"He joins in laughing; skipping's for everyone.","outcome":"fair","best":true},{"text":"Tell him to find a 'boys' game","consequence":"He's shut out of fun for no fair reason."}],"debrief":"Fair chances free boys too; no game belongs to one gender.","relearn":"Skipping, or any game, is open to anyone keen.","persona":"Faizan-type","source":"both directions / opportunity"},
  {"id":"fp-1233","cat":"fair-opportunity","type":"sort","hook":"Sort: this gives a fair chance, or holds it back?","items":[{"id":"a","text":"\"You can audition if you like\""},{"id":"b","text":"\"Dancing's not for boys\""},{"id":"c","text":"\"Your turn to bowl now\""},{"id":"d","text":"\"Girls just hand out the books\""},{"id":"e","text":"\"Whoever's keen can present\""},{"id":"f","text":"\"Leave the lab to the boys\""}],"bins":[{"id":"give","label":"Gives a chance","valence":"pos"},{"id":"hold","label":"Holds it back","valence":"neg"}],"key":{"a":"give","b":"hold","c":"give","d":"hold","e":"give","f":"hold"},"relearn":"Words that open a turn give a chance; \"not for you\" holds it back.","persona":"any","source":"opportunity"},
  {"id":"fp-1234","cat":"fair-opportunity","type":"reflect","hook":"Lensy: who in your class never seems to get a turn?","prompt":"Picture them.","options":["A shy kid","A new kid","Someone often left out","Not sure yet"],"affirm":"Noticing who's missed out is the first step to opening a fair chance.","relearn":"Spotting who's left out helps you share chances fairly.","persona":"any","source":"opportunity / agency"},
  {"id":"fp-1235","cat":"fair-opportunity","type":"reflect","hook":"Lensy: should a girl get the same chance to lead as a boy?","prompt":"What do you think?","options":["Yes","Exactly the same","Of course"],"affirm":"Girls deserve the very same chance to lead, learn and dream.","relearn":"Girls and boys deserve exactly the same chances.","persona":"Ananya","source":"gender equality"},
  {"id":"fp-1236","cat":"fair-opportunity","type":"reflect","hook":"Lensy: if you led the group, how would you hand out chances?","prompt":"What feels fair?","options":["By turns","Draw names","Whoever's keenest","Open to all"],"affirm":"Any of those is a fair way; you're thinking like a fair leader.","relearn":"Turns, draws and openness are all fair ways to share chances.","persona":"Ananya","source":"leadership / opportunity"},
  {"id":"fp-1237","cat":"fair-opportunity","type":"match","hook":"Match the chance to a fair way to decide it.","pairs":[{"left":"Who reads the assembly notice","right":"Take it in turns"},{"left":"Who gets the spare trip seat","right":"Draw a name"},{"left":"Who leads the project","right":"A fair class vote"},{"left":"Who tries the new kit first","right":"Whoever signs up"},{"left":"Who answers for the quiz","right":"Whoever knows it"}],"relearn":"Different chances suit different fair ways: turns, draws, votes, sign-ups.","persona":"any","source":"opportunity"},
  {"id":"fp-1238","cat":"fair-opportunity","type":"match","hook":"Match the unfair line to the fair reply.","pairs":[{"left":"\"Boys go first\"","right":"\"Let's take turns\""},{"left":"\"Girls just watch\"","right":"\"Everyone plays\""},{"left":"\"That's a boy's job\"","right":"\"Anyone can try\""},{"left":"\"Only my friends\"","right":"\"Open it to all\""},{"left":"\"She can't lead\"","right":"\"Anyone can lead\""}],"relearn":"Every unfair line has a calm, fair reply that opens the chance.","persona":"Reyansh","source":"voice / opportunity"},
  {"id":"fp-1239","cat":"fair-opportunity","type":"match","hook":"Match the kid to the chance they've earned a fair turn at.","pairs":[{"left":"Practised batting all week","right":"A spot in the line-up"},{"left":"Never got to present yet","right":"Today's show-and-tell"},{"left":"Always tidies, never plays","right":"First go on the swing"},{"left":"Knows the song best","right":"Leads the class song"},{"left":"Signed up first","right":"The next turn on the kit"}],"relearn":"A fair turn is earned by effort, waiting your turn, knowing or signing up.","persona":"any","source":"opportunity"},
  {"id":"fp-1260","cat":"stand-up","type":"role-play","hook":"The PT teacher says only boys try out for the relay race.","setup":"Speak up for a fair try-out. Say:","yourLine":[{"text":"\"Can everyone try out, sir? Then it's fair.\"","best":true},{"text":"Just watch the boys line up"}],"relearn":"Asking for an open try-out is a calm, fair move.","persona":"Reyansh","source":"fair chance / voice"},
  {"id":"fp-1261","cat":"stand-up","type":"role-play","hook":"At the tap, big kids push small ones out of the water line.","setup":"Stand up for the small kids. Say:","yourLine":[{"text":"\"Hey, there's a line, smallest gets a turn too.\"","best":true},{"text":"Drink and walk away"}],"relearn":"Naming the line out loud helps everyone get a turn.","persona":"any","source":"turn-taking / voice"},
  {"id":"fp-1262","cat":"stand-up","type":"role-play","hook":"Your cousin says your sister can't watch cricket, just cook.","setup":"Speak up at home, calm. Say:","yourLine":[{"text":"\"She can watch too, let's all take turns in the kitchen.\"","best":true},{"text":"Say it's not your business"}],"relearn":"A calm \"let's take turns\" works at home too.","persona":"Ananya","source":"home double standard / voice"},
  {"id":"fp-1263","cat":"stand-up","type":"role-play","hook":"Kids tell Faizan he can't join the dance because he's a boy.","setup":"Back up your friend. Say:","yourLine":[{"text":"\"Anyone who likes dancing can join, come on Faizan.\"","best":true},{"text":"Shrug and keep dancing"}],"relearn":"Backing up a shut-out friend is fairness in action.","persona":"Faizan-type","source":"ally / voice"},
  {"id":"fp-1264","cat":"stand-up","type":"role-play","hook":"The monitor lets only her friends use the new skipping rope.","setup":"Ask for a fair share. Say:","yourLine":[{"text":"\"Everyone wants a go, can we take turns with it?\"","best":true},{"text":"Sulk in the corner"}],"relearn":"Asking for turns beats grumbling on your own.","persona":"any","source":"hogging / voice"},
  {"id":"fp-1265","cat":"stand-up","type":"role-play","hook":"A boy is teased for crying when he's hurt; others laugh.","setup":"Stand up for him, calm. Say:","yourLine":[{"text":"\"Anyone can cry when it hurts, let's get help.\"","best":true},{"text":"Laugh with the others"}],"relearn":"Defending a teased kid is a kind, fair stand.","persona":"Faizan-type","source":"ally / voice"},
  {"id":"fp-1266","cat":"stand-up","type":"role-play","hook":"The chai stall uncle serves the boys first, girls wait every day.","setup":"Ask kindly for fair turns. Say:","yourLine":[{"text":"\"Uncle, we were here first, can it be first-come?\"","best":true},{"text":"Wait quietly again"}],"relearn":"A polite \"first-come\" ask names the fair rule.","persona":"Ananya","source":"everyday unfairness / voice"},
  {"id":"fp-1267","cat":"stand-up","type":"role-play","hook":"Your team wants to leave out the slowest runner from the game.","setup":"Speak up for them. Say:","yourLine":[{"text":"\"Everyone plays, we'll pick fair teams.\"","best":true},{"text":"Go along to win"}],"relearn":"Including everyone is fairer than only picking winners.","persona":"any","source":"inclusion / voice"},
  {"id":"fp-1268","cat":"stand-up","type":"role-play","hook":"A friend is blamed for a mess everyone made together.","setup":"Be fair and own your part. Say:","yourLine":[{"text":"\"We all made it, so we'll all clean it.\"","best":true},{"text":"Let your friend take the blame"}],"relearn":"Sharing the blame fairly is standing up too.","persona":"any","source":"fair blame / voice"},
  {"id":"fp-1269","cat":"stand-up","type":"branch","hook":"The class picks a leader; someone says \"only a boy can lead.\"","options":[{"text":"Say \"anyone can lead, let's vote fairly\"","consequence":"The class votes; the best pick wins, not a gender.","outcome":"fair","best":true},{"text":"Let the boys decide it","consequence":"A fair vote would give everyone a real say."}],"debrief":"Leading is decided by a fair vote, never by gender.","relearn":"Leadership goes to anyone, chosen fairly.","persona":"Ananya","source":"leadership / fairness"},
  {"id":"fp-1270","cat":"stand-up","type":"branch","hook":"You notice the canteen always gives extra to the tall kids.","options":[{"text":"Tell the canteen aunty so shares are equal","consequence":"Shares get evened out; everyone gets enough.","outcome":"fair","best":true},{"text":"Take your share and say nothing","consequence":"Naming an unfair share is how it gets fixed."}],"debrief":"Pointing out an unequal share helps fix it for all.","relearn":"You can name an unfair share to a fair grown-up.","persona":"any","source":"unequal shares"},
  {"id":"fp-1271","cat":"stand-up","type":"branch","hook":"A new kid is told they can't sit with your group at lunch.","options":[{"text":"Make room: \"sit here, there's space\"","consequence":"The new kid joins; the group is friendlier.","outcome":"ally","best":true},{"text":"Keep the seat saved for friends","consequence":"Leaving someone out isn't a fair welcome."}],"debrief":"Making room for a left-out kid is a fair, kind move.","relearn":"Including a new kid is fairness you can choose.","persona":"any","source":"inclusion"},
  {"id":"fp-1272","cat":"stand-up","type":"branch","hook":"Your group made up a rule that only your street can join the match.","options":[{"text":"Suggest opening it: \"any kid who wants can play\"","consequence":"More kids play; the game's bigger and fairer.","outcome":"fair","best":true},{"text":"Keep it just your street","consequence":"A rule that shuts kids out isn't a fair one."}],"debrief":"Opening up a closed rule makes the game fair for all.","relearn":"You can suggest changing a rule that shuts kids out.","persona":"any","source":"changing rules"},
  {"id":"fp-1273","cat":"stand-up","type":"branch","hook":"At the temple queue, a man waves your family's girls to the back.","options":[{"text":"Tell amma so a grown-up can sort the fair turn","consequence":"A grown-up helps everyone keep their place.","outcome":"persistent","best":true},{"text":"Move to the back quietly","consequence":"Telling a fair grown-up is a good next step."}],"debrief":"When speaking up alone is hard, a fair grown-up can help.","relearn":"You can ask a trusted grown-up to help make it fair.","persona":"Ananya","source":"escalation / agency"},
  {"id":"fp-1274","cat":"stand-up","type":"branch","hook":"Your best friend wants to keep an unfair rule that helps you both.","options":[{"text":"Say \"it's not fair on the others, let's change it\"","consequence":"You lose a small perk; the game feels fair to all.","outcome":"fair","best":true},{"text":"Keep it because your friend likes it","consequence":"Being fair sometimes means losing a perk you enjoy."}],"debrief":"Fair can mean dropping an unfair edge, even with a friend.","relearn":"Fairness can cost you a perk you didn't earn.","persona":"Reyansh","source":"privilege (kid-level)"},
  {"id":"fp-1275","cat":"stand-up","type":"branch","hook":"A teacher always asks girls to fetch water, never the boys.","options":[{"text":"Ask \"can we all take turns fetching, miss?\"","consequence":"The job rotates; no one group carries it.","outcome":"fair","best":true},{"text":"Just fetch it again","consequence":"A turn-taking ask spreads the job fairly."}],"debrief":"Chores at school rotate by turns, not by gender.","relearn":"You can ask for a job to rotate fairly.","persona":"Ananya","source":"school chore gap"},
  {"id":"fp-1276","cat":"stand-up","type":"branch","hook":"Some kids won't let the disabled boy join because he's slow.","options":[{"text":"Suggest a role he can do: \"he can be our scorer\"","consequence":"He joins his way; everyone has fun together.","outcome":"ally","best":true},{"text":"Start without him","consequence":"Leaving him out isn't fair; there's a way to include him."}],"debrief":"Finding a fair way for everyone to join beats shutting out.","relearn":"You can find a fair role so no one is left out.","persona":"Kabir-type","source":"inclusion / equity"},
  {"id":"fp-1277","cat":"stand-up","type":"branch","hook":"You hear seniors say the new science club is \"for clever boys only.\"","options":[{"text":"Tell girls who'd love it: \"it's open, let's sign up\"","consequence":"Girls join; the club has more ideas and fun.","outcome":"fair","best":true},{"text":"Believe it's just for boys","consequence":"A clever club is open to anyone keen, not one gender."}],"debrief":"A chance to learn is open to all, never gender-only.","relearn":"You can spread the word that a chance is open to all.","persona":"Ananya","source":"fair chance"},
  {"id":"fp-1278","cat":"stand-up","type":"branch","hook":"Your little brother is mocked for helping cook at the mela stall.","options":[{"text":"Back him: \"cooking's a skill, good job bhai\"","consequence":"He keeps helping proudly; the teasing fades.","outcome":"ally","best":true},{"text":"Tell him to stop so they quit teasing","consequence":"Backing him up beats asking him to hide what he does."}],"debrief":"Helping at home is for everyone; back up a teased helper.","relearn":"You can defend a boy who helps at home.","persona":"any","source":"boys help at home / ally"},
  {"id":"fp-1279","cat":"stand-up","type":"branch","hook":"The captain keeps benching one girl every match for no reason.","options":[{"text":"Ask \"can we rotate who plays so it's fair?\"","consequence":"Everyone gets game time; the team's happier.","outcome":"fair","best":true},{"text":"Say nothing, you're playing fine","consequence":"Fair play time is shared, not kept from one kid."}],"debrief":"Game time rotates fairly, not picked to leave one out.","relearn":"You can ask for fair turns even when you're fine.","persona":"any","source":"fairness for others"},
  {"id":"fp-1280","cat":"stand-up","type":"branch","hook":"Kids dare you to skip a smaller kid's turn so you go twice.","options":[{"text":"Refuse: \"no, it's their turn, that's fair\"","consequence":"The smaller kid gets their go; the dare flops.","outcome":"fair","best":true},{"text":"Take the extra turn","consequence":"Skipping someone's turn for yourself isn't fair."}],"debrief":"Saying no to an unfair dare protects someone's fair turn.","relearn":"You can refuse a dare that cheats someone's turn.","persona":"any","source":"peer pressure / fairness"},
  {"id":"fp-1281","cat":"stand-up","type":"branch","hook":"You see a rule on the notice board: \"girls swim Monday only.\"","options":[{"text":"Ask a fair teacher \"can swim days be shared equally?\"","consequence":"The teacher reviews it; the days get shared.","outcome":"persistent","best":true},{"text":"Accept it as just the rule","consequence":"Even a written rule can be made fairer if you ask."}],"debrief":"A written unfair rule can still be changed if you speak up.","relearn":"Unfair rules aren't permanent; you can ask to change them.","persona":"Ananya","source":"changing rules"},
  {"id":"fp-1282","cat":"stand-up","type":"branch","hook":"At the family puja, boys are served sweets first, girls last.","options":[{"text":"Say to dadi \"can the youngest go first this time?\"","consequence":"Dadi nods; the order changes, everyone's happy.","outcome":"fair","best":true},{"text":"Wait your turn as always","consequence":"A gentle ask can shift an unfair serving order."}],"debrief":"A respectful ask at home can make a turn order fair.","relearn":"You can gently suggest a fairer order at home.","persona":"Sunita","source":"home / joint family"},
  {"id":"fp-1283","cat":"stand-up","type":"branch","hook":"Friends plan to lock out a kid who told a teacher about cheating.","options":[{"text":"Say \"telling the truth isn't a reason to shut him out\"","consequence":"The group rethinks; he's not punished for honesty.","outcome":"ally","best":true},{"text":"Join the lock-out","consequence":"Punishing honesty isn't fair; you can defend him."}],"debrief":"Standing up for an honest kid is a fair, brave move.","relearn":"You can defend someone punished for doing right.","persona":"any","source":"ally / fairness"},
  {"id":"fp-1284","cat":"stand-up","type":"strike-rewrite","hook":"\"You're just a kid, so the teacher won't listen to you.\"","myth":{"un":"Grown-ups never listen to kids about fairness.","re":"Many fair-minded grown-ups will listen when you ask calmly.","why":"A clear, calm fair-ask helps a grown-up see the problem."},"relearn":"A calm ask helps a fair grown-up listen.","persona":"Ananya","source":"agency / voice"},
  {"id":"fp-1285","cat":"stand-up","type":"strike-rewrite","hook":"\"If you speak up, your friends will think you're a snitch.\"","myth":{"un":"Speaking up for fairness makes you a snitch.","re":"Asking for fair turns helps everyone, that's not snitching.","why":"Snitching gets people in trouble; this makes things fair."},"relearn":"Asking for fairness isn't snitching, it helps all.","persona":"any","source":"values"},
  {"id":"fp-1286","cat":"stand-up","type":"strike-rewrite","hook":"\"One kid can't change anything that's unfair anyway.\"","myth":{"un":"One kid's voice can't change an unfair rule.","re":"One kid speaking up often gets others to join in.","why":"Lots of fair rules began with just one person asking."},"relearn":"One voice can start a fair change.","persona":"Ananya","source":"agency"},
  {"id":"fp-1287","cat":"stand-up","type":"strike-rewrite","hook":"\"Standing up for a friend just gets you in trouble too.\"","myth":{"un":"Backing up a shut-out friend only gets you in trouble.","re":"Backing up a friend is brave and often helps them join.","why":"When one kid stands up, others usually feel braver too."},"relearn":"Backing up a friend is brave, not trouble.","persona":"Faizan-type","source":"ally"},
  {"id":"fp-1288","cat":"stand-up","type":"strike-rewrite","hook":"\"Fairness only matters when it's something that affects you.\"","myth":{"un":"Fairness only counts when it happens to you.","re":"Fairness is everyone's business; you can help others too.","why":"A fair place is better and kinder for every kid in it."},"relearn":"You can care about fairness for others, not just you.","persona":"Ananya","source":"solidarity"},
  {"id":"fp-1289","cat":"stand-up","type":"strike-rewrite","hook":"\"It's polite to stay quiet when grown-ups make an unfair rule.\"","myth":{"un":"Being quiet about an unfair rule is just good manners.","re":"You can ask politely and respectfully if a rule is fair.","why":"A kind, calm question can make a rule fairer for all."},"relearn":"You can ask politely if a rule is fair.","persona":"Ananya","source":"respectful voice"},
  {"id":"fp-1290","cat":"stand-up","type":"strike-rewrite","hook":"\"Giving up your turn to be fair makes you a loser.\"","myth":{"un":"Sharing an unfair advantage makes you a loser.","re":"Sharing a turn fairly is a strong, generous thing to do.","why":"Real winners want the game to be fair for everyone."},"relearn":"Sharing fairly is strong, not losing.","persona":"Reyansh","source":"privilege (kid-level)"},
  {"id":"fp-1291","cat":"stand-up","type":"strike-rewrite","hook":"\"Spotting an unfair rule is being a troublemaker.\"","myth":{"un":"Noticing an unfair rule means you're a troublemaker.","re":"Noticing what's unfair is the first step to fixing it.","why":"You can't make a rule fairer until someone names it."},"relearn":"Noticing unfairness starts a fair fix.","persona":"Ananya","source":"changemaking"},
  {"id":"fp-1292","cat":"stand-up","type":"strike-rewrite","hook":"\"If a rule's old, it must be fair, so leave it alone.\"","myth":{"un":"An old rule must be fair just because it's old.","re":"Even old rules can be unfair and changed to fairer ones.","why":"Rules are made by people, and people can make them fairer."},"relearn":"Old rules can still be made fairer.","persona":"Ananya","source":"changing rules"},
  {"id":"fp-1293","cat":"stand-up","type":"reflect","hook":"Lensy: when have you felt brave standing up for what's fair?","prompt":"What comes to mind?","options":["At home","At school","On the playground","Still building up to it"],"affirm":"Every small stand counts, and you're growing braver each time.","relearn":"Standing up for fairness, even small, is brave.","persona":"Ananya","source":"courage"},
  {"id":"fp-1294","cat":"stand-up","type":"reflect","hook":"Lensy: who in your life stands up for fairness in a way you like?","prompt":"Think of someone.","options":["A friend","A parent","A teacher","An older sibling"],"affirm":"Noticing fair heroes around you helps you become one too.","relearn":"You can learn standing up from the fair people around you.","persona":"any","source":"role models"},
  {"id":"fp-1295","cat":"stand-up","type":"reflect","hook":"Lensy: what helps you feel brave enough to speak up?","prompt":"What helps you?","options":["A friend beside me","Taking a breath","Knowing it's right","Practising the words"],"affirm":"Whatever helps you is worth keeping; brave grows with practice.","relearn":"You can find what helps you feel brave to speak up.","persona":"any","source":"courage"},
  {"id":"fp-1296","cat":"stand-up","type":"reflect","hook":"Lensy: how do you feel after you've stood up for someone?","prompt":"How does it feel?","options":["Proud","A bit nervous","Glad I did","Stronger"],"affirm":"All those feelings are okay; standing up takes real heart.","relearn":"It's normal to feel many things after standing up.","persona":"Faizan-type","source":"feelings"},
  {"id":"fp-1297","cat":"stand-up","type":"reflect","hook":"Lensy: what's a fair change you'd love to see at your school?","prompt":"Dream it up.","options":["Shared chores","Fair team picks","Everyone gets a say","Open clubs for all"],"affirm":"Big fair changes start with a kid dreaming them, like you.","relearn":"Imagining a fairer place is how change begins.","persona":"Ananya","source":"changemaking"},
  {"id":"fp-1298","cat":"stand-up","type":"reflect","hook":"Lensy: when something's unfair, what's the first thing you notice?","prompt":"What tips you off?","options":["Someone's left out","A funny feeling inside","Only one group wins","People look sad"],"affirm":"Trust that feeling, it's your fairness sense waking up.","relearn":"That uneasy feeling can be your fairness sense.","persona":"any","source":"noticing"},
  {"id":"fp-1299","cat":"stand-up","type":"reflect","hook":"Lensy: what would you say to a kid too scared to speak up?","prompt":"What would you tell them?","options":["You're not alone","Start small","I'll go with you","Your voice matters"],"affirm":"That's exactly the kind thing a fairness friend would say.","relearn":"Encouraging a nervous kid is its own kind of standing up.","persona":"any","source":"solidarity"},
  {"id":"fp-1300","cat":"stand-up","type":"reflect","hook":"Lensy: where do you most want to be braver about fairness?","prompt":"Pick a place.","options":["With my family","With my friends","With grown-ups","With strangers"],"affirm":"Naming where you want to grow is a brave first step itself.","relearn":"You can choose where to practise being braver.","persona":"any","source":"agency"},
  {"id":"fp-1301","cat":"stand-up","type":"reflect","hook":"Lensy: what does it feel like inside when YOU get treated unfairly?","prompt":"Sit with it.","options":["Frustrated","Sad","Left out","Like saying something"],"affirm":"Knowing that feeling helps you spot it for others too.","relearn":"Knowing unfairness in yourself helps you see it in others.","persona":"Ananya","source":"empathy"},
  {"id":"fp-1302","cat":"stand-up","type":"build","hook":"Build a plan to speak up about an unfair turn rule.","prompt":"Put the steps in a calm order.","pieces":["Notice the unfair rule","Take a breath to stay calm","Say the fair-ask clearly","Ask a fair grown-up if needed"],"mode":"sequence","key":["Notice the unfair rule","Take a breath to stay calm","Say the fair-ask clearly","Ask a fair grown-up if needed"],"relearn":"Notice, breathe, speak up, then ask a grown-up if needed.","persona":"Ananya","source":"speak-up plan"},
  {"id":"fp-1303","cat":"stand-up","type":"build","hook":"Build a fair way to back up a friend who's shut out.","prompt":"Pick the moves that help your friend join.","pieces":["Stand next to your friend","Say they can play too","Make room for them","Laugh at them","Walk away and ignore it"],"mode":"assemble","key":["Stand next to your friend","Say they can play too","Make room for them"],"relearn":"Stand close, speak up, and make room for a shut-out friend.","persona":"Faizan-type","source":"ally kit"},
  {"id":"fp-1304","cat":"stand-up","type":"build","hook":"Build a calm fair-ask you could use on the playground.","prompt":"Pick the words that make a kind, clear fair-ask.","pieces":["\"That's not quite fair\"","\"Can everyone get a turn?\"","\"Let's sort it together\"","\"You're all cheating\"","\"This is stupid\""],"mode":"assemble","key":["\"That's not quite fair\"","\"Can everyone get a turn?\"","\"Let's sort it together\""],"relearn":"A fair-ask names it, asks for turns, and invites help.","persona":"any","source":"fair-ask kit"},
  {"id":"fp-1305","cat":"stand-up","type":"build","hook":"Build the steps for getting a fair grown-up to help.","prompt":"Order the steps for asking a grown-up.","pieces":["Find a fair-minded grown-up","Explain what's unfair calmly","Suggest a fairer way","Thank them for helping"],"mode":"sequence","key":["Find a fair-minded grown-up","Explain what's unfair calmly","Suggest a fairer way","Thank them for helping"],"relearn":"Find them, explain calmly, suggest a fix, say thanks.","persona":"Ananya","source":"escalation plan"},
  {"id":"fp-1306","cat":"stand-up","type":"build","hook":"Build a kit of brave things to do when a rule shuts kids out.","prompt":"Pick the brave, fair moves.","pieces":["Ask why the rule exists","Suggest a fairer rule","Get others to ask too","Break the rule sneakily","Tease the rule-maker"],"mode":"assemble","key":["Ask why the rule exists","Suggest a fairer rule","Get others to ask too"],"relearn":"Ask why, suggest a fix, and bring others along.","persona":"Ananya","source":"changemaker kit"},
  {"id":"fp-1307","cat":"stand-up","type":"build","hook":"Build the order for sharing an unfair perk you have.","prompt":"Put the fair steps in order.","pieces":["Notice you always get first go","Offer to take turns","Let someone else go first","Enjoy the game together"],"mode":"sequence","key":["Notice you always get first go","Offer to take turns","Let someone else go first","Enjoy the game together"],"relearn":"Notice your edge, offer turns, let others go, enjoy it fair.","persona":"Reyansh","source":"share-the-perk plan"},
  {"id":"fp-1308","cat":"stand-up","type":"build","hook":"Build a welcome for a new kid being left out of the game.","prompt":"Pick the moves that make them feel included.","pieces":["Say hi and use their name","Show them the rules","Offer them the next turn","Whisper about them","Pick teams without them"],"mode":"assemble","key":["Say hi and use their name","Show them the rules","Offer them the next turn"],"relearn":"Greet them, show the rules, and offer a turn.","persona":"any","source":"welcome kit"},
  {"id":"fp-1309","cat":"stand-up","type":"build","hook":"Build a plan to fix a chore that always lands on one kid.","prompt":"Order the steps to make it fair.","pieces":["Notice one kid does it all","Suggest a turn-rota","Write down whose turn it is","Check it stays fair"],"mode":"sequence","key":["Notice one kid does it all","Suggest a turn-rota","Write down whose turn it is","Check it stays fair"],"relearn":"Notice, suggest a rota, write turns, keep it fair.","persona":"Sunita","source":"fair-chore plan"},
  {"id":"fp-1310","cat":"stand-up","type":"match","hook":"Match each unfair line to a fair thing you could say back.","pairs":[{"left":"\"Boys go first.\"","right":"\"Let's take turns.\""},{"left":"\"You can't play.\"","right":"\"There's room for you.\""},{"left":"\"Girls just watch.\"","right":"\"Anyone can play.\""},{"left":"\"It's always been this way.\"","right":"\"We can make it fairer.\""},{"left":"\"Not your problem.\"","right":"\"Fair is everyone's job.\""}],"relearn":"Every unfair line has a calm, fair reply.","persona":"Ananya","source":"fair comebacks"},
  {"id":"fp-1311","cat":"stand-up","type":"match","hook":"Match each place to a fair way to stand up there.","pairs":[{"left":"At the dinner table","right":"\"Let's all clear plates.\""},{"left":"In the cricket gully","right":"\"Everyone bats.\""},{"left":"In the classroom","right":"\"Anyone can answer.\""},{"left":"At the water tap","right":"\"Keep the line fair.\""},{"left":"In the school club","right":"\"It's open to all.\""}],"relearn":"You can stand up for fairness in any place.","persona":"any","source":"fair-everywhere"},
  {"id":"fp-1312","cat":"stand-up","type":"match","hook":"Match each brave move to who it helps most.","pairs":[{"left":"Make room at lunch","right":"A lonely new kid"},{"left":"Ask for fair team picks","right":"The slow runner"},{"left":"Share your first turn","right":"The kid always last"},{"left":"Say \"that's not funny\"","right":"A teased friend"},{"left":"Tell a fair teacher","right":"A whole shut-out group"}],"relearn":"Each brave move helps a real person be treated fairly.","persona":"any","source":"ally map"},
  {"id":"fp-1313","cat":"stand-up","type":"match","hook":"Match each feeling to a fair thing you can do with it.","pairs":[{"left":"\"That's not fair!\"","right":"Say it calmly out loud"},{"left":"Feeling scared","right":"Take a breath first"},{"left":"Not sure what to say","right":"Ask a friend to help"},{"left":"Brushed off","right":"Tell a fair grown-up"},{"left":"Proud after","right":"Cheer on the next kid"}],"relearn":"Every fairness feeling has a brave next step.","persona":"Ananya","source":"feeling-to-action"},
  {"id":"fp-1314","cat":"stand-up","type":"match","hook":"Match each kid being treated unfairly to a fair fix.","pairs":[{"left":"Only she fetches water","right":"Take turns fetching"},{"left":"He's mocked for cooking","right":"\"Cooking's a great skill\""},{"left":"New kid sits alone","right":"\"Come sit with us\""},{"left":"One team always benched","right":"Rotate who plays"},{"left":"Club is \"boys only\"","right":"\"It's open to all\""}],"relearn":"Every unfair moment has a fair fix you can name.","persona":"any","source":"fix map"},
  {"id":"fp-1315","cat":"stand-up","type":"match","hook":"Match each excuse for staying quiet to a brave reply.","pairs":[{"left":"\"I'm just a kid.\"","right":"\"My voice counts too.\""},{"left":"\"It's not my turn.\"","right":"\"Fair is everyone's job.\""},{"left":"\"They'll laugh at me.\"","right":"\"Doing right is brave.\""},{"left":"\"Nothing will change.\"","right":"\"One ask can start it.\""},{"left":"\"It's always been so.\"","right":"\"We can make it fairer.\""}],"relearn":"For every excuse to stay quiet, there's a braver answer.","persona":"Ananya","source":"excuse-buster"},
  {"id":"fp-1316","cat":"stand-up","type":"match","hook":"Match each calm word to the moment it fits.","pairs":[{"left":"\"Can we take turns?\"","right":"Someone's hogging"},{"left":"\"There's room for you.\"","right":"A kid left out"},{"left":"\"Let's vote fairly.\"","right":"Picking a leader"},{"left":"\"We'll all help.\"","right":"One kid does it all"},{"left":"\"Is that fair?\"","right":"A new rule appears"}],"relearn":"The right calm word fits the unfair moment.","persona":"any","source":"word-to-moment"},
  {"id":"fp-1317","cat":"stand-up","type":"match","hook":"Match each step of standing up to what it does.","pairs":[{"left":"Notice","right":"Spots the unfair rule"},{"left":"Breathe","right":"Keeps you calm"},{"left":"Speak","right":"Names the fair-ask"},{"left":"Ask a grown-up","right":"Helps when alone isn't enough"},{"left":"Cheer","right":"Backs up the next kid"}],"relearn":"Each step of standing up has its own job.","persona":"Ananya","source":"steps map"},
  {"id":"fp-1318","cat":"stand-up","type":"sort","hook":"Sort each into Stand up or Stay quiet, then think why.","items":[{"id":"i1","text":"Asking \"can everyone get a turn?\""},{"id":"i2","text":"Laughing along at a put-down"},{"id":"i3","text":"Telling a fair teacher about a shut-out kid"},{"id":"i4","text":"Pretending you didn't see it"},{"id":"i5","text":"Making room for a left-out kid"},{"id":"i6","text":"Keeping an unfair perk quietly"}],"bins":[{"id":"up","label":"Stand up ✊","valence":"tell"},{"id":"quiet","label":"Stay quiet 😬","valence":"uhoh"}],"key":{"i1":"up","i2":"quiet","i3":"up","i4":"quiet","i5":"up","i6":"quiet"},"relearn":"Standing up names it and acts; staying quiet lets it slide.","persona":"any","source":"stand-up vs quiet"},
  {"id":"fp-1319","cat":"stand-up","type":"sort","hook":"Sort each line into Fair or Not fair.","items":[{"id":"i1","text":"\"Whoever's next gets the swing.\""},{"id":"i2","text":"\"Only my street can play.\""},{"id":"i3","text":"\"We all clear our own plates.\""},{"id":"i4","text":"\"Girls can't be captain.\""},{"id":"i5","text":"\"Anyone keen can join the club.\""},{"id":"i6","text":"\"Boys always get first go.\""}],"bins":[{"id":"fair","label":"Fair 💚","valence":"pos"},{"id":"notfair","label":"Not fair 🛑","valence":"neg"}],"key":{"i1":"fair","i2":"notfair","i3":"fair","i4":"notfair","i5":"fair","i6":"notfair"},"relearn":"A fair rule lets everyone share; an unfair one shuts kids out.","persona":"Ananya","source":"fair vs not fair"},
  {"id":"fp-1320","cat":"stand-up","type":"sort","hook":"Sort each move into Brave stand or Just mean.","items":[{"id":"i1","text":"Asking calmly for fair turns"},{"id":"i2","text":"Calling the rule-maker stupid"},{"id":"i3","text":"Inviting a shut-out kid in"},{"id":"i4","text":"Shoving to get your way"},{"id":"i5","text":"Suggesting a fairer rule"},{"id":"i6","text":"Teasing kids who disagree"}],"bins":[{"id":"brave","label":"Brave stand ✊","valence":"pos"},{"id":"mean","label":"Just mean 🛑","valence":"neg"}],"key":{"i1":"brave","i2":"mean","i3":"brave","i4":"mean","i5":"brave","i6":"mean"},"relearn":"Standing up is calm and fair, never mean or pushy.","persona":"any","source":"brave vs mean"},
  {"id":"fp-1321","cat":"stand-up","type":"sort","hook":"Sort each into Speak up now or Tell a grown-up.","items":[{"id":"i1","text":"A friend skips your turn once"},{"id":"i2","text":"A rule shuts girls out every day"},{"id":"i3","text":"Kids won't share the ball"},{"id":"i4","text":"You asked but got brushed off"},{"id":"i5","text":"Someone cuts the water line"},{"id":"i6","text":"An unfair rule is on the board"}],"bins":[{"id":"now","label":"Speak up now 🗣️","valence":"tell"},{"id":"grownup","label":"Tell a grown-up 💚","valence":"pos"}],"key":{"i1":"now","i2":"grownup","i3":"now","i4":"grownup","i5":"now","i6":"grownup"},"relearn":"Speak up for small things; ask a grown-up for the big ones.","persona":"Ananya","source":"when-to-escalate"},
  {"id":"fp-1322","cat":"stand-up","type":"sort","hook":"Sort each into Helps the shut-out kid or Hurts them.","items":[{"id":"i1","text":"Saving them a seat"},{"id":"i2","text":"Whispering about them"},{"id":"i3","text":"Cheering when they try"},{"id":"i4","text":"Picking teams without them"},{"id":"i5","text":"Showing them the rules"},{"id":"i6","text":"Laughing when they miss"}],"bins":[{"id":"helps","label":"Helps 💚","valence":"pos"},{"id":"hurts","label":"Hurts 🛑","valence":"neg"}],"key":{"i1":"helps","i2":"hurts","i3":"helps","i4":"hurts","i5":"helps","i6":"hurts"},"relearn":"Welcoming moves help; whispering and excluding hurt.","persona":"Faizan-type","source":"helps vs hurts"},
  {"id":"fp-1323","cat":"stand-up","type":"sort","hook":"Sort each thought into Fairness sense or Just an excuse.","items":[{"id":"i1","text":"\"Someone's being left out.\""},{"id":"i2","text":"\"It's not my problem.\""},{"id":"i3","text":"\"Only one group ever wins.\""},{"id":"i4","text":"\"I'm just a kid, who cares.\""},{"id":"i5","text":"\"That feels unfair inside.\""},{"id":"i6","text":"\"It's always been this way.\""}],"bins":[{"id":"sense","label":"Fairness sense 💚","valence":"pos"},{"id":"excuse","label":"Just an excuse 😬","valence":"uhoh"}],"key":{"i1":"sense","i2":"excuse","i3":"sense","i4":"excuse","i5":"sense","i6":"excuse"},"relearn":"Your fairness sense notices; excuses talk you out of acting.","persona":"any","source":"sense vs excuse"},
  {"id":"fp-1324","cat":"stand-up","type":"sort","hook":"Sort each into A real win or Not a fair win.","items":[{"id":"i1","text":"Winning after fair turns"},{"id":"i2","text":"Winning by skipping others"},{"id":"i3","text":"Sharing first go and still playing"},{"id":"i4","text":"Changing the rule mid-game to win"},{"id":"i5","text":"Cheering the kid who came last"},{"id":"i6","text":"Locking others out so you win"}],"bins":[{"id":"real","label":"Real win 💚","valence":"pos"},{"id":"notwin","label":"Not fair 🛑","valence":"neg"}],"key":{"i1":"real","i2":"notwin","i3":"real","i4":"notwin","i5":"real","i6":"notwin"},"relearn":"A real win is fair and shared, not won by shutting kids out.","persona":"Reyansh","source":"fair win"},
  {"id":"fp-1325","cat":"stand-up","type":"sort","hook":"Sort each into Being fair or Keeping an unfair edge.","items":[{"id":"i1","text":"Offering to take turns going first"},{"id":"i2","text":"Always batting first because you can"},{"id":"i3","text":"Letting a smaller kid have a go"},{"id":"i4","text":"Keeping the best spot every time"},{"id":"i5","text":"Sharing the new rope around"},{"id":"i6","text":"Hogging the swing all break"}],"bins":[{"id":"fair","label":"Being fair 💚","valence":"pos"},{"id":"edge","label":"Unfair edge 🛑","valence":"neg"}],"key":{"i1":"fair","i2":"edge","i3":"fair","i4":"edge","i5":"fair","i6":"edge"},"relearn":"Being fair can mean giving up an edge you didn't earn.","persona":"Reyansh","source":"give-up-perk"},
  {"id":"fp-1350","cat":"what-is-fair","type":"sort","hook":"Sort each into fair or not fair at the tea stall queue.","items":[{"id":"a","text":"Everyone waits their turn in line"},{"id":"b","text":"A boy cuts to the front"},{"id":"c","text":"Saving a spot for a tired auntie"},{"id":"d","text":"Pushing little kids out"},{"id":"e","text":"First come, first served"},{"id":"f","text":"Only my gang gets served"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair means everyone gets their turn in the line.","persona":"any","source":"fairness / turn-taking"},
  {"id":"fp-1351","cat":"what-is-fair","type":"sort","hook":"Sort: does this share the snack fairly, or not?","items":[{"id":"a","text":"Cutting the chikki into equal bits"},{"id":"b","text":"Eating it all yourself"},{"id":"c","text":"One piece left, so you split it"},{"id":"d","text":"Hiding some so others miss out"},{"id":"e","text":"Asking if anyone hasn't had any"},{"id":"f","text":"Giving the most to your best friend"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Sharing a snack equally is fair; hogging it isn't.","persona":"any","source":"sharing / fairness"},
  {"id":"fp-1352","cat":"what-is-fair","type":"sort","hook":"Sort: a fair way to decide, or an unfair one?","items":[{"id":"a","text":"Toss a coin for who bats first"},{"id":"b","text":"\"I'm oldest, so I decide everything\""},{"id":"c","text":"Take turns being the chooser"},{"id":"d","text":"Whoever shouts loudest wins"},{"id":"e","text":"Draw lots so it's random"},{"id":"f","text":"Only the captain's friends decide"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair ways to decide give everyone an even chance.","persona":"Ananya","source":"fair process"},
  {"id":"fp-1353","cat":"what-is-fair","type":"sort","hook":"Sort: leaves someone out, or includes everyone?","items":[{"id":"a","text":"\"You can all join our game\""},{"id":"b","text":"\"This bench is only for us\""},{"id":"c","text":"Making room for the new kid"},{"id":"d","text":"\"You're too small to play\""},{"id":"e","text":"Picking sides so no one's spare"},{"id":"f","text":"Whispering so one kid feels left out"}],"bins":[{"id":"in","label":"Everyone matters","valence":"pos"},{"id":"out","label":"Leaves out","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"Fair means no one is left out; everyone matters.","persona":"any","source":"inclusion / fairness"},
  {"id":"fp-1354","cat":"what-is-fair","type":"sort","hook":"Sort: is this just me getting my way, or fair to all?","items":[{"id":"a","text":"\"Let's pick a game we all like\""},{"id":"b","text":"\"We only play what I want\""},{"id":"c","text":"Asking what everyone feels like"},{"id":"d","text":"Sulking till you get your pick"},{"id":"e","text":"Taking turns to choose the game"},{"id":"f","text":"Changing rules so only you win"}],"bins":[{"id":"fair","label":"Fair to all","valence":"pos"},{"id":"my","label":"Just my way","valence":"neg"}],"key":{"a":"fair","b":"my","c":"fair","d":"my","e":"fair","f":"my"},"relearn":"Fair is about everyone, not only me getting my way.","persona":"any","source":"fairness"},
  {"id":"fp-1355","cat":"what-is-fair","type":"sort","hook":"Sort: same for all, or what each one needs?","items":[{"id":"a","text":"A box for the shorter kid to see over"},{"id":"b","text":"Same big chair for the tiny kid"},{"id":"c","text":"A bigger plate for the hungriest"},{"id":"d","text":"Same fast pace for a hurt leg"},{"id":"e","text":"Reading the menu to a friend who can't"},{"id":"f","text":"One umbrella, only you stay dry"}],"bins":[{"id":"need","label":"Meets each need","valence":"pos"},{"id":"no","label":"Not really fair","valence":"neg"}],"key":{"a":"need","b":"no","c":"need","d":"no","e":"need","f":"no"},"relearn":"Sometimes fair means giving each what they need.","persona":"Kabir-type","source":"equity preview"},
  {"id":"fp-1356","cat":"what-is-fair","type":"sort","hook":"Sort: a question worth asking, or making trouble?","items":[{"id":"a","text":"\"Is it fair only some get a turn?\""},{"id":"b","text":"\"You're stupid for asking\""},{"id":"c","text":"\"Could we share this more evenly?\""},{"id":"d","text":"Yelling to shut someone up"},{"id":"e","text":"\"Why does only one of us help?\""},{"id":"f","text":"Calling a kid a tattletale for asking"}],"bins":[{"id":"ask","label":"Fair to ask","valence":"pos"},{"id":"no","label":"Not okay","valence":"neg"}],"key":{"a":"ask","b":"no","c":"ask","d":"no","e":"ask","f":"no"},"relearn":"\"Is that fair?\" is a good question, not trouble.","persona":"Ananya","source":"agency / voice"},
  {"id":"fp-1357","cat":"what-is-fair","type":"sort","hook":"Sort: a fair turn-rule, or a hogging-rule?","items":[{"id":"a","text":"Two minutes each on the cycle"},{"id":"b","text":"\"It's mine all evening\""},{"id":"c","text":"A turn-list pinned on the wall"},{"id":"d","text":"Riding off so no one else can"},{"id":"e","text":"\"Whoever's waiting goes next\""},{"id":"f","text":"Only handing it to your sibling"}],"bins":[{"id":"turn","label":"Fair turns","valence":"pos"},{"id":"hog","label":"Hogging","valence":"neg"}],"key":{"a":"turn","b":"hog","c":"turn","d":"hog","e":"turn","f":"hog"},"relearn":"Sharing the turn is fair; hogging it isn't.","persona":"any","source":"sharing"},
  {"id":"fp-1358","cat":"what-is-fair","type":"sort","hook":"Sort: change it to be fairer, or it's fair already?","items":[{"id":"a","text":"\"Only boys ring the bell\""},{"id":"b","text":"\"Everyone gets a turn\""},{"id":"c","text":"\"Girls clean, boys play\""},{"id":"d","text":"\"We rotate the monitor job\""},{"id":"e","text":"\"One kid is always last\""},{"id":"f","text":"\"Anyone who knows can answer\""}],"bins":[{"id":"change","label":"Make it fairer","valence":"tell"},{"id":"ok","label":"Fair already","valence":"pos"}],"key":{"a":"change","b":"ok","c":"change","d":"ok","e":"change","f":"ok"},"relearn":"Unfair rules can be changed; fair ones already give all a turn.","persona":"Ananya","source":"rules / agency"},
  {"id":"fp-1359","cat":"what-is-fair","type":"sort","hook":"Sort: more than one fair move, or clearly not fair?","items":[{"id":"a","text":"Split the last roti in half"},{"id":"b","text":"Grab both rotis for yourself"},{"id":"c","text":"Give it to whoever's hungriest"},{"id":"d","text":"Eat it before anyone notices"},{"id":"e","text":"Take turns who gets the last one"},{"id":"f","text":"Throw it away so no one has it"}],"bins":[{"id":"fair","label":"A fair move","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"There can be more than one fair move; you reason it out.","persona":"any","source":"fairness / reasoning"},
  {"id":"fp-1360","cat":"what-is-fair","type":"reflect","hook":"Lensy: when something is fair, what do you notice in the group?","prompt":"Pick one.","options":["Everyone looks happy","No one is sulking","People feel counted"],"affirm":"Fair shows up when everyone feels they were counted.","relearn":"You can spot fairness by how everyone feels counted.","persona":"any","source":"fairness sense"},
  {"id":"fp-1361","cat":"what-is-fair","type":"reflect","hook":"Lensy: who should fairness be for?","prompt":"What do you think?","options":["Everyone","Me and others equally","All of us, not just me"],"affirm":"Fairness is for everyone, not only the one asking.","relearn":"Fair is about everyone, not just me getting my way.","persona":"Ananya","source":"fairness"},
  {"id":"fp-1362","cat":"what-is-fair","type":"reflect","hook":"Lensy: a friend gets left out a lot. What does that make you want to do?","prompt":"What do you think?","options":["Include them","Give them a turn","Sit with them"],"affirm":"Wanting no one left out is your fairness-sense at work.","relearn":"Fairness means no one is left out; everyone matters.","persona":"any","source":"inclusion"},
  {"id":"fp-1363","cat":"what-is-fair","type":"reflect","hook":"Lensy: a shorter friend needs a box to see the match. Is the box fair?","prompt":"What do you think?","options":["Yes, now they can see","It meets their need","Fair, not the same"],"affirm":"Giving what each one needs is a kind of fair too.","relearn":"Sometimes fair means each gets what they need, not the same.","persona":"Kabir-type","source":"equity preview"},
  {"id":"fp-1364","cat":"what-is-fair","type":"reflect","hook":"Lensy: someone says an old rule is unfair. Can a rule ever change?","prompt":"What do you think?","options":["Yes, people made it","If we ask, it can","Rules aren't forever"],"affirm":"Rules are made by people, so people can make them fairer.","relearn":"Unfair rules are not permanent; they can be changed.","persona":"Ananya","source":"rules / agency"},
  {"id":"fp-1365","cat":"what-is-fair","type":"reflect","hook":"Lensy: you wonder out loud, \"is that fair?\" Should you feel bad asking?","prompt":"What do you think?","options":["No, it's a good question","Asking helps","It's brave to ask"],"affirm":"Asking \"is that fair?\" is good thinking, not trouble.","relearn":"\"Is that fair?\" is a question worth asking.","persona":"Ananya","source":"agency / voice"},
  {"id":"fp-1366","cat":"what-is-fair","type":"reflect","hook":"Lensy: there's one swing and a long line. What feels fair to you?","prompt":"What do you think?","options":["Everyone takes a turn","A turn each, by line","Share it round"],"affirm":"Sharing the swing by turns lets everyone enjoy it.","relearn":"Fair means everyone gets a turn, not one kid hogging.","persona":"any","source":"sharing"},
  {"id":"fp-1367","cat":"what-is-fair","type":"reflect","hook":"Lensy: there's more than one fair way to split a cake. Which feels right?","prompt":"What do you think?","options":["Equal slices for all","A say for whoever baked it","Take turns first pick"],"affirm":"More than one move can be fair; you reason out which fits.","relearn":"There can be more than one fair move; you decide.","persona":"any","source":"fairness / reasoning"},
  {"id":"fp-1368","cat":"what-is-fair","type":"reflect","hook":"Lensy: does fair mean you always get exactly what you want?","prompt":"What do you think?","options":["No","Sometimes I share","Everyone gets a bit"],"affirm":"Fair isn't always your way; it's a turn or share for all.","relearn":"Fair is about everyone, not just me getting my way.","persona":"any","source":"fairness"},
  {"id":"fp-1369","cat":"what-is-fair","type":"reflect","hook":"Lensy: think of a time something felt fair. What made it feel that way?","prompt":"What do you think?","options":["Everyone got a go","No one was skipped","We all agreed"],"affirm":"You already know fairness when you feel it; trust that.","relearn":"Fairness is everyone getting a go and feeling counted.","persona":"any","source":"fairness sense"},
  {"id":"fp-1370","cat":"what-is-fair","type":"reflect","hook":"Lensy: only one kid always gets the new ball first. How does that sit?","prompt":"What do you think?","options":["Not quite fair","Others want a turn","We could rotate"],"affirm":"Noticing one kid always going first is your fairness-sense.","relearn":"Always one kid first isn't fair; turns make it fair.","persona":"Ananya","source":"justice sensitivity"},
  {"id":"fp-1371","cat":"what-is-fair","type":"reflect","hook":"Lensy: a new classmate doesn't know the game yet. What feels fair?","prompt":"What do you think?","options":["Teach them first","Give them an easy turn","Let them join in"],"affirm":"Helping someone join in is a fair, kind move.","relearn":"Fairness can mean a little extra help so all can join.","persona":"Kabir-type","source":"equity / inclusion"},
  {"id":"fp-1372","cat":"what-is-fair","type":"reflect","hook":"Lensy: who decides what counts as fair in your group?","prompt":"What do you think?","options":["All of us together","We talk it out","Everyone gets a say"],"affirm":"Fairness works best when everyone has a say in it.","relearn":"Fair is reasoned out together, not handed down.","persona":"any","source":"fair process"},
  {"id":"fp-1373","cat":"what-is-fair","type":"reflect","hook":"Lensy: if you had one wish for your playground, what would be fair?","prompt":"Pick your wish.","options":["Everyone gets a turn","No one left out","A say for all"],"affirm":"That wish is what Fair Play World is built on.","relearn":"Fair: everyone gets a turn, no one's left out, all have a say.","persona":"Ananya","source":"vision"},
  {"id":"fp-1374","cat":"what-is-fair","type":"reflect","hook":"Lensy: is it fair if your team makes up a rule mid-game so you win?","prompt":"What do you think?","options":["No","That's not fair","We agreed before"],"affirm":"Changing rules just to win isn't fair to the others.","relearn":"Fair means rules are agreed, not bent so I win.","persona":"any","source":"fairness"},
  {"id":"fp-1375","cat":"what-is-fair","type":"strike-rewrite","hook":"\"Fair means everyone gets the exact same thing.\"","myth":{"un":"Fair always means everyone gets exactly the same.","re":"Fair can mean each one getting what they need.","why":"A shorter kid may need a box to see the same match."},"relearn":"Fair isn't always the same; sometimes it's each one's need.","persona":"Kabir-type","source":"equity preview"},
  {"id":"fp-1376","cat":"what-is-fair","type":"strike-rewrite","hook":"\"Fairness means I win because I asked first.\"","myth":{"un":"Fair means whoever asks first wins.","re":"Fair means everyone gets a turn or a share.","why":"Asking first doesn't make a thing only yours."},"relearn":"Fair is a turn for all, not first-come-takes-all.","persona":"any","source":"fairness"},
  {"id":"fp-1377","cat":"what-is-fair","type":"strike-rewrite","hook":"\"Some kids just don't matter as much.\"","myth":{"un":"Some kids don't really matter as much.","re":"Everyone matters, so fair means no one is left out.","why":"A group is fair only when it counts everyone."},"relearn":"Fairness means everyone matters; no one is left out.","persona":"any","source":"inclusion"},
  {"id":"fp-1378","cat":"what-is-fair","type":"strike-rewrite","hook":"\"Once a rule is made, it can never change.\"","myth":{"un":"A rule can never be changed once it's made.","re":"People can change an unfair rule into a fairer one.","why":"Rules are made by people and can be improved."},"relearn":"Unfair rules can be changed to fairer ones.","persona":"Ananya","source":"rules / agency"},
  {"id":"fp-1379","cat":"what-is-fair","type":"strike-rewrite","hook":"\"Asking 'is that fair?' just makes trouble.\"","myth":{"un":"Asking \"is that fair?\" only makes trouble.","re":"Asking \"is that fair?\" is a good question worth asking.","why":"Naming a problem is the first step to fixing it."},"relearn":"\"Is that fair?\" is worth asking, not trouble-making.","persona":"Ananya","source":"agency / voice"},
  {"id":"fp-1380","cat":"what-is-fair","type":"strike-rewrite","hook":"\"Sharing the swing means I get less fun.\"","myth":{"un":"Sharing means I just get less for myself.","re":"Sharing the turn means everyone, including you, gets a fair go.","why":"You still get your turn; so does everyone else."},"relearn":"Sharing turns is fair and you still get your go.","persona":"any","source":"sharing"},
  {"id":"fp-1381","cat":"what-is-fair","type":"strike-rewrite","hook":"\"There's only ever one right way to be fair.\"","myth":{"un":"There's only one right way to be fair.","re":"There can be more than one fair move; you reason it out.","why":"Splitting, taking turns, or a say can all be fair."},"relearn":"More than one move can be fair; you decide which fits.","persona":"any","source":"fairness / reasoning"},
  {"id":"fp-1382","cat":"what-is-fair","type":"strike-rewrite","hook":"\"If I'm winning, the rules must be fair.\"","myth":{"un":"If I'm winning, the rules must already be fair.","re":"A rule is fair only if it gives everyone a turn.","why":"A rule can help you and still shut others out."},"relearn":"Fair rules give everyone a turn, not just the winner.","persona":"Ananya","source":"fair process"},
  {"id":"fp-1383","cat":"what-is-fair","type":"branch","hook":"You and a friend both want the one new library book first.","options":[{"text":"Decide a fair turn: one reads it, then the other","consequence":"You both get the book; it feels fair to share.","outcome":"fair","best":true},{"text":"Grab it and keep it for weeks","consequence":"You read it, but your friend never gets a fair turn.","outcome":"unfair"}],"debrief":"Taking turns lets you both enjoy the one book fairly.","relearn":"Fair means everyone gets a turn, even with one book.","persona":"any","source":"sharing / fairness"},
  {"id":"fp-1384","cat":"what-is-fair","type":"branch","hook":"Your group always plays what you want; one kid never gets a say.","options":[{"text":"Ask, \"what does everyone feel like today?\"","consequence":"The quiet kid picks; the group tries something new.","outcome":"fair","best":true},{"text":"Pick your favourite again","consequence":"One kid keeps missing out on a fair say.","outcome":"unfair"}],"debrief":"Fair is about everyone's say, not just yours.","relearn":"Fair is about everyone, not just me getting my way.","persona":"any","source":"fairness"},
  {"id":"fp-1385","cat":"what-is-fair","type":"branch","hook":"A smaller kid can't reach the high shelf to join the craft.","options":[{"text":"Pass them a stool so they can reach too","consequence":"Now they can join; same craft, a little help.","outcome":"equity","best":true},{"text":"Say, \"reach it yourself like the rest\"","consequence":"They're left out when a small help would include them.","outcome":"unfair"}],"debrief":"Fair can mean a small help so everyone can take part.","relearn":"Fair isn't always the same; it's each getting what they need.","persona":"Kabir-type","source":"equity / inclusion"},
  {"id":"fp-1386","cat":"what-is-fair","type":"branch","hook":"The class has a rule, \"new pencils only for the front row.\"","options":[{"text":"Ask the teacher if everyone could get one fairly","consequence":"The rule changes; all rows get pencils.","outcome":"fair","best":true},{"text":"Decide nothing can be done about it","consequence":"The unfair rule stays, though it could be changed.","outcome":"stuck"}],"debrief":"Unfair rules can be changed once you ask, kindly.","relearn":"People can change an unfair rule to a fairer one.","persona":"Ananya","source":"rules / agency"},
  {"id":"fp-1387","cat":"what-is-fair","type":"branch","hook":"You notice only your close friends ever get the spare cricket bat.","options":[{"text":"Say, \"let's lend it to whoever's waiting\"","consequence":"Everyone gets a fair turn; more kids join the game.","outcome":"fair","best":true},{"text":"Keep it among your friends","consequence":"Other kids never get a turn; that's hogging.","outcome":"unfair"}],"debrief":"\"Only my friends get any\" isn't fair; sharing the turn is.","relearn":"Hogging among friends isn't fair; sharing the turn is.","persona":"any","source":"sharing / fairness"},
  {"id":"fp-1388","cat":"what-is-fair","type":"branch","hook":"Two of you want the window seat on the bus every single day.","options":[{"text":"Take turns: window one day, aisle the next","consequence":"You both get the window fairly; no daily fight.","outcome":"fair","best":true},{"text":"Race to grab it first each time","consequence":"The faster one always wins; that's not really fair.","outcome":"unfair"}],"debrief":"Taking turns is a fair fix when you both want one thing.","relearn":"Splitting or taking turns is a fair fix.","persona":"any","source":"fairness"},
  {"id":"fp-1389","cat":"what-is-fair","type":"branch","hook":"In a group game, you spot a rule that lets one kid never lose.","options":[{"text":"Suggest a rule that gives everyone a fair chance","consequence":"The game's fun again; everyone has a shot.","outcome":"fair","best":true},{"text":"Leave the lopsided rule alone","consequence":"One kid always wins; the rest stop wanting to play.","outcome":"unfair"}],"debrief":"A fair rule gives everyone a real chance, not one kid always.","relearn":"Fair rules give everyone a chance; unfair ones favour a few.","persona":"Ananya","source":"fair process"},
  {"id":"fp-1390","cat":"what-is-fair","type":"branch","hook":"Your friend asks, \"is it fair that only I tidy our shared desk?\"","options":[{"text":"Say, \"good question! Let's take turns tidying\"","consequence":"You share it; your friend feels heard and it's fair.","outcome":"fair","best":true},{"text":"Tell them to stop complaining","consequence":"A fair question gets brushed off; the unfairness stays.","outcome":"unfair"}],"debrief":"\"Is that fair?\" is worth taking seriously, not brushing off.","relearn":"\"Is that fair?\" is a question worth asking.","persona":"any","source":"agency / voice"},
  {"id":"fp-1391","cat":"what-is-fair","type":"branch","hook":"At a birthday, there are six laddoos and seven kids.","options":[{"text":"Break two laddoos so everyone gets a fair share","consequence":"All seven kids get some; no one's left out.","outcome":"fair","best":true},{"text":"Give them out till they run out","consequence":"The last kid gets none; that doesn't feel fair.","outcome":"unfair"}],"debrief":"A fair share can mean splitting so no one is left out.","relearn":"Fairness means no one is left out; everyone gets a share.","persona":"any","source":"sharing / inclusion"},
  {"id":"fp-1392","cat":"what-is-fair","type":"branch","hook":"Your little cousin can't run as fast in the relay yet.","options":[{"text":"Give them a shorter stretch so they can join","consequence":"They run, laughing; the race is fair and fun.","outcome":"equity","best":true},{"text":"Make them run the same long stretch","consequence":"They fall behind and feel left out.","outcome":"unfair"}],"debrief":"Fair can mean a fitting adjustment so everyone joins in.","relearn":"Fair isn't always the same; it's each getting what they need.","persona":"Kabir-type","source":"equity / inclusion"},
  {"id":"fp-1393","cat":"what-is-fair","type":"branch","hook":"You realise you took a bigger share of the chips without thinking.","options":[{"text":"Even it out so everyone has a fair amount","consequence":"You fix it; the share feels fair to all.","outcome":"fair","best":true},{"text":"Eat it quickly before anyone notices","consequence":"You got more, but it wasn't a fair share.","outcome":"unfair"}],"debrief":"Fair means noticing and evening out an uneven share.","relearn":"Fair usually means everyone gets a turn or a share.","persona":"any","source":"fairness"},
  {"id":"fp-1394","cat":"what-is-fair","type":"match","hook":"Match the fair idea to what it means.","pairs":[{"left":"A turn for everyone","right":"No one is skipped"},{"left":"Fair ≠ always the same","right":"Each gets what they need"},{"left":"Rules can change","right":"People can make them fairer"},{"left":"\"Is that fair?\"","right":"A good question to ask"},{"left":"Fair is for all","right":"Not just me getting my way"}],"relearn":"Fairness: a turn for all, meeting needs, changeable rules, asking why.","persona":"any","source":"fairness / definitions"},
  {"id":"fp-1395","cat":"what-is-fair","type":"match","hook":"Match the situation to its fair fix.","pairs":[{"left":"One cycle, three kids waiting","right":"Take turns"},{"left":"One big watermelon","right":"Equal slices"},{"left":"A kid who can't see over the wall","right":"A box to stand on"},{"left":"Only one kid ever chooses","right":"Rotate who chooses"},{"left":"A book everyone wants","right":"A turn-list"}],"relearn":"Different situations have fair fixes: turns, equal shares, a box, a list.","persona":"any","source":"fairness / problem-solving"},
  {"id":"fp-1396","cat":"what-is-fair","type":"match","hook":"Match the unfair move to a fairer one.","pairs":[{"left":"Hogging the swing","right":"Take turns on it"},{"left":"\"Only my way\"","right":"Ask what all want"},{"left":"Leaving one kid out","right":"Make room for them"},{"left":"Bending the rule to win","right":"Keep the agreed rule"},{"left":"\"Nothing can change\"","right":"Ask to make it fairer"}],"relearn":"Every unfair move has a fairer one you can choose instead.","persona":"any","source":"fairness / reasoning"},
  {"id":"fp-1397","cat":"what-is-fair","type":"match","hook":"Match what a friend says to what fair really means.","pairs":[{"left":"\"I asked first, it's mine\"","right":"Everyone still gets a turn"},{"left":"\"Same for all, always\"","right":"Or what each one needs"},{"left":"\"That kid doesn't count\"","right":"Everyone matters"},{"left":"\"This rule can't change\"","right":"People can make it fairer"},{"left":"\"Only one fair answer\"","right":"More than one can be fair"}],"relearn":"Fair: a turn for all, needs met, all matter, rules change, many fair moves.","persona":"any","source":"fairness / definitions"},
  {"id":"fp-1398","cat":"what-is-fair","type":"match","hook":"Match the place to a fair move there.","pairs":[{"left":"At the water tap","right":"Wait your turn in line"},{"left":"Sharing one phone","right":"Take timed turns"},{"left":"Picking a class game","right":"Let everyone vote"},{"left":"A shorter friend can't see","right":"Pass them a stool"},{"left":"One kid always last-picked","right":"Mix up the teams"}],"relearn":"A fair move fits the place: turns, votes, a stool, mixed teams.","persona":"any","source":"fairness / transfer"},
  {"id":"fp-1399","cat":"what-is-fair","type":"build","hook":"Build a fair way to share the one classroom tablet.","prompt":"Pick the pieces that make it fair.","pieces":["a timed turn for each","a turn-list everyone can see","help for a kid who's stuck","skip whoever you dislike","whoever grabs it keeps it"],"mode":"assemble","key":["a timed turn for each","a turn-list everyone can see","help for a kid who's stuck"],"relearn":"A fair share: timed turns, a visible list, and help where it's needed.","persona":"any","source":"fair systems"},
  {"id":"fp-1400","cat":"what-is-fair","type":"build","hook":"Build the meaning of the word \"fair\".","prompt":"Pick the pieces that belong in \"fair\".","pieces":["everyone gets a turn","no one is left out","each gets what they need","only I get my way","the loudest decides"],"mode":"assemble","key":["everyone gets a turn","no one is left out","each gets what they need"],"relearn":"Fair: everyone gets a turn, no one left out, each gets what they need.","persona":"Ananya","source":"fairness / definitions"},
  {"id":"fp-1401","cat":"what-is-fair","type":"build","hook":"Build a fair plan for a game where everyone wants to go first.","prompt":"Pick the steps that make it fair.","pieces":["draw lots for first turn","then take turns in order","let a stuck kid get help","let only friends play","change rules so you win"],"mode":"sequence","key":["draw lots for first turn","then take turns in order","let a stuck kid get help"],"relearn":"A fair plan: random first turn, then turns in order, with help to join.","persona":"any","source":"fair process"},
  {"id":"fp-1402","cat":"what-is-fair","type":"build","hook":"Build a fair way to split a tiffin among four friends.","prompt":"Pick what keeps it fair.","pieces":["count the pieces first","share them out evenly","check no one's left out","take the most yourself","hide some for later"],"mode":"sequence","key":["count the pieces first","share them out evenly","check no one's left out"],"relearn":"Fair sharing: count first, split evenly, and check no one's left out.","persona":"any","source":"sharing / fairness"},
  {"id":"fp-1403","cat":"what-is-fair","type":"build","hook":"Build a fair-turn chart for the one new football at break.","prompt":"Pick what makes the chart fair.","pieces":["a turn for each group","a clear order on it","a swap if a kid's away","first pick for the captain only","skip the new kids"],"mode":"assemble","key":["a turn for each group","a clear order on it","a swap if a kid's away"],"relearn":"A fair chart: a turn for each, a clear order, room to swap.","persona":"any","source":"fair systems"},
  {"id":"fp-1404","cat":"what-is-fair","type":"build","hook":"Build a fair rule when two kids both want to be line-leader.","prompt":"Pick the fair pieces.","pieces":["take turns each day","write the order down","let everyone get a go","keep it for one kid","pick by who's loudest"],"mode":"assemble","key":["take turns each day","write the order down","let everyone get a go"],"relearn":"A fair rule: take turns, write the order, everyone gets a go.","persona":"Ananya","source":"fair process"},
  {"id":"fp-1405","cat":"what-is-fair","type":"build","hook":"Build the steps to fix something that wasn't shared fairly.","prompt":"Put the fair steps in order.","pieces":["notice it wasn't fair","say it kindly out loud","agree a fairer way together","blame one person loudly","pretend you didn't see"],"mode":"sequence","key":["notice it wasn't fair","say it kindly out loud","agree a fairer way together"],"relearn":"Fixing unfairness: notice it, say it kindly, agree a fairer way.","persona":"Ananya","source":"agency / fair process"},
  {"id":"fp-1406","cat":"what-is-fair","type":"role-play","hook":"Two of you reach the last cold drink at the same time.","setup":"Say something fair. Say:","yourLine":[{"text":"\"Let's share it or take turns next time.\"","best":true},{"text":"\"I touched it first, so it's mine.\""}],"relearn":"Offering to share or take turns is the fair move.","persona":"any","source":"sharing / voice"},
  {"id":"fp-1407","cat":"what-is-fair","type":"role-play","hook":"Your group keeps picking only what you like to play.","setup":"Open it up fairly. Say:","yourLine":[{"text":"\"What does everyone feel like playing today?\"","best":true},{"text":"\"We'll just play my game again.\""}],"relearn":"Asking what everyone wants makes the choice fair.","persona":"any","source":"fairness / voice"},
  {"id":"fp-1408","cat":"what-is-fair","type":"role-play","hook":"A friend says the team rule feels unfair but is scared to ask.","setup":"Back the question. Say:","yourLine":[{"text":"\"It's okay to ask. Is this rule fair to all?\"","best":true},{"text":"\"Don't ask, you'll get in trouble.\""}],"relearn":"\"Is that fair?\" is a fine question to ask out loud.","persona":"Ananya","source":"agency / voice"},
  {"id":"fp-1409","cat":"what-is-fair","type":"role-play","hook":"A shorter kid can't see the board game on the high table.","setup":"Offer a fair fix. Say:","yourLine":[{"text":"\"Here, take this stool so you can see too.\"","best":true},{"text":"\"Not my problem you're short.\""}],"relearn":"Offering what someone needs to join in is fair.","persona":"Kabir-type","source":"equity / voice"},
  {"id":"fp-1410","cat":"what-is-fair","type":"role-play","hook":"Someone says the duty roster can never be changed.","setup":"Speak up calmly. Say:","yourLine":[{"text":"\"We made the rule, so we can make it fairer.\"","best":true},{"text":"\"I guess we're stuck with it forever.\""}],"relearn":"Rules made by people can be made fairer by people.","persona":"Ananya","source":"rules / voice"},
  {"id":"fp-1411","cat":"what-is-fair","type":"role-play","hook":"One kid is always left out when sides are picked.","setup":"Make it fair. Say:","yourLine":[{"text":"\"Let's mix the teams so everyone's in.\"","best":true},{"text":"\"They can just watch again.\""}],"relearn":"Including everyone in the teams is the fair move.","persona":"any","source":"inclusion / voice"},
  {"id":"fp-1412","cat":"what-is-fair","type":"role-play","hook":"You realise the made-up rule helps only your side win.","setup":"Be fair, even though it costs you. Say:","yourLine":[{"text":"\"Let's use a rule that's fair for both sides.\"","best":true},{"text":"\"Keep it. I like winning.\""}],"relearn":"A fair rule works for everyone, not just my side.","persona":"any","source":"fair process / voice"},
  {"id":"fp-1413","cat":"what-is-fair","type":"role-play","hook":"A friend insists fair must mean the exact same for all.","setup":"Explain gently. Say:","yourLine":[{"text":"\"Sometimes fair is each getting what they need.\"","best":true},{"text":"\"Yeah, fair is always identical.\""}],"relearn":"Fair isn't always the same; sometimes it's meeting a need.","persona":"Kabir-type","source":"equity / voice"},
  {"id":"fp-1414","cat":"what-is-fair","type":"sort","hook":"Sort: fair to all, or unfair to some, at the class party?","items":[{"id":"a","text":"Every kid gets one balloon"},{"id":"b","text":"Some kids get none"},{"id":"c","text":"Drawing names for the first slice"},{"id":"d","text":"Best friends get double cake"},{"id":"e","text":"Asking who hasn't been served"},{"id":"f","text":"Skipping the new kid on purpose"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"no","label":"Not fair","valence":"neg"}],"key":{"a":"fair","b":"no","c":"fair","d":"no","e":"fair","f":"no"},"relearn":"Fair means everyone gets a share; no one is left out.","persona":"any","source":"sharing / inclusion"},
  {"id":"fp-1415","cat":"what-is-fair","type":"match","hook":"Match the kid's worry to the fair answer.","pairs":[{"left":"\"I never get to go first\"","right":"Let's take turns first"},{"left":"\"They got more than me\"","right":"Let's share it evenly"},{"left":"\"No one asks what I want\"","right":"Everyone gets a say"},{"left":"\"I can't reach to join\"","right":"Here's a stool"},{"left":"\"This rule's not fair\"","right":"We can change it"}],"relearn":"Each fairness worry has a fair answer: turns, sharing, a say, help, change.","persona":"any","source":"fairness / problem-solving"},
  {"id":"fp-1416","cat":"what-is-fair","type":"match","hook":"Match the fairness word to a simple example.","pairs":[{"left":"A turn for all","right":"Each kid bats once"},{"left":"A fair share","right":"Equal bits of barfi"},{"left":"What you need","right":"Glasses for who can't see"},{"left":"No one left out","right":"The new kid joins in"},{"left":"A changeable rule","right":"We vote to fix it"}],"relearn":"Fairness in examples: a turn, a share, a need met, all in, rules change.","persona":"any","source":"fairness / definitions"},
];

